CREATE OR REPLACE FUNCTION private.acquisition_buyer_index(p_workspace uuid, p_after uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 25)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE expires timestamptz; rows jsonb; items jsonb; next_id uuid; enabled boolean;
BEGIN
 IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 50 THEN RAISE EXCEPTION 'Bounded buyer page required' USING ERRCODE='22023'; END IF;
 expires:=private.lock_acquisition_buyer_reader(p_workspace);
 SELECT coalesce(jsonb_agg(to_jsonb(page) ORDER BY page.buyer_id),'[]') INTO rows FROM (
  SELECT b.id AS buyer_id,b.acquisition_revision AS revision,v.details->>'first_name' AS first_name,
   v.details->>'last_name' AS last_name,v.details->>'company' AS company,(v.details->>'active')::boolean AS active,
   false AS buyer_verified
  FROM public.buyers b JOIN private.acquisition_buyer_versions v ON v.workspace_id=b.workspace_id AND v.buyer_id=b.id AND v.revision=b.acquisition_revision
  WHERE b.workspace_id=p_workspace AND (p_after IS NULL OR b.id>p_after) ORDER BY b.id LIMIT p_limit+1
 ) page;
 SELECT coalesce(jsonb_agg(value ORDER BY ordinality),'[]') INTO items FROM jsonb_array_elements(rows) WITH ORDINALITY WHERE ordinality<=p_limit;
 IF jsonb_array_length(rows)>p_limit THEN next_id:=(items->(p_limit-1)->>'buyer_id')::uuid; END IF;
 SELECT a.enabled INTO enabled FROM private.acquisition_activation a WHERE singleton;
 IF expires IS NOT NULL AND expires<=clock_timestamp() THEN RAISE EXCEPTION 'Buyer session expired' USING ERRCODE='42501'; END IF;
 RETURN jsonb_build_object('workspace_id',p_workspace,'items',items,'next_cursor',next_id,'checked_at',clock_timestamp(),
  'can_save',coalesce(enabled,false),'contact_authorized',false,'execution_authorized',false);
END $function$

CREATE OR REPLACE FUNCTION private.acquisition_buyer_profile(p_workspace uuid, p_buyer uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE expires timestamptz; result jsonb; enabled boolean;
BEGIN
 IF p_buyer IS NULL THEN RAISE EXCEPTION 'Buyer identity required' USING ERRCODE='22023'; END IF;
 expires:=private.lock_acquisition_buyer_reader(p_workspace);
 SELECT a.enabled INTO enabled FROM private.acquisition_activation a WHERE singleton;
 SELECT jsonb_build_object('workspace_id',b.workspace_id,'buyer_id',b.id,'revision',b.acquisition_revision,'details',v.details,
  'checked_at',clock_timestamp(),'can_save',coalesce(enabled,false),'buyer_verified',false,'contact_authorized',false,'execution_authorized',false)
 INTO result FROM public.buyers b JOIN private.acquisition_buyer_versions v
  ON v.workspace_id=b.workspace_id AND v.buyer_id=b.id AND v.revision=b.acquisition_revision
 WHERE b.workspace_id=p_workspace AND b.id=p_buyer;
 IF expires IS NOT NULL AND expires<=clock_timestamp() THEN RAISE EXCEPTION 'Buyer session expired' USING ERRCODE='42501'; END IF;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION private.acquisition_evidence_candidates(p_workspace uuid, p_campaign uuid, p_purpose text, p_after uuid, p_limit integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE policy jsonb; items jsonb; candidate record; next_after uuid; last_id uuid; seen integer:=0;
BEGIN
 IF auth.jwt()->>'aal' IS DISTINCT FROM 'aal2' OR coalesce(private.acquisition_role(p_workspace),'') NOT IN ('owner','admin','operator') THEN
  RAISE EXCEPTION 'Evidence discovery authority required' USING ERRCODE='42501'; END IF;
 IF p_purpose IS NULL OR p_purpose NOT IN ('mail_content','mail_destination') OR p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 50 THEN
  RAISE EXCEPTION 'Bounded evidence purpose and page required' USING ERRCODE='22023'; END IF;
 PERFORM 1 FROM public.ad_campaigns WHERE workspace_id=p_workspace AND id=p_campaign AND acquisition_channel='direct_mail';
 IF NOT FOUND THEN RAISE EXCEPTION 'Mail campaign unavailable' USING ERRCODE='42501'; END IF;
 -- Discovery works while activation is paused and for historical campaigns. Registration rechecks all write gates.
 SELECT jsonb_build_object('id',id,'workspace_id',workspace_id,'purpose',purpose,'version',version,'retention_seconds',retention_seconds,'valid_from',valid_from,'valid_until',valid_until)
 INTO policy FROM private.acquisition_evidence_policies WHERE workspace_id=p_workspace AND purpose=p_purpose
  AND revoked_at IS NULL AND valid_from<=statement_timestamp() AND valid_until>statement_timestamp()
 ORDER BY version DESC LIMIT 1;
 items:='[]'::jsonb;
 FOR candidate IN SELECT id FROM public.acquisition_evidence_artifacts
  WHERE workspace_id=p_workspace AND campaign_id=p_campaign AND purpose=p_purpose AND (p_after IS NULL OR id>p_after)
  ORDER BY id LIMIT p_limit+1 LOOP
  seen:=seen+1;
  IF seen>p_limit THEN next_after:=last_id; EXIT; END IF;
  items:=items||jsonb_build_array(private.acquisition_evidence_state(p_workspace,p_campaign,candidate.id));
  last_id:=candidate.id;
 END LOOP;
 RETURN jsonb_build_object('workspace_id',p_workspace,'campaign_id',p_campaign,'purpose',p_purpose,
  'current_policy',policy,'items',items,'next_after',next_after,'checked_at',statement_timestamp(),'execution_authorized',false);
END $function$

CREATE OR REPLACE FUNCTION private.acquisition_evidence_review_candidate(p_workspace uuid, p_campaign uuid, p_artifact uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE artifact public.acquisition_evidence_artifacts%ROWTYPE; observation public.acquisition_evidence_verifications%ROWTYPE;
 deadline timestamptz; checked timestamptz:=statement_timestamp();
BEGIN
 IF auth.jwt()->>'role' IS DISTINCT FROM 'authenticated' OR auth.jwt()->>'aal' IS DISTINCT FROM 'aal2'
  OR coalesce(private.acquisition_role(p_workspace),'') NOT IN ('owner','admin') THEN
  RAISE EXCEPTION 'Content reviewer with MFA required' USING ERRCODE='42501'; END IF;
 SELECT * INTO artifact FROM public.acquisition_evidence_artifacts WHERE workspace_id=p_workspace AND campaign_id=p_campaign AND id=p_artifact;
 IF NOT FOUND OR artifact.purpose<>'mail_content' THEN RAISE EXCEPTION 'Review file unavailable' USING ERRCODE='42501'; END IF;
 SELECT * INTO observation FROM public.acquisition_evidence_verifications
  WHERE workspace_id=p_workspace AND campaign_id=p_campaign AND artifact_id=p_artifact ORDER BY created_at DESC,id DESC LIMIT 1;
 IF NOT FOUND OR NOT private.acquisition_content_evidence_current(p_workspace,p_campaign,p_artifact,artifact.expected_sha256,observation.id,checked) THEN
  RAISE EXCEPTION 'Current verified file required' USING ERRCODE='55000'; END IF;
 SELECT least(artifact.retain_until,policy.valid_until,k.valid_until,session.not_after) INTO deadline
  FROM private.acquisition_evidence_verification_keys k
  JOIN private.acquisition_evidence_policies policy ON policy.id=artifact.retention_policy_id AND policy.workspace_id=p_workspace
  JOIN auth.sessions session ON session.id=observation.session_id AND session.user_id=observation.actor_id
  WHERE k.id=observation.key_id AND k.workspace_id=p_workspace;
 IF deadline IS NULL OR deadline<=checked THEN RAISE EXCEPTION 'Review file expired' USING ERRCODE='55000'; END IF;
 RETURN jsonb_build_object('workspace_id',p_workspace,'campaign_id',p_campaign,'artifact_id',p_artifact,
  'sha256',artifact.expected_sha256,'verification_id',observation.id,'status','review_candidate',
  'max_approval_until',deadline,'checked_at',checked,'preview_authorized',false,'content_approved',false,'execution_authorized',false);
END $function$

CREATE OR REPLACE FUNCTION private.acquisition_evidence_state(p_workspace uuid, p_campaign uuid, p_artifact uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE artifact public.acquisition_evidence_artifacts%ROWTYPE; revocation public.acquisition_evidence_revocations%ROWTYPE; policy_current boolean;
BEGIN
 IF coalesce(private.acquisition_role(p_workspace),'') NOT IN ('owner','admin','operator') THEN
  RAISE EXCEPTION 'Evidence access denied' USING ERRCODE='42501'; END IF;
 SELECT * INTO artifact FROM public.acquisition_evidence_artifacts WHERE workspace_id=p_workspace AND campaign_id=p_campaign AND id=p_artifact;
 IF NOT FOUND THEN RAISE EXCEPTION 'Evidence artifact unavailable' USING ERRCODE='42501'; END IF;
 SELECT * INTO revocation FROM public.acquisition_evidence_revocations WHERE workspace_id=p_workspace AND artifact_id=p_artifact;
 SELECT revoked_at IS NULL AND valid_from<=statement_timestamp() AND valid_until>statement_timestamp() INTO policy_current
 FROM private.acquisition_evidence_policies WHERE id=artifact.retention_policy_id AND workspace_id=p_workspace AND purpose=artifact.purpose;
 RETURN jsonb_build_object('workspace_id',p_workspace,'campaign_id',p_campaign,'artifact_id',p_artifact,
  'purpose',artifact.purpose,'expected_sha256',artifact.expected_sha256,'expected_byte_size',artifact.expected_byte_size,
  'media_type',artifact.media_type,'created_at',artifact.created_at,'retain_until',artifact.retain_until,
  'retention_policy_id',artifact.retention_policy_id,'revoked_at',revocation.created_at,
  'status',CASE WHEN revocation.id IS NOT NULL THEN 'revoked' WHEN artifact.retain_until<=statement_timestamp() THEN 'expired'
   WHEN policy_current IS DISTINCT FROM true THEN 'policy_review_required' ELSE 'pending_verification' END,
  'bytes_verified',false,'content_approved',false,'execution_authorized',false,'checked_at',statement_timestamp());
END $function$

CREATE OR REPLACE FUNCTION private.acquisition_inbound_requests(p_workspace uuid, p_integration uuid, p_call text, p_after uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 20)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE rows jsonb;
BEGIN
 IF coalesce(private.acquisition_role(p_workspace),'') NOT IN ('owner','admin','operator') THEN RAISE EXCEPTION 'Inbound request read denied' USING ERRCODE='42501'; END IF;
 IF p_integration IS NULL OR p_call IS NULL OR p_call !~ '^[A-Za-z0-9_-]{1,200}$' OR p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 50 THEN RAISE EXCEPTION 'Invalid read bounds' USING ERRCODE='22023'; END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) INTO rows FROM (
  SELECT id,acquisition_revision,acquisition_request_kind,acquisition_evidence,acquisition_phone,acquisition_request_hash,created_at
  FROM public.tasks WHERE workspace_id=p_workspace AND acquisition_integration_id=p_integration AND acquisition_call_id=p_call
   AND (p_after IS NULL OR id>p_after) ORDER BY id LIMIT p_limit
 ) t;
 RETURN jsonb_build_object('workspace_id',p_workspace,'integration_id',p_integration,'call_id',p_call,'items',rows,'execution_authorized',false);
END $function$

CREATE OR REPLACE FUNCTION private.acquisition_renewal_snapshot(p_workspace uuid, p_contract uuid, p_version integer, p_root uuid, p_policy uuid, p_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
DECLARE original public.acquisition_contract_reviews%ROWTYPE; prior public.acquisition_contract_reviews%ROWTYPE;
 policy private.acquisition_contract_review_policies%ROWTYPE; scope private.acquisition_disposition_policy_scopes%ROWTYPE;
 a public.acquisition_evidence_artifacts%ROWTYPE; v public.acquisition_evidence_verifications%ROWTYPE;
 originals jsonb; item jsonb; sources jsonb:='[]'; supports jsonb; support_rows jsonb; snapshot jsonb;
 source_expiry timestamptz; seq integer;
BEGIN
 SELECT * INTO original FROM public.acquisition_contract_reviews WHERE workspace_id=p_workspace AND contract_id=p_contract
  AND contract_version=p_version AND id=p_root AND status='approved' AND renewal_root_id IS NULL;
 IF NOT FOUND THEN RAISE EXCEPTION 'Original renewal decision unavailable' USING ERRCODE='55000'; END IF;
 supports:=private.acquisition_renewal_review_set(p_workspace,p_contract,p_version,p_root,p_at);
 IF supports IS NULL THEN RAISE EXCEPTION 'Original renewal support unavailable' USING ERRCODE='55000'; END IF;
 SELECT * INTO prior FROM public.acquisition_contract_reviews WHERE id=private.acquisition_review_lineage_head(p_workspace,p_contract,p_version,p_root,p_at);
 SELECT max(sequence) INTO seq FROM public.acquisition_contract_reviews WHERE workspace_id=p_workspace AND contract_id=p_contract
  AND contract_version=p_version AND kind=original.kind;
 SELECT * INTO policy FROM private.acquisition_contract_review_policies WHERE workspace_id=p_workspace AND id=p_policy;
 IF NOT FOUND OR policy.kind<>original.kind OR policy.purpose<>original.purpose THEN
  RAISE EXCEPTION 'Matching renewal policy required' USING ERRCODE='55000'; END IF;
 originals:=coalesce(original.deadline_sources,'[]')||coalesce(original.execution_sources,'[]')||coalesce(original.title_sources,'[]')||coalesce(original.disposition_sources,'[]');
 FOR item IN SELECT DISTINCT value FROM jsonb_array_elements(originals) ORDER BY value LOOP
  SELECT * INTO a FROM public.acquisition_evidence_artifacts WHERE workspace_id=p_workspace AND contract_id=p_contract
   AND id=(item->>'artifact_id')::uuid AND contract_version=(item->>'source_version')::integer
   AND expected_sha256=item->>'sha256' AND purpose=item->>'purpose';
  IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM private.contract_document_reference(p_workspace,p_contract,p_version,a.id) ref
   WHERE ref.source_version=a.contract_version AND NOT ref.link_revoked) THEN
   RAISE EXCEPTION 'Unchanged retained renewal source required' USING ERRCODE='55000'; END IF;
  SELECT * INTO v FROM public.acquisition_evidence_verifications WHERE workspace_id=p_workspace AND artifact_id=a.id ORDER BY created_at DESC,id DESC LIMIT 1;
  IF NOT FOUND OR NOT private.contract_review_evidence_current(p_workspace,p_contract,a.contract_version,a.id,v.id,a.expected_sha256,a.purpose,p_at) THEN
   RAISE EXCEPTION 'Current retained renewal source verification required' USING ERRCODE='55000'; END IF;
  SELECT least(a.retain_until,rp.valid_until,k.valid_until,ks.valid_until,s.not_after) INTO source_expiry
   FROM private.acquisition_evidence_policies rp JOIN private.acquisition_evidence_verification_keys k ON k.workspace_id=rp.workspace_id AND k.id=v.key_id
   JOIN private.acquisition_contract_verification_key_scopes ks ON ks.workspace_id=k.workspace_id AND ks.key_id=k.id AND ks.purpose=a.purpose
   JOIN auth.sessions s ON s.id=v.session_id AND s.user_id=v.actor_id WHERE rp.workspace_id=p_workspace AND rp.id=a.retention_policy_id;
  IF source_expiry IS NULL OR source_expiry<=p_at THEN RAISE EXCEPTION 'Bounded renewal source authority required' USING ERRCODE='55000'; END IF;
  sources:=sources||jsonb_build_array(jsonb_build_object('artifact_id',a.id,'source_version',a.contract_version,'verification_id',v.id,
   'sha256',a.expected_sha256,'purpose',a.purpose,'expires_at',source_expiry));
 END LOOP;
 SELECT jsonb_agg(value ORDER BY value->>'artifact_id') INTO sources FROM jsonb_array_elements(sources);
 SELECT jsonb_agg(to_jsonb(r) ORDER BY r.id) INTO support_rows FROM public.acquisition_contract_reviews r
  WHERE r.workspace_id=p_workspace AND r.contract_id=p_contract AND r.contract_version=p_version
   AND r.id IN (SELECT (value->>'review_id')::uuid FROM jsonb_array_elements(supports));
 SELECT * INTO scope FROM private.acquisition_disposition_policy_scopes WHERE workspace_id=p_workspace AND policy_id=p_policy;
 snapshot:=jsonb_build_object('version','personal-review-renewal-v1','original',to_jsonb(original),'previous',to_jsonb(prior),
  'expected_sequence',seq,'policy',to_jsonb(policy),'disposition_scope',CASE WHEN original.kind='disposition_findings' THEN to_jsonb(scope) ELSE NULL END,
  'sources',sources,'supports',supports,'support_rows',support_rows);
 RETURN snapshot||jsonb_build_object('sha256',encode(sha256(convert_to(snapshot::text,'UTF8')),'hex'));
END $function$

CREATE OR REPLACE FUNCTION private.contract_document_candidates(p_workspace uuid, p_contract uuid, p_version integer, p_purpose text, p_after uuid, p_limit integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE policy jsonb; items jsonb; candidate record; next_after uuid; last_id uuid; seen integer:=0;
BEGIN
 IF auth.role() IS DISTINCT FROM 'authenticated' OR auth.jwt()->>'aal' IS DISTINCT FROM 'aal2' OR coalesce(private.acquisition_role(p_workspace),'') NOT IN ('owner','admin','operator') THEN
  RAISE EXCEPTION 'Evidence discovery authority required' USING ERRCODE='42501'; END IF;
 IF p_version IS NULL OR p_version<1 OR p_purpose IS NULL OR p_purpose NOT IN ('purchase_contract','title_report','assignment_agreement','seller_disclosure','assignee_disclosure','closing_statement','supporting_document') OR p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 50 THEN
  RAISE EXCEPTION 'Bounded evidence purpose and page required' USING ERRCODE='22023'; END IF;
 PERFORM 1 FROM public.acquisition_contract_versions WHERE workspace_id=p_workspace AND deal_id=p_contract AND version=p_version;
 IF NOT FOUND THEN RAISE EXCEPTION 'Contract version unavailable' USING ERRCODE='42501'; END IF;
 -- Discovery works while activation is paused and for historical contract versions. Registration rechecks all write gates.
 SELECT jsonb_build_object('id',id,'workspace_id',workspace_id,'purpose',purpose,'version',version,'retention_seconds',retention_seconds,'valid_from',valid_from,'valid_until',valid_until)
 INTO policy FROM private.acquisition_evidence_policies WHERE workspace_id=p_workspace AND purpose=p_purpose
  AND revoked_at IS NULL AND valid_from<=statement_timestamp() AND valid_until>statement_timestamp()
 ORDER BY version DESC LIMIT 1;
 items:='[]'::jsonb;
 FOR candidate IN SELECT id FROM public.acquisition_evidence_artifacts
  WHERE workspace_id=p_workspace AND campaign_id IS NULL AND contract_id=p_contract AND contract_version=p_version AND purpose=p_purpose AND (p_after IS NULL OR id>p_after)
  ORDER BY id LIMIT p_limit+1 LOOP
  seen:=seen+1;
  IF seen>p_limit THEN next_after:=last_id; EXIT; END IF;
  items:=items||jsonb_build_array(private.contract_document_state(p_workspace,p_contract,p_version,candidate.id));
  last_id:=candidate.id;
 END LOOP;
 RETURN jsonb_build_object('workspace_id',p_workspace,'contract_id',p_contract,'contract_version',p_version,'purpose',p_purpose,
  'current_policy',policy,'items',items,'next_after',next_after,'checked_at',statement_timestamp(),'execution_authorized',false);
END $function$

CREATE OR REPLACE FUNCTION private.contract_reference_candidates(p_workspace uuid, p_contract uuid, p_version integer, p_purpose text, p_after uuid, p_limit integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE candidate record; items jsonb:='[]'::jsonb; next_after uuid; last_id uuid; seen integer:=0;
BEGIN
 IF auth.role() IS DISTINCT FROM 'authenticated' OR auth.jwt()->>'aal' IS DISTINCT FROM 'aal2'
  OR coalesce(private.acquisition_role(p_workspace),'') NOT IN ('owner','admin','operator') THEN
  RAISE EXCEPTION 'Contract source discovery authority required' USING ERRCODE='42501'; END IF;
 IF p_purpose IS NULL OR p_purpose NOT IN ('purchase_contract','title_report','assignment_agreement','seller_disclosure','assignee_disclosure','closing_statement','supporting_document')
  OR p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 50 THEN RAISE EXCEPTION 'Bounded source purpose and page required' USING ERRCODE='22023'; END IF;
 PERFORM 1 FROM public.acquisition_contract_versions WHERE workspace_id=p_workspace AND deal_id=p_contract AND version=p_version;
 IF NOT FOUND THEN RAISE EXCEPTION 'Contract version unavailable' USING ERRCODE='42501'; END IF;
 -- One artifact row, even when several terms cite it. Withdrawn references remain
 -- discoverable for history and original-reviewer withdrawal, never approval.
 FOR candidate IN SELECT a.id,a.created_at FROM public.acquisition_evidence_artifacts a
  WHERE a.workspace_id=p_workspace AND a.contract_id=p_contract AND a.campaign_id IS NULL
   AND a.purpose=p_purpose AND a.contract_version<=p_version AND (p_after IS NULL OR a.id>p_after)
   AND EXISTS(SELECT 1 FROM private.contract_document_reference(p_workspace,p_contract,p_version,a.id))
  ORDER BY a.id LIMIT p_limit+1 LOOP
  seen:=seen+1;
  IF seen>p_limit THEN next_after:=last_id; EXIT; END IF;
  items:=items||jsonb_build_array(private.contract_reference_state(p_workspace,p_contract,p_version,candidate.id)
   ||jsonb_build_object('source_created_at',candidate.created_at));
  last_id:=candidate.id;
 END LOOP;
 RETURN jsonb_build_object('workspace_id',p_workspace,'contract_id',p_contract,'contract_version',p_version,'purpose',p_purpose,
  'items',items,'next_after',next_after,'checked_at',statement_timestamp(),'execution_authorized',false);
END $function$

CREATE OR REPLACE FUNCTION private.contract_reference_state(p_workspace uuid, p_contract uuid, p_version integer, p_artifact uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE ref record; artifact public.acquisition_evidence_artifacts%ROWTYPE; scan public.acquisition_evidence_verifications%ROWTYPE;
 checked timestamptz:=statement_timestamp(); source_state jsonb; status_name text;
BEGIN
 IF auth.role() IS DISTINCT FROM 'authenticated' OR auth.jwt()->>'aal' IS DISTINCT FROM 'aal2'
  OR coalesce(private.acquisition_role(p_workspace),'') NOT IN ('owner','admin','operator') THEN
  RAISE EXCEPTION 'Contract source authority required' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.acquisition_contract_versions WHERE workspace_id=p_workspace AND deal_id=p_contract AND version=p_version;
 IF NOT FOUND THEN RAISE EXCEPTION 'Contract version unavailable' USING ERRCODE='42501'; END IF;
 SELECT * INTO ref FROM private.contract_document_reference(p_workspace,p_contract,p_version,p_artifact);
 IF NOT FOUND THEN RAISE EXCEPTION 'Contract source unavailable' USING ERRCODE='42501'; END IF;
 source_state:=private.contract_document_state(p_workspace,p_contract,ref.source_version,p_artifact);
 SELECT * INTO artifact FROM public.acquisition_evidence_artifacts WHERE id=p_artifact;
 SELECT * INTO scan FROM public.acquisition_evidence_verifications WHERE workspace_id=p_workspace AND artifact_id=p_artifact ORDER BY created_at DESC,id DESC LIMIT 1;
 IF ref.link_revoked THEN status_name:='reference_withdrawn';
 ELSIF source_state->>'status'='revoked' THEN status_name:='source_revoked';
 ELSIF scan.id IS NULL OR NOT private.contract_review_evidence_current(p_workspace,p_contract,ref.source_version,p_artifact,scan.id,artifact.expected_sha256,artifact.purpose,checked) THEN status_name:='requires_review';
 ELSE status_name:='available_for_review'; END IF;
 RETURN jsonb_build_object('workspace_id',p_workspace,'contract_id',p_contract,'contract_version',p_version,'artifact_id',p_artifact,
  'source_version',ref.source_version,'reference_type',ref.reference_type,'link_id',ref.link_id,'status',status_name,
  'purpose',artifact.purpose,'sha256',artifact.expected_sha256,'verification_id',CASE WHEN status_name='available_for_review' THEN scan.id ELSE NULL END,
  'checked_at',checked,'review_approved',false,'execution_authorized',false);
END $function$

CREATE OR REPLACE FUNCTION private.contract_review_candidate(p_workspace uuid, p_contract uuid, p_version integer, p_kind text, p_artifact uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE checked timestamptz:=statement_timestamp(); state jsonb; purpose_name text; status_name text; source_ref record;
 artifact public.acquisition_evidence_artifacts%ROWTYPE; scan public.acquisition_evidence_verifications%ROWTYPE;
 policy private.acquisition_contract_review_policies%ROWTYPE; prior public.acquisition_contract_reviews%ROWTYPE;
 deadline timestamptz; candidate jsonb:=NULL; withdrawal jsonb:=NULL;
BEGIN
 -- Reuse owner/admin MFA, live membership/session and retained-version access.
 state:=private.contract_review_state(p_workspace,p_contract,p_version,p_kind);
 purpose_name:=CASE WHEN p_kind='title_review' THEN 'title_report' ELSE 'purchase_contract' END;
 SELECT * INTO source_ref FROM private.contract_document_reference(p_workspace,p_contract,p_version,p_artifact);
 IF NOT FOUND THEN RAISE EXCEPTION 'Review document reference unavailable' USING ERRCODE='42501'; END IF;
 SELECT * INTO artifact FROM public.acquisition_evidence_artifacts
  WHERE workspace_id=p_workspace AND contract_id=p_contract AND contract_version=source_ref.source_version
   AND id=p_artifact AND purpose=purpose_name AND campaign_id IS NULL;
 IF NOT FOUND THEN RAISE EXCEPTION 'Review document unavailable' USING ERRCODE='42501'; END IF;
 SELECT * INTO prior FROM public.acquisition_contract_reviews
  WHERE workspace_id=p_workspace AND contract_id=p_contract AND contract_version=p_version AND kind=p_kind
  ORDER BY sequence DESC LIMIT 1;
 IF prior.status='approved' AND prior.actor_id=auth.uid() AND prior.artifact_id=p_artifact THEN
  withdrawal:=jsonb_build_object('review_id',prior.id,'artifact_id',prior.artifact_id,
   'verification_id',prior.verification_id,'policy_id',prior.policy_id,'expected_sequence',prior.sequence);
 END IF;
 SELECT * INTO scan FROM public.acquisition_evidence_verifications
  WHERE workspace_id=p_workspace AND contract_id=p_contract AND contract_version=source_ref.source_version AND artifact_id=p_artifact
  ORDER BY created_at DESC,id DESC LIMIT 1;
 -- A deterministic most-recent reviewed policy; never creates or activates policy.
 SELECT * INTO policy FROM private.acquisition_contract_review_policies
  WHERE workspace_id=p_workspace AND kind=p_kind AND purpose=purpose_name AND reviewer_id=auth.uid()
   AND revoked_at IS NULL AND valid_from<=checked AND checked<valid_until
  ORDER BY valid_from DESC,id DESC LIMIT 1;
 IF NOT EXISTS(SELECT 1 FROM private.acquisition_activation WHERE singleton AND enabled) THEN status_name:='paused';
 ELSIF NOT EXISTS(SELECT 1 FROM public.deals WHERE id=p_contract AND workspace_id=p_workspace AND acquisition_version=p_version
   AND acquisition_status NOT IN ('closed','cancelled','expired')) THEN status_name:='contract_unavailable';
 ELSIF policy.id IS NULL THEN status_name:='reviewer_policy_required';
 ELSIF source_ref.link_revoked OR scan.id IS NULL OR NOT private.contract_review_evidence_current(p_workspace,p_contract,source_ref.source_version,p_artifact,scan.id,artifact.expected_sha256,purpose_name,checked)
  THEN status_name:='evidence_review_required';
 ELSE
  SELECT least(artifact.retain_until,rp.valid_until,k.valid_until,ks.valid_until,scanner_session.not_after,
    reviewer_session.not_after,policy.valid_until,checked+make_interval(secs=>policy.max_review_seconds)) INTO deadline
   FROM private.acquisition_evidence_verification_keys k
   JOIN private.acquisition_contract_verification_key_scopes ks ON ks.workspace_id=k.workspace_id AND ks.key_id=k.id AND ks.purpose=purpose_name
   JOIN private.acquisition_evidence_policies rp ON rp.workspace_id=k.workspace_id AND rp.id=artifact.retention_policy_id
   JOIN auth.sessions scanner_session ON scanner_session.id=scan.session_id AND scanner_session.user_id=scan.actor_id
   JOIN auth.sessions reviewer_session ON reviewer_session.id=(auth.jwt()->>'session_id')::uuid AND reviewer_session.user_id=auth.uid()
   WHERE k.workspace_id=p_workspace AND k.id=scan.key_id;
  IF deadline IS NULL OR deadline<=checked THEN status_name:='evidence_review_required';
  ELSE
   status_name:='ready_for_human_review';
   candidate:=jsonb_build_object('artifact_id',p_artifact,'verification_id',scan.id,'sha256',artifact.expected_sha256,
    'policy_id',policy.id,'max_expires_at',deadline,'expected_sequence',(state->>'sequence')::integer);
  END IF;
 END IF;
 RETURN jsonb_build_object('workspace_id',p_workspace,'contract_id',p_contract,'contract_version',p_version,'kind',p_kind,
  'artifact_id',p_artifact,'purpose',purpose_name,'status',status_name,'candidate',candidate,'withdrawal',withdrawal,
  'current_review',state,'checked_at',checked,'execution_authorized',false);
END $function$

CREATE OR REPLACE FUNCTION private.deadline_review_candidate(p_workspace uuid, p_contract uuid, p_version integer, p_term text, p_artifact uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE checked timestamptz:=statement_timestamp(); state jsonb; status_name text; source_ref record; prepared jsonb;
 artifact public.acquisition_evidence_artifacts%ROWTYPE; scan public.acquisition_evidence_verifications%ROWTYPE;
 policy private.acquisition_contract_review_policies%ROWTYPE; prior public.acquisition_contract_reviews%ROWTYPE;
 original_source public.acquisition_contract_term_sources%ROWTYPE; original_deadline timestamptz; source_choice jsonb:=NULL;
 deadline timestamptz; candidate jsonb:=NULL; withdrawal jsonb:=NULL;
BEGIN
 state:=private.deadline_review_state(p_workspace,p_contract,p_version,p_term);
 SELECT terms INTO prepared FROM public.acquisition_contract_versions WHERE workspace_id=p_workspace AND deal_id=p_contract AND version=p_version;
 SELECT * INTO source_ref FROM private.contract_document_reference(p_workspace,p_contract,p_version,p_artifact);
 IF NOT FOUND THEN RAISE EXCEPTION 'Interpretation source reference unavailable' USING ERRCODE='42501'; END IF;
 SELECT * INTO artifact FROM public.acquisition_evidence_artifacts WHERE workspace_id=p_workspace AND contract_id=p_contract
  AND contract_version=source_ref.source_version AND id=p_artifact AND purpose='purchase_contract' AND campaign_id IS NULL;
 IF NOT FOUND THEN RAISE EXCEPTION 'Interpretation source unavailable' USING ERRCODE='42501'; END IF;
 SELECT * INTO prior FROM public.acquisition_contract_reviews WHERE workspace_id=p_workspace AND contract_id=p_contract
  AND contract_version=p_version AND kind='deadline_resolution' AND deadline_term=p_term ORDER BY sequence DESC LIMIT 1;
 -- Withdrawal remains bound to the original review even if another file is selected.
 IF prior.status='approved' AND prior.actor_id=auth.uid() AND (state->>'sequence')::integer<2147483647 THEN
  withdrawal:=jsonb_build_object('review_id',prior.id,'artifact_id',prior.artifact_id,'source_version',prior.source_version,
   'verification_id',prior.verification_id,'policy_id',prior.policy_id,'expected_sequence',(state->>'sequence')::integer);
 END IF;
 SELECT * INTO original_source FROM public.acquisition_contract_term_sources
  WHERE workspace_id=p_workspace AND contract_id=p_contract AND contract_version=p_version AND term=p_term;
 IF FOUND THEN
  source_choice:=jsonb_build_object('term',p_term,'artifact_id',original_source.artifact_id,
   'artifact_version',original_source.artifact_version,'verification_id',original_source.verification_id,
   'sha256',original_source.sha256,'locator',original_source.locator);
  SELECT least(a.retain_until,rp.valid_until,k.valid_until,ks.valid_until,scanner_session.not_after) INTO original_deadline
  FROM public.acquisition_evidence_artifacts a
  JOIN public.acquisition_evidence_verifications v ON v.workspace_id=a.workspace_id AND v.artifact_id=a.id AND v.id=original_source.verification_id
  JOIN private.acquisition_evidence_policies rp ON rp.workspace_id=a.workspace_id AND rp.id=a.retention_policy_id
  JOIN private.acquisition_evidence_verification_keys k ON k.workspace_id=v.workspace_id AND k.id=v.key_id
  JOIN private.acquisition_contract_verification_key_scopes ks ON ks.workspace_id=k.workspace_id AND ks.key_id=k.id AND ks.purpose=a.purpose
  JOIN auth.sessions scanner_session ON scanner_session.id=v.session_id AND scanner_session.user_id=v.actor_id
  WHERE a.workspace_id=p_workspace AND a.contract_id=p_contract AND a.contract_version=original_source.artifact_version
   AND a.id=original_source.artifact_id AND a.expected_sha256=original_source.sha256
   AND EXISTS(SELECT 1 FROM private.contract_document_reference(p_workspace,p_contract,p_version,a.id) r
     WHERE r.source_version=original_source.artifact_version AND NOT r.link_revoked)
   AND private.contract_review_evidence_current(p_workspace,p_contract,original_source.artifact_version,a.id,v.id,original_source.sha256,a.purpose,checked);
 END IF;
 SELECT * INTO scan FROM public.acquisition_evidence_verifications WHERE workspace_id=p_workspace AND artifact_id=p_artifact ORDER BY created_at DESC,id DESC LIMIT 1;
 SELECT * INTO policy FROM private.acquisition_contract_review_policies WHERE workspace_id=p_workspace AND kind='deadline_resolution'
  AND purpose='purchase_contract' AND reviewer_id=auth.uid() AND revoked_at IS NULL AND valid_from<=checked AND checked<valid_until
  ORDER BY valid_from DESC,id DESC LIMIT 1;
 IF NOT EXISTS(SELECT 1 FROM private.acquisition_activation WHERE singleton AND enabled) THEN status_name:='paused';
 ELSIF NOT EXISTS(SELECT 1 FROM public.deals WHERE workspace_id=p_workspace AND id=p_contract AND acquisition_version=p_version AND acquisition_status='pending_signature') THEN status_name:='contract_unavailable';
 ELSIF (state->>'sequence')::integer>=2147483647 THEN status_name:='history_limit_reached';
 ELSIF prepared IS NULL OR NOT private.valid_contract_terms(prepared) THEN status_name:='prepared_terms_required';
 ELSIF prepared->p_term->>'precision' IS DISTINCT FROM 'date' THEN status_name:='original_date_required';
 ELSIF original_deadline IS NULL OR original_deadline<=checked THEN status_name:='original_evidence_review_required';
 ELSIF policy.id IS NULL THEN status_name:='reviewer_policy_required';
 ELSIF source_ref.link_revoked OR scan.id IS NULL OR NOT private.contract_review_evidence_current(p_workspace,p_contract,source_ref.source_version,p_artifact,scan.id,artifact.expected_sha256,'purchase_contract',checked) THEN status_name:='evidence_review_required';
 ELSE
  SELECT least(original_deadline,artifact.retain_until,rp.valid_until,k.valid_until,ks.valid_until,scanner_session.not_after,
   reviewer_session.not_after,policy.valid_until,checked+make_interval(secs=>policy.max_review_seconds)) INTO deadline
  FROM private.acquisition_evidence_verification_keys k
  JOIN private.acquisition_contract_verification_key_scopes ks ON ks.workspace_id=k.workspace_id AND ks.key_id=k.id AND ks.purpose='purchase_contract'
  JOIN private.acquisition_evidence_policies rp ON rp.workspace_id=k.workspace_id AND rp.id=artifact.retention_policy_id
  JOIN auth.sessions scanner_session ON scanner_session.id=scan.session_id AND scanner_session.user_id=scan.actor_id
  JOIN auth.sessions reviewer_session ON reviewer_session.id=(auth.jwt()->>'session_id')::uuid AND reviewer_session.user_id=auth.uid()
  WHERE k.workspace_id=p_workspace AND k.id=scan.key_id;
  IF deadline IS NULL OR deadline<=checked THEN status_name:='evidence_review_required';
  ELSE
   status_name:='ready_for_human_review';
   candidate:=jsonb_build_object('artifact_id',p_artifact,'source_version',source_ref.source_version,'verification_id',scan.id,
    'sha256',artifact.expected_sha256,'policy_id',policy.id,'max_expires_at',deadline,'expected_sequence',(state->>'sequence')::integer);
  END IF;
 END IF;
 RETURN jsonb_build_object('workspace_id',p_workspace,'contract_id',p_contract,'contract_version',p_version,'artifact_id',p_artifact,
  'term',p_term,'status',status_name,'candidate',candidate,'withdrawal',withdrawal,'original_source',source_choice,
  'current_review',state,'checked_at',checked,'execution_authorized',false);
END $function$

CREATE OR REPLACE FUNCTION private.disposition_source_choice(p_workspace uuid, p_contract uuid, p_version integer, p_artifact uuid, p_scan uuid, p_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
DECLARE ref record; artifact public.acquisition_evidence_artifacts%ROWTYPE;
 scan public.acquisition_evidence_verifications%ROWTYPE; deadline timestamptz;
BEGIN
 IF p_at IS NULL OR NOT isfinite(p_at) OR p_artifact IS NULL THEN RETURN NULL; END IF;
 SELECT * INTO ref FROM private.contract_document_reference(p_workspace,p_contract,p_version,p_artifact);
 IF NOT FOUND OR ref.link_revoked THEN RETURN NULL; END IF;
 SELECT * INTO artifact FROM public.acquisition_evidence_artifacts WHERE workspace_id=p_workspace AND contract_id=p_contract
  AND contract_version=ref.source_version AND id=p_artifact AND campaign_id IS NULL;
 IF NOT FOUND THEN RETURN NULL; END IF;
 SELECT * INTO scan FROM public.acquisition_evidence_verifications WHERE workspace_id=p_workspace AND artifact_id=p_artifact ORDER BY created_at DESC,id DESC LIMIT 1;
 IF NOT FOUND OR (p_scan IS NOT NULL AND scan.id<>p_scan) OR NOT private.contract_review_evidence_current(
  p_workspace,p_contract,ref.source_version,p_artifact,scan.id,artifact.expected_sha256,artifact.purpose,p_at) THEN RETURN NULL; END IF;
 SELECT least(artifact.retain_until,rp.valid_until,k.valid_until,ks.valid_until,s.not_after) INTO deadline
 FROM private.acquisition_evidence_policies rp
 JOIN private.acquisition_evidence_verification_keys k ON k.workspace_id=rp.workspace_id AND k.id=scan.key_id
 JOIN private.acquisition_contract_verification_key_scopes ks ON ks.workspace_id=k.workspace_id AND ks.key_id=k.id AND ks.purpose=artifact.purpose
 JOIN auth.sessions s ON s.id=scan.session_id AND s.user_id=scan.actor_id
 WHERE rp.workspace_id=p_workspace AND rp.id=artifact.retention_policy_id;
 IF deadline IS NULL OR deadline<=p_at THEN RETURN NULL; END IF;
 RETURN jsonb_build_object('artifact_id',artifact.id,'source_version',ref.source_version,'verification_id',scan.id,
  'sha256',artifact.expected_sha256,'purpose',artifact.purpose,'expires_at',deadline);
END $function$

