CREATE OR REPLACE FUNCTION private.link_contract_document(p_id uuid, p_workspace uuid, p_contract uuid, p_version integer, p_source_version integer, p_artifact uuid, p_verification uuid, p_sha256 text, p_note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE authority record; saved public.acquisition_contract_document_links%ROWTYPE; artifact public.acquisition_evidence_artifacts%ROWTYPE;
 scan public.acquisition_evidence_verifications%ROWTYPE; stamped timestamptz; active boolean;
BEGIN
 IF p_id IS NULL OR p_source_version IS NULL OR p_version IS NULL OR p_source_version<1 OR p_source_version>=p_version
  OR p_artifact IS NULL OR p_verification IS NULL OR p_sha256 IS NULL OR p_sha256 !~ '^[0-9a-f]{64}$'
  OR p_note IS NULL OR length(trim(p_note)) NOT BETWEEN 20 AND 4000 OR length(p_note)>4000 THEN
  RAISE EXCEPTION 'Exact earlier source and link note required' USING ERRCODE='22023'; END IF;
 SELECT * INTO authority FROM private.lock_contract_document_context(p_workspace,p_contract,p_version,ARRAY['owner','admin','operator']);
 PERFORM pg_advisory_xact_lock(hashtextextended('contract-document-link:'||p_id::text,0));
 IF authority.session_expires IS NOT NULL AND authority.session_expires<=clock_timestamp() THEN RAISE EXCEPTION 'Link session expired' USING ERRCODE='42501'; END IF;
 SELECT * INTO saved FROM public.acquisition_contract_document_links WHERE id=p_id;
 IF FOUND THEN
  IF (saved.workspace_id,saved.contract_id,saved.contract_version,saved.source_version,saved.artifact_id,saved.verification_id,saved.sha256,saved.note,saved.actor_id)
   IS DISTINCT FROM (p_workspace,p_contract,p_version,p_source_version,p_artifact,p_verification,p_sha256,p_note,auth.uid()) THEN
   RAISE EXCEPTION 'Document link request conflict' USING ERRCODE='23505'; END IF;
  RETURN jsonb_build_object('link_id',p_id,'workspace_id',p_workspace,'contract_id',p_contract,'contract_version',p_version,
   'source_version',p_source_version,'artifact_id',p_artifact,'duplicate',true,'review_approved',false,'execution_authorized',false);
 END IF;
 SELECT enabled INTO active FROM private.acquisition_activation WHERE singleton FOR SHARE;
 IF active IS DISTINCT FROM true OR NOT EXISTS(SELECT 1 FROM public.deals WHERE workspace_id=p_workspace AND id=p_contract AND acquisition_version=p_version AND acquisition_status='draft') THEN
  RAISE EXCEPTION 'Current active draft required' USING ERRCODE='55000'; END IF;
 IF EXISTS(SELECT 1 FROM public.acquisition_contract_term_sources WHERE workspace_id=p_workspace AND contract_id=p_contract AND contract_version=p_version AND artifact_id=p_artifact) THEN
  RAISE EXCEPTION 'Document already referenced by recorded terms' USING ERRCODE='55000'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-artifact:'||p_artifact::text,0));
 SELECT * INTO artifact FROM public.acquisition_evidence_artifacts WHERE workspace_id=p_workspace AND contract_id=p_contract AND contract_version=p_source_version AND id=p_artifact AND expected_sha256=p_sha256 AND campaign_id IS NULL;
 IF NOT FOUND THEN RAISE EXCEPTION 'Same-contract original source required' USING ERRCODE='42501'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-bytes:'||p_workspace::text||':'||p_sha256,0));
 SELECT * INTO scan FROM public.acquisition_evidence_verifications WHERE workspace_id=p_workspace AND artifact_id=p_artifact AND id=p_verification;
 IF NOT FOUND THEN RAISE EXCEPTION 'Exact source verification required' USING ERRCODE='55000'; END IF;
 PERFORM 1 FROM private.acquisition_evidence_verification_keys k
  JOIN private.acquisition_contract_verification_key_scopes ks ON ks.workspace_id=k.workspace_id AND ks.key_id=k.id AND ks.purpose=artifact.purpose
  JOIN private.acquisition_evidence_policies rp ON rp.workspace_id=k.workspace_id AND rp.id=artifact.retention_policy_id
  JOIN public.workspace_memberships m ON m.workspace_id=k.workspace_id AND m.user_id=scan.actor_id
  JOIN public.profiles profile ON profile.id=m.user_id JOIN auth.sessions sess ON sess.id=scan.session_id AND sess.user_id=m.user_id
  WHERE k.workspace_id=p_workspace AND k.id=scan.key_id FOR SHARE OF k,ks,rp,m,profile,sess;
 stamped:=clock_timestamp();
 IF authority.session_expires IS NOT NULL AND authority.session_expires<=stamped THEN RAISE EXCEPTION 'Link session expired' USING ERRCODE='42501'; END IF;
 IF NOT private.contract_review_evidence_current(p_workspace,p_contract,p_source_version,p_artifact,p_verification,p_sha256,artifact.purpose,stamped) THEN
  RAISE EXCEPTION 'Current verified original source required' USING ERRCODE='55000'; END IF;
 INSERT INTO public.acquisition_contract_document_links(id,workspace_id,contract_id,contract_version,source_version,artifact_id,verification_id,sha256,actor_id,session_id,note,created_at)
 VALUES(p_id,p_workspace,p_contract,p_version,p_source_version,p_artifact,p_verification,p_sha256,auth.uid(),(auth.jwt()->>'session_id')::uuid,p_note,stamped);
 INSERT INTO public.audit_logs(entity_type,entity_id,action,actor,workspace_id,new_value)
 VALUES('acquisition_contract_document_link',p_id::text,'linked',auth.uid()::text,p_workspace,
  jsonb_build_object('contract_id',p_contract,'contract_version',p_version,'source_version',p_source_version,'artifact_id',p_artifact,'verification_id',p_verification,'execution_authorized',false));
 RETURN jsonb_build_object('link_id',p_id,'workspace_id',p_workspace,'contract_id',p_contract,'contract_version',p_version,
  'source_version',p_source_version,'artifact_id',p_artifact,'duplicate',false,'review_approved',false,'execution_authorized',false);
END $function$

CREATE OR REPLACE FUNCTION private.lock_acquisition_content_evidence(p_workspace uuid, p_campaign uuid, p_artifact uuid, p_hash text, p_expires timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE artifact public.acquisition_evidence_artifacts%ROWTYPE; observation public.acquisition_evidence_verifications%ROWTYPE;
 deadline timestamptz; checked timestamptz;
BEGIN
 -- Invoked only by the owner/admin review transaction. Never exposed as an RPC.
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-artifact:'||p_artifact::text,0));
 SELECT * INTO artifact FROM public.acquisition_evidence_artifacts WHERE workspace_id=p_workspace AND campaign_id=p_campaign AND id=p_artifact;
 IF NOT FOUND OR artifact.expected_sha256 IS DISTINCT FROM p_hash OR artifact.purpose<>'mail_content' THEN
  RAISE EXCEPTION 'Registered content evidence required' USING ERRCODE='55000'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-bytes:'||p_workspace::text||':'||artifact.expected_sha256,0));
 SELECT * INTO observation FROM public.acquisition_evidence_verifications
  WHERE workspace_id=p_workspace AND campaign_id=p_campaign AND artifact_id=p_artifact ORDER BY created_at DESC,id DESC LIMIT 1;
 IF NOT FOUND THEN RAISE EXCEPTION 'Verified content evidence required' USING ERRCODE='55000'; END IF;
 SELECT least(artifact.retain_until,policy.valid_until,k.valid_until,session.not_after) INTO deadline
  FROM private.acquisition_evidence_verification_keys k
  JOIN private.acquisition_evidence_policies policy ON policy.id=artifact.retention_policy_id AND policy.workspace_id=p_workspace
  JOIN public.workspace_memberships m ON m.workspace_id=p_workspace AND m.user_id=observation.actor_id
  JOIN public.profiles profile ON profile.id=m.user_id
  JOIN auth.sessions session ON session.id=observation.session_id AND session.user_id=m.user_id
  WHERE k.id=observation.key_id AND k.workspace_id=p_workspace FOR SHARE OF k,policy,m,profile,session;
 checked:=clock_timestamp();
 IF deadline IS NULL OR p_expires IS NULL OR NOT isfinite(p_expires) OR p_expires<=checked OR p_expires>deadline
  OR NOT private.acquisition_content_evidence_current(p_workspace,p_campaign,p_artifact,p_hash,observation.id,checked) THEN
  RAISE EXCEPTION 'Current retained scan evidence required' USING ERRCODE='55000'; END IF;
 RETURN observation.id;
END $function$

CREATE OR REPLACE FUNCTION private.lock_acquisition_renewal_authority(p_workspace uuid, p_contract uuid, p_version integer, p_root uuid, p_policy uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE reviews jsonb; originals jsonb; bound jsonb; ids uuid[]; policies uuid[]; sessions uuid[];
 artifact public.acquisition_evidence_artifacts%ROWTYPE; verification public.acquisition_evidence_verifications%ROWTYPE;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('deal-ref:'||p_contract::text,0));
 PERFORM 1 FROM public.deals WHERE workspace_id=p_workspace AND id=p_contract AND acquisition_version=p_version FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Current renewal contract version required' USING ERRCODE='55000'; END IF;
 reviews:=private.acquisition_renewal_review_set(p_workspace,p_contract,p_version,p_root,clock_timestamp());
 IF reviews IS NULL THEN RAISE EXCEPTION 'Complete unsuperseded renewal support required' USING ERRCODE='55000'; END IF;
 SELECT array_agg(DISTINCT (value->>'review_id')::uuid) INTO ids FROM jsonb_array_elements(reviews);
 SELECT coalesce(jsonb_agg(source),'[]') INTO originals FROM public.acquisition_contract_reviews r
  CROSS JOIN LATERAL jsonb_array_elements(coalesce(r.deadline_sources,'[]')||coalesce(r.execution_sources,'[]')||
   coalesce(r.title_sources,'[]')||coalesce(r.disposition_sources,'[]')) source
  WHERE r.workspace_id=p_workspace AND r.contract_id=p_contract AND r.contract_version=p_version AND r.id=ANY(ids);
 IF jsonb_array_length(originals)=0 THEN RAISE EXCEPTION 'Original renewal evidence required' USING ERRCODE='55000'; END IF;
 -- Match existing writers: canonical contract, sorted artifact/byte pairs, then
 -- evidence authority and review authority. Never lock a dependency piecemeal
 -- after a downstream policy has already been locked.
 FOR bound IN SELECT jsonb_build_object('id',id) FROM (SELECT DISTINCT value->>'artifact_id' AS id FROM jsonb_array_elements(originals)) source_ids ORDER BY id LOOP
  PERFORM pg_advisory_xact_lock(hashtextextended('evidence-artifact:'||(bound->>'id'),0));
  SELECT * INTO artifact FROM public.acquisition_evidence_artifacts WHERE workspace_id=p_workspace AND contract_id=p_contract AND id=(bound->>'id')::uuid;
  IF NOT FOUND THEN RAISE EXCEPTION 'Original renewal evidence unavailable' USING ERRCODE='55000'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('evidence-bytes:'||p_workspace::text||':'||artifact.expected_sha256,0));
 END LOOP;
 FOR artifact IN SELECT a.* FROM public.acquisition_evidence_artifacts a WHERE a.workspace_id=p_workspace AND a.contract_id=p_contract
  AND a.id IN (SELECT (value->>'artifact_id')::uuid FROM jsonb_array_elements(originals)) ORDER BY a.id LOOP
  SELECT * INTO verification FROM public.acquisition_evidence_verifications WHERE workspace_id=p_workspace AND artifact_id=artifact.id ORDER BY created_at DESC,id DESC LIMIT 1;
  IF NOT FOUND THEN RAISE EXCEPTION 'Current renewal observation required' USING ERRCODE='55000'; END IF;
  PERFORM 1 FROM private.acquisition_evidence_policies rp
   JOIN private.acquisition_evidence_verification_keys k ON k.workspace_id=rp.workspace_id AND k.id=verification.key_id
   JOIN private.acquisition_contract_verification_key_scopes ks ON ks.workspace_id=k.workspace_id AND ks.key_id=k.id AND ks.purpose=artifact.purpose
   JOIN public.workspace_memberships m ON m.workspace_id=k.workspace_id AND m.user_id=verification.actor_id
   JOIN public.profiles profile ON profile.id=m.user_id JOIN auth.sessions sess ON sess.user_id=m.user_id AND sess.id=verification.session_id
   WHERE rp.workspace_id=p_workspace AND rp.id=artifact.retention_policy_id FOR SHARE OF rp,k,ks,m,profile,sess;
  IF NOT FOUND THEN RAISE EXCEPTION 'Complete renewal evidence authority required' USING ERRCODE='55000'; END IF;
 END LOOP;
 SELECT array_append(array_agg(DISTINCT policy_id),p_policy),array_agg(DISTINCT session_id) INTO policies,sessions
  FROM public.acquisition_contract_reviews WHERE workspace_id=p_workspace AND contract_id=p_contract AND contract_version=p_version AND id=ANY(ids);
 PERFORM 1 FROM private.acquisition_contract_review_policies WHERE workspace_id=p_workspace AND id=ANY(policies) ORDER BY id FOR SHARE;
 PERFORM 1 FROM private.acquisition_disposition_policy_scopes WHERE workspace_id=p_workspace AND policy_id=ANY(policies) ORDER BY policy_id FOR SHARE;
 PERFORM 1 FROM public.workspace_memberships m JOIN public.profiles profile ON profile.id=m.user_id
  JOIN auth.sessions sess ON sess.user_id=m.user_id WHERE m.workspace_id=p_workspace AND sess.id=ANY(sessions)
  ORDER BY m.user_id,sess.id FOR SHARE OF m,profile,sess;
 IF reviews IS DISTINCT FROM private.acquisition_renewal_review_set(p_workspace,p_contract,p_version,p_root,clock_timestamp()) THEN
  RAISE EXCEPTION 'Renewal support changed while waiting' USING ERRCODE='55000'; END IF;
 -- Returning this set does not assert source/policy freshness, active acquisition,
 -- effective supporting reviews, proposed expiry, actor permission or approval.
 RETURN reviews;
END $function$

CREATE OR REPLACE FUNCTION private.protect_acquisition_buyer()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE owner_name text; scoped boolean;
BEGIN
 scoped:=CASE WHEN TG_OP='INSERT' THEN NEW.workspace_id IS NOT NULL
  WHEN TG_OP='DELETE' THEN OLD.workspace_id IS NOT NULL
  ELSE OLD.workspace_id IS NOT NULL OR NEW.workspace_id IS NOT NULL END;
 IF NOT scoped THEN RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END; END IF;
 IF TG_OP='UPDATE' AND (NEW.id IS DISTINCT FROM OLD.id OR NEW.workspace_id IS DISTINCT FROM OLD.workspace_id) THEN
  RAISE EXCEPTION 'Buyer identity and workspace are immutable' USING ERRCODE='23514'; END IF;
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Archive scoped buyers without deleting history' USING ERRCODE='42501'; END IF;
 -- Trusted provider opt-outs remain a one-way operation. This cannot alter
 -- identity, permissions to true, price preferences, or verification evidence.
 IF TG_OP='UPDATE' AND current_user='service_role' AND NEW.email_opt_in IS FALSE
  AND (to_jsonb(NEW)-'email_opt_in'-'updated_at')=(to_jsonb(OLD)-'email_opt_in'-'updated_at') THEN RETURN NEW; END IF;
 SELECT pg_get_userbyid(proowner) INTO owner_name FROM pg_proc WHERE oid='private.protect_acquisition_buyer()'::regprocedure;
 IF current_user<>owner_name THEN RAISE EXCEPTION 'Use scoped buyer functions' USING ERRCODE='42501'; END IF;
 IF (TG_OP='INSERT' AND NEW.acquisition_revision<>1) OR
  (TG_OP='UPDATE' AND NEW.acquisition_revision<>OLD.acquisition_revision+1) THEN
  RAISE EXCEPTION 'Buyer revision must advance exactly once' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION private.record_acquisition_buyer(p_id uuid, p_workspace uuid, p_buyer uuid, p_expected_revision integer, p_details jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE authority record; saved private.acquisition_buyer_versions%ROWTYPE; buyer public.buyers%ROWTYPE;
 fingerprint text; duplicate boolean:=false; enabled boolean;
BEGIN
 IF p_id IS NULL OR p_expected_revision IS NULL OR p_expected_revision NOT BETWEEN 0 AND 2147483646
  OR NOT private.valid_acquisition_buyer_details(p_details) THEN
  RAISE EXCEPTION 'Exact bounded buyer details required' USING ERRCODE='22023'; END IF;
 SELECT * INTO authority FROM private.lock_acquisition_buyer_context(p_workspace,p_buyer);
 PERFORM pg_advisory_xact_lock(hashtextextended('buyer-request:'||p_id::text,0));
 IF authority.session_expires IS NOT NULL AND authority.session_expires<=clock_timestamp() THEN
  RAISE EXCEPTION 'Buyer session expired' USING ERRCODE='42501'; END IF;
 fingerprint:=encode(sha256(convert_to(jsonb_build_array(p_workspace,p_buyer,p_expected_revision,p_details,auth.uid(),auth.jwt()->>'session_id')::text,'UTF8')),'hex');
 SELECT * INTO saved FROM private.acquisition_buyer_versions WHERE request_id=p_id;
 IF FOUND THEN
  IF saved.request_hash IS DISTINCT FROM fingerprint THEN RAISE EXCEPTION 'Buyer request conflict' USING ERRCODE='23505'; END IF;
  duplicate:=true;
 ELSE
  SELECT a.enabled INTO enabled FROM private.acquisition_activation a WHERE singleton FOR SHARE;
  IF enabled IS DISTINCT FROM true THEN RAISE EXCEPTION 'Acquisition paused' USING ERRCODE='55000'; END IF;
  SELECT * INTO buyer FROM public.buyers WHERE id=p_buyer FOR UPDATE;
  IF FOUND THEN
   IF buyer.workspace_id IS DISTINCT FROM p_workspace THEN RAISE EXCEPTION 'Buyer unavailable in this workspace' USING ERRCODE='42501'; END IF;
   IF buyer.acquisition_revision IS DISTINCT FROM p_expected_revision THEN RAISE EXCEPTION 'Buyer revision changed' USING ERRCODE='40001'; END IF;
   IF NOT EXISTS(SELECT 1 FROM private.acquisition_buyer_versions v WHERE v.workspace_id=p_workspace AND v.buyer_id=p_buyer AND v.revision=p_expected_revision) THEN
    RAISE EXCEPTION 'Buyer profile history unavailable' USING ERRCODE='55000'; END IF;
  ELSIF p_expected_revision<>0 THEN RAISE EXCEPTION 'Buyer revision changed' USING ERRCODE='40001';
  END IF;
  IF authority.session_expires IS NOT NULL AND authority.session_expires<=clock_timestamp() THEN
   RAISE EXCEPTION 'Buyer session expired before save' USING ERRCODE='42501'; END IF;
  IF buyer.id IS NULL THEN
  INSERT INTO public.buyers(id,workspace_id,acquisition_revision,first_name,last_name,company,email,phone,target_zips,property_types,strategy,
   min_price,max_price,max_repairs,close_speed_days,active,notes,pof_verified,email_opt_in,sms_opt_in)
  VALUES(p_buyer,p_workspace,p_expected_revision+1,p_details->>'first_name',p_details->>'last_name',p_details->>'company',p_details->>'email',p_details->>'phone',
   ARRAY(SELECT jsonb_array_elements_text(p_details->'target_zips')),ARRAY(SELECT jsonb_array_elements_text(p_details->'property_types')),
   ARRAY(SELECT jsonb_array_elements_text(p_details->'strategies')),(p_details->>'min_price_cents')::numeric/100,
   (p_details->>'max_price_cents')::numeric/100,(p_details->>'max_repairs_cents')::numeric/100,(p_details->>'close_speed_days')::integer,
   (p_details->>'active')::boolean,p_details->>'source_note',false,false,false);
  ELSE
   UPDATE public.buyers SET acquisition_revision=p_expected_revision+1,
    first_name=p_details->>'first_name',
    last_name=p_details->>'last_name',
    company=p_details->>'company',
    email=p_details->>'email',
    phone=p_details->>'phone',
    target_zips=ARRAY(SELECT jsonb_array_elements_text(p_details->'target_zips')),
    property_types=ARRAY(SELECT jsonb_array_elements_text(p_details->'property_types')),
    strategy=ARRAY(SELECT jsonb_array_elements_text(p_details->'strategies')),
    min_price=(p_details->>'min_price_cents')::numeric/100,
    max_price=(p_details->>'max_price_cents')::numeric/100,
    max_repairs=(p_details->>'max_repairs_cents')::numeric/100,
    close_speed_days=(p_details->>'close_speed_days')::integer,
    active=(p_details->>'active')::boolean,
    notes=p_details->>'source_note' WHERE id=p_buyer AND workspace_id=p_workspace;
  END IF;
  INSERT INTO private.acquisition_buyer_versions(request_id,workspace_id,buyer_id,revision,details,actor_id,session_id,actor_membership_updated_at,request_hash)
   VALUES(p_id,p_workspace,p_buyer,p_expected_revision+1,p_details,auth.uid(),(auth.jwt()->>'session_id')::uuid,authority.actor_updated,fingerprint)
   RETURNING * INTO saved;
 END IF;
 RETURN jsonb_build_object('request_id',saved.request_id,'workspace_id',saved.workspace_id,'buyer_id',saved.buyer_id,'revision',saved.revision,
  'details',saved.details,'duplicate',duplicate,'profile_recorded',true,'buyer_verified',false,'contact_authorized',false,'execution_authorized',false);
END $function$

CREATE OR REPLACE FUNCTION private.record_acquisition_evidence_verification(p_id uuid, p_workspace uuid, p_campaign uuid, p_artifact uuid, p_actor uuid, p_session uuid, p_key uuid, p_observation text, p_signature text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE artifact public.acquisition_evidence_artifacts%ROWTYPE; signer private.acquisition_evidence_verification_keys%ROWTYPE;
 saved public.acquisition_evidence_verifications%ROWTYPE; policy private.acquisition_evidence_policies%ROWTYPE;
 payload jsonb; raw json; field text; message text; fingerprint text; expected bytea; supplied bytea; difference integer:=0;
 actor_updated timestamptz; session_expires timestamptz; stamped timestamptz; checked timestamptz; scanned timestamptz;
 registry_checked timestamptz; retained timestamptz; role_name text;
BEGIN
 role_name:=private.acquisition_role(p_workspace);
 IF auth.jwt()->>'role' IS DISTINCT FROM 'authenticated' OR auth.jwt()->>'aal' IS DISTINCT FROM 'aal2'
  OR coalesce(role_name,'') NOT IN ('owner','admin','operator') OR p_actor IS DISTINCT FROM auth.uid()
  OR p_session::text IS DISTINCT FROM auth.jwt()->>'session_id' THEN
  RAISE EXCEPTION 'Verification authority required' USING ERRCODE='42501'; END IF;
 IF p_id IS NULL OR p_campaign IS NULL OR p_artifact IS NULL OR p_actor IS NULL OR p_session IS NULL OR p_key IS NULL
  OR p_observation IS NULL OR octet_length(p_observation) NOT BETWEEN 2 AND 4096
  OR p_signature IS NULL OR p_signature !~ '^[0-9a-f]{64}$' THEN
  RAISE EXCEPTION 'Bounded signed observation required' USING ERRCODE='22023'; END IF;
 raw:=p_observation::json; payload:=raw::jsonb;
 IF jsonb_typeof(payload) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Object observation required' USING ERRCODE='22023'; END IF;
 IF (SELECT count(*) FROM json_each(raw))<>12 OR (SELECT count(DISTINCT key) FROM json_each(raw))<>12
  OR payload - ARRAY['sha256','byte_size','media_type','retain_until','retention_policy_id','checked_at','scan_checked_at',
                    'registry_checked_at','scanner','scanner_version','scan_policy_version','scan_status'] <> '{}'::jsonb THEN
  RAISE EXCEPTION 'Exact observation fields required' USING ERRCODE='22023'; END IF;
 FOR field IN SELECT jsonb_object_keys(payload) LOOP
  IF field='byte_size' THEN
   IF jsonb_typeof(payload->field)<>'number' OR (payload->>field) !~ '^[1-9][0-9]{0,7}$' THEN
    RAISE EXCEPTION 'Integer evidence size required' USING ERRCODE='22023'; END IF;
  ELSIF jsonb_typeof(payload->field) IS DISTINCT FROM 'string' THEN
   RAISE EXCEPTION 'String observation field required' USING ERRCODE='22023'; END IF;
 END LOOP;
 IF payload->>'sha256' !~ '^[0-9a-f]{64}$' OR (payload->>'byte_size')::integer NOT BETWEEN 1 AND 10485760
  OR payload->>'scanner'<>'clamav-instream-v1' OR payload->>'scan_status' NOT IN ('no_detection','detected') THEN
  RAISE EXCEPTION 'Valid scan observation required' USING ERRCODE='22023'; END IF;
 FOREACH field IN ARRAY ARRAY['checked_at','scan_checked_at','registry_checked_at','retain_until'] LOOP
  IF payload->>field !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$' THEN
   RAISE EXCEPTION 'Explicit observation timestamp required' USING ERRCODE='22023'; END IF;
 END LOOP;
 checked:=(payload->>'checked_at')::timestamptz; scanned:=(payload->>'scan_checked_at')::timestamptz;
 registry_checked:=(payload->>'registry_checked_at')::timestamptz; retained:=(payload->>'retain_until')::timestamptz;
 message:='acquisition-evidence-attestation-v1'||chr(10)||p_id::text||chr(10)||p_workspace::text||chr(10)||p_campaign::text||chr(10)||
  p_artifact::text||chr(10)||p_actor::text||chr(10)||p_session::text||chr(10)||p_key::text||chr(10)||p_observation;
 fingerprint:=encode(sha256(convert_to(message||chr(10)||p_signature,'UTF8')),'hex');
 PERFORM 1 FROM public.workspaces WHERE id=p_workspace AND status='active' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Workspace unavailable' USING ERRCODE='42501'; END IF;
 SELECT m.role,m.updated_at,s.not_after INTO role_name,actor_updated,session_expires FROM public.workspace_memberships m JOIN public.profiles p ON p.id=m.user_id
 JOIN auth.sessions s ON s.user_id=p.id WHERE m.workspace_id=p_workspace AND m.user_id=auth.uid() AND m.status='active'
  AND m.role IN ('owner','admin','operator') AND p.status='approved' AND s.id=p_session
  AND (s.not_after IS NULL OR s.not_after>clock_timestamp()) FOR SHARE OF m,p,s;
 IF NOT FOUND THEN RAISE EXCEPTION 'Verification session unavailable' USING ERRCODE='42501'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-verification:'||p_id::text,0));
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-artifact:'||p_artifact::text,0));
 IF session_expires IS NOT NULL AND session_expires<=clock_timestamp() THEN RAISE EXCEPTION 'Verification session expired' USING ERRCODE='42501'; END IF;
 SELECT * INTO saved FROM public.acquisition_evidence_verifications WHERE id=p_id;
 IF FOUND THEN
  IF saved.request_hash IS DISTINCT FROM fingerprint THEN RAISE EXCEPTION 'Verification request conflict' USING ERRCODE='23505'; END IF;
  RETURN jsonb_build_object('verification_id',saved.id,'artifact_id',saved.artifact_id,'workspace_id',saved.workspace_id,
   'scan_status',saved.scan_status,'duplicate',true,'observation_persisted',true,'preview_authorized',false,'content_approved',false,'execution_authorized',false);
 END IF;
 SELECT * INTO artifact FROM public.acquisition_evidence_artifacts WHERE workspace_id=p_workspace AND campaign_id=p_campaign AND id=p_artifact;
 IF NOT FOUND OR (role_name='operator' AND artifact.created_by<>auth.uid()) THEN RAISE EXCEPTION 'Artifact unavailable' USING ERRCODE='42501'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-bytes:'||p_workspace::text||':'||artifact.expected_sha256,0));
 PERFORM 1 FROM public.ad_campaigns WHERE id=p_campaign AND workspace_id=p_workspace AND acquisition_channel='direct_mail' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Campaign unavailable' USING ERRCODE='42501'; END IF;
 SELECT * INTO signer FROM private.acquisition_evidence_verification_keys WHERE id=p_key AND workspace_id=p_workspace FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Verification signer unavailable' USING ERRCODE='42501'; END IF;
 SELECT * INTO policy FROM private.acquisition_evidence_policies WHERE id=artifact.retention_policy_id FOR SHARE;
 stamped:=clock_timestamp();
 IF session_expires IS NOT NULL AND session_expires<=stamped THEN RAISE EXCEPTION 'Verification session expired' USING ERRCODE='42501'; END IF;
 IF signer.revoked_at IS NOT NULL OR NOT(signer.valid_from<=checked AND signer.valid_from<=stamped AND stamped<signer.valid_until)
  OR signer.scanner_version IS DISTINCT FROM payload->>'scanner_version'
  OR signer.scan_policy_version IS DISTINCT FROM payload->>'scan_policy_version' THEN
  RAISE EXCEPTION 'Current reviewed scanner required' USING ERRCODE='42501'; END IF;
 expected:=extensions.hmac(convert_to(message,'UTF8'),signer.secret,'sha256'); supplied:=decode(p_signature,'hex');
 FOR n IN 0..31 LOOP difference:=difference | (get_byte(expected,n) # get_byte(supplied,n)); END LOOP;
 IF difference<>0 THEN RAISE EXCEPTION 'Invalid verification signature' USING ERRCODE='42501'; END IF;
 IF NOT isfinite(checked) OR NOT isfinite(scanned) OR NOT isfinite(registry_checked) OR NOT isfinite(retained)
  OR checked<artifact.created_at-interval '5 seconds' OR checked<stamped-interval '120 seconds' OR checked>scanned OR scanned>stamped+interval '5 seconds'
  OR registry_checked<scanned-interval '5 seconds' OR registry_checked>stamped+interval '5 seconds'
  OR artifact.retain_until<=stamped OR retained IS DISTINCT FROM artifact.retain_until
  OR (payload->>'retention_policy_id')::uuid IS DISTINCT FROM artifact.retention_policy_id
  OR payload->>'sha256' IS DISTINCT FROM artifact.expected_sha256 OR (payload->>'byte_size')::integer<>artifact.expected_byte_size
  OR payload->>'media_type' IS DISTINCT FROM artifact.media_type OR policy.revoked_at IS NOT NULL
  OR NOT(policy.valid_from<=stamped AND stamped<policy.valid_until)
  OR EXISTS(SELECT 1 FROM public.acquisition_evidence_revocations WHERE artifact_id=p_artifact) THEN
  RAISE EXCEPTION 'Evidence changed or observation expired' USING ERRCODE='55000'; END IF;
 INSERT INTO public.acquisition_evidence_verifications(id,workspace_id,campaign_id,artifact_id,actor_id,session_id,
  actor_membership_updated_at,key_id,scan_status,observation,request_hash,created_at)
 VALUES(p_id,p_workspace,p_campaign,p_artifact,p_actor,p_session,actor_updated,p_key,payload->>'scan_status',payload,fingerprint,stamped)
 RETURNING * INTO saved;
 INSERT INTO public.audit_logs(entity_type,entity_id,action,actor,workspace_id,new_value)
 VALUES('acquisition_evidence_verification',p_id::text,'recorded',auth.uid()::text,p_workspace,
  jsonb_build_object('artifact_id',p_artifact,'campaign_id',p_campaign,'scan_status',saved.scan_status,'key_id',p_key,
                    'preview_authorized',false,'content_approved',false,'execution_authorized',false));
 RETURN jsonb_build_object('verification_id',saved.id,'artifact_id',saved.artifact_id,'workspace_id',saved.workspace_id,
  'scan_status',saved.scan_status,'duplicate',false,'observation_persisted',true,'preview_authorized',false,'content_approved',false,'execution_authorized',false);
END $function$

CREATE OR REPLACE FUNCTION private.record_acquisition_inbound_request(p_integration uuid, p_number text, p_agent text, p_agent_version integer, p_call text, p_request uuid, p_expected_revision integer, p_kind text, p_evidence jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE route private.acquisition_inbound_routes%ROWTYPE; saved public.tasks%ROWTYPE;
 fingerprint text; revision integer; phone text; k text; max_length integer;
BEGIN
 PERFORM 1 FROM private.acquisition_activation WHERE singleton AND enabled FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Acquisition activation required' USING ERRCODE='55000'; END IF;
 PERFORM 1 FROM private.acquisition_integrations WHERE id=p_integration AND enabled AND provider='retell' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Inbound integration unavailable' USING ERRCODE='42501'; END IF;
 SELECT * INTO route FROM private.acquisition_inbound_routes WHERE integration_id=p_integration AND enabled FOR SHARE;
 IF NOT FOUND OR route.acquisition_number IS DISTINCT FROM p_number OR route.agent_id IS DISTINCT FROM p_agent
  OR route.agent_version IS DISTINCT FROM p_agent_version THEN RAISE EXCEPTION 'Inbound route unavailable' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.workspaces WHERE id=route.workspace_id AND status='active' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Workspace unavailable' USING ERRCODE='42501'; END IF;
 IF p_call IS NULL OR p_call !~ '^[A-Za-z0-9_-]{1,200}$' OR p_request IS NULL OR p_expected_revision IS NULL
  OR p_expected_revision NOT BETWEEN 0 AND 999999999 OR p_kind IS NULL OR p_kind NOT IN ('request_callback','request_human')
  OR p_evidence IS NULL OR jsonb_typeof(p_evidence)<>'object' OR octet_length(p_evidence::text)>8192 THEN
  RAISE EXCEPTION 'Invalid inbound request' USING ERRCODE='22023'; END IF;
 IF p_kind='request_callback' THEN
  IF (SELECT count(*) FROM jsonb_object_keys(p_evidence))<>4 OR NOT p_evidence ?& ARRAY['phone','preferred_time','purpose','requested_by_caller']
   OR p_evidence->'requested_by_caller' IS DISTINCT FROM 'true'::jsonb THEN
   RAISE EXCEPTION 'Invalid callback evidence' USING ERRCODE='22023'; END IF;
  FOREACH k IN ARRAY ARRAY['phone','preferred_time','purpose'] LOOP
   max_length:=CASE WHEN k='phone' THEN 100 ELSE 500 END;
   IF jsonb_typeof(p_evidence->k) IS DISTINCT FROM 'string' OR length(trim(p_evidence->>k))<1 OR length(p_evidence->>k)>max_length THEN
    RAISE EXCEPTION 'Invalid callback text' USING ERRCODE='22023'; END IF;
  END LOOP;
  BEGIN phone:=private.normalize_acquisition_contact('phone',p_evidence->>'phone');
  EXCEPTION WHEN SQLSTATE '22023' THEN phone:=NULL; END;
 ELSE
  IF (SELECT count(*) FROM jsonb_object_keys(p_evidence))<>3 OR NOT p_evidence ?& ARRAY['reason','details','requested_by_caller']
   OR jsonb_typeof(p_evidence->'requested_by_caller') IS DISTINCT FROM 'boolean'
   OR jsonb_typeof(p_evidence->'reason') IS DISTINCT FROM 'string'
   OR p_evidence->>'reason' NOT IN ('caller_requested','unsupported_language','failed_transfer','sensitive_situation','unable_to_complete')
   OR (p_evidence->>'reason'='caller_requested' AND p_evidence->'requested_by_caller'<>'true'::jsonb)
   OR jsonb_typeof(p_evidence->'details') IS DISTINCT FROM 'string' OR length(trim(p_evidence->>'details'))<1 OR length(p_evidence->>'details')>1000 THEN
   RAISE EXCEPTION 'Invalid escalation evidence' USING ERRCODE='22023'; END IF;
 END IF;
 -- Database fingerprint is authoritative; client hashes never grant authority.
 fingerprint:=encode(sha256(convert_to(jsonb_build_object('version','acquisition-inbound-requests-v1',
  'workspace_id',route.workspace_id,'integration_id',p_integration,'agent_id',p_agent,'agent_version',p_agent_version,
  'call_id',p_call,'request_id',p_request,'expected_revision',p_expected_revision,'kind',p_kind,'evidence',p_evidence)::text,'UTF8')),'hex');
 PERFORM pg_advisory_xact_lock(hashtextextended('acquisition-inbound-request:'||p_integration::text||':'||p_request::text,0));
 -- Same lock used by lifecycle receipt, serializing new intents with terminal events.
 PERFORM pg_advisory_xact_lock(hashtextextended('acquisition-inbound:'||p_integration::text||':'||p_call,0));
 IF p_kind='request_callback' AND EXISTS(SELECT 1 FROM public.acquisition_contact_suppressions
  WHERE inbound_integration_id=p_integration AND inbound_call_id=p_call AND (inbound_kind='cancel_callback' OR inbound_kind='do_not_contact' AND inbound_evidence->'channels' ?| ARRAY['all','human_voice'])) THEN
  RAISE EXCEPTION 'Callback withdrawn by caller' USING ERRCODE='55000'; END IF;
 SELECT * INTO saved FROM public.tasks WHERE acquisition_integration_id=p_integration AND acquisition_request_id=p_request;
 IF FOUND THEN
  IF saved.acquisition_request_hash IS DISTINCT FROM fingerprint THEN RAISE EXCEPTION 'Inbound request conflict' USING ERRCODE='23505'; END IF;
  -- Confirm an existing commit even if the call has since ended. No new work.
  RETURN jsonb_build_object('id',saved.id,'workspace_id',saved.workspace_id,'revision',saved.acquisition_revision,'duplicate',true,'execution_authorized',false);
 END IF;
 IF NOT EXISTS(SELECT 1 FROM public.call_events WHERE acquisition_integration_id=p_integration AND acquisition_call_id=p_call
    AND acquisition_event_type='call_started' AND acquisition_projection->>'call_status'='ongoing')
  OR EXISTS(SELECT 1 FROM public.call_events WHERE acquisition_integration_id=p_integration AND acquisition_call_id=p_call
    AND acquisition_event_type IN ('call_ended','call_analyzed')) THEN
  RAISE EXCEPTION 'Ongoing inbound ledger required' USING ERRCODE='55000'; END IF;
 SELECT coalesce(max(acquisition_revision),0) INTO revision FROM public.tasks WHERE acquisition_integration_id=p_integration
  AND acquisition_call_id=p_call AND acquisition_request_kind=p_kind;
 IF revision<>p_expected_revision THEN RAISE EXCEPTION 'Inbound request revision changed' USING ERRCODE='40001'; END IF;
 INSERT INTO public.tasks(title,priority,status,type,workspace_id,acquisition_integration_id,acquisition_call_id,
  acquisition_request_id,acquisition_revision,acquisition_request_kind,acquisition_evidence,acquisition_request_hash,acquisition_phone)
 VALUES('Inbound acquisition review',NULL,'acquisition_review_required','acquisition_inbound_review',route.workspace_id,p_integration,p_call,
  p_request,revision+1,p_kind,p_evidence,fingerprint,phone) RETURNING * INTO saved;
 INSERT INTO public.audit_logs(entity_type,entity_id,action,actor,new_value,workspace_id)
 VALUES('acquisition_inbound_request',saved.id::text,'recorded','inbound_tools',
  jsonb_build_object('integration_id',p_integration,'request_id',p_request,'revision',revision+1,'kind',p_kind,'request_hash',fingerprint,'execution_authorized',false),route.workspace_id);
 RETURN jsonb_build_object('id',saved.id,'workspace_id',saved.workspace_id,'revision',saved.acquisition_revision,'duplicate',false,'execution_authorized',false);
END $function$

CREATE OR REPLACE FUNCTION private.record_contract_document_verification(p_id uuid, p_workspace uuid, p_contract uuid, p_version integer, p_purpose text, p_artifact uuid, p_actor uuid, p_session uuid, p_key uuid, p_observation text, p_signature text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE artifact public.acquisition_evidence_artifacts%ROWTYPE; signer private.acquisition_evidence_verification_keys%ROWTYPE;
 saved public.acquisition_evidence_verifications%ROWTYPE; policy private.acquisition_evidence_policies%ROWTYPE;
 payload jsonb; raw json; field text; message text; fingerprint text; expected bytea; supplied bytea; difference integer:=0;
 actor_updated timestamptz; session_expires timestamptz; stamped timestamptz; checked timestamptz; scanned timestamptz;
 registry_checked timestamptz; retained timestamptz; role_name text; authority record; scope private.acquisition_contract_verification_key_scopes%ROWTYPE;
BEGIN
 role_name:=private.acquisition_role(p_workspace);
 IF auth.jwt()->>'role' IS DISTINCT FROM 'authenticated' OR auth.jwt()->>'aal' IS DISTINCT FROM 'aal2'
  OR coalesce(role_name,'') NOT IN ('owner','admin','operator') OR p_actor IS DISTINCT FROM auth.uid()
  OR p_session::text IS DISTINCT FROM auth.jwt()->>'session_id' THEN
  RAISE EXCEPTION 'Verification authority required' USING ERRCODE='42501'; END IF;
 IF p_id IS NULL OR p_contract IS NULL OR p_version IS NULL OR p_version<1
  OR p_purpose IS NULL OR p_purpose NOT IN ('purchase_contract','title_report','assignment_agreement','seller_disclosure','assignee_disclosure','closing_statement','supporting_document') OR p_artifact IS NULL OR p_actor IS NULL OR p_session IS NULL OR p_key IS NULL
  OR p_observation IS NULL OR octet_length(p_observation) NOT BETWEEN 2 AND 4096
  OR p_signature IS NULL OR p_signature !~ '^[0-9a-f]{64}$' THEN
  RAISE EXCEPTION 'Bounded signed observation required' USING ERRCODE='22023'; END IF;
 raw:=p_observation::json; payload:=raw::jsonb;
 IF jsonb_typeof(payload) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Object observation required' USING ERRCODE='22023'; END IF;
 IF (SELECT count(*) FROM json_each(raw))<>12 OR (SELECT count(DISTINCT key) FROM json_each(raw))<>12
  OR payload - ARRAY['sha256','byte_size','media_type','retain_until','retention_policy_id','checked_at','scan_checked_at',
                    'registry_checked_at','scanner','scanner_version','scan_policy_version','scan_status'] <> '{}'::jsonb THEN
  RAISE EXCEPTION 'Exact observation fields required' USING ERRCODE='22023'; END IF;
 FOR field IN SELECT jsonb_object_keys(payload) LOOP
  IF field='byte_size' THEN
   IF jsonb_typeof(payload->field)<>'number' OR (payload->>field) !~ '^[1-9][0-9]{0,7}$' THEN
    RAISE EXCEPTION 'Integer evidence size required' USING ERRCODE='22023'; END IF;
  ELSIF jsonb_typeof(payload->field) IS DISTINCT FROM 'string' THEN
   RAISE EXCEPTION 'String observation field required' USING ERRCODE='22023'; END IF;
 END LOOP;
 IF payload->>'sha256' !~ '^[0-9a-f]{64}$' OR (payload->>'byte_size')::integer NOT BETWEEN 1 AND 10485760
  OR payload->>'scanner'<>'clamav-instream-v1' OR payload->>'scan_status' NOT IN ('no_detection','detected') THEN
  RAISE EXCEPTION 'Valid scan observation required' USING ERRCODE='22023'; END IF;
 FOREACH field IN ARRAY ARRAY['checked_at','scan_checked_at','registry_checked_at','retain_until'] LOOP
  IF payload->>field !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$' THEN
   RAISE EXCEPTION 'Explicit observation timestamp required' USING ERRCODE='22023'; END IF;
 END LOOP;
 checked:=(payload->>'checked_at')::timestamptz; scanned:=(payload->>'scan_checked_at')::timestamptz;
 registry_checked:=(payload->>'registry_checked_at')::timestamptz; retained:=(payload->>'retain_until')::timestamptz;
 message:='acquisition-contract-document-attestation-v1'||chr(10)||p_id::text||chr(10)||p_workspace::text||chr(10)||p_contract::text||chr(10)||p_version::text||chr(10)||p_purpose||chr(10)||
  p_artifact::text||chr(10)||p_actor::text||chr(10)||p_session::text||chr(10)||p_key::text||chr(10)||p_observation;
 fingerprint:=encode(sha256(convert_to(message||chr(10)||p_signature,'UTF8')),'hex');
 SELECT * INTO authority FROM private.lock_contract_document_context(p_workspace,p_contract,p_version,ARRAY['owner','admin','operator']);
 actor_updated:=authority.actor_updated; session_expires:=authority.session_expires;
 role_name:=private.acquisition_role(p_workspace);
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-verification:'||p_id::text,0));
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-artifact:'||p_artifact::text,0));
 IF session_expires IS NOT NULL AND session_expires<=clock_timestamp() THEN RAISE EXCEPTION 'Verification session expired' USING ERRCODE='42501'; END IF;
 SELECT * INTO saved FROM public.acquisition_evidence_verifications WHERE id=p_id;
 IF FOUND THEN
  IF saved.request_hash IS DISTINCT FROM fingerprint THEN RAISE EXCEPTION 'Verification request conflict' USING ERRCODE='23505'; END IF;
  RETURN jsonb_build_object('verification_id',saved.id,'artifact_id',saved.artifact_id,'workspace_id',saved.workspace_id,'contract_id',saved.contract_id,'contract_version',saved.contract_version,'purpose',saved.contract_purpose,
   'scan_status',saved.scan_status,'duplicate',true,'observation_persisted',true,'preview_authorized',false,'legal_review_approved',false,'execution_authorized',false);
 END IF;
 SELECT * INTO artifact FROM public.acquisition_evidence_artifacts WHERE workspace_id=p_workspace AND contract_id=p_contract AND contract_version=p_version AND purpose=p_purpose AND campaign_id IS NULL AND id=p_artifact;
 IF NOT FOUND OR (role_name='operator' AND artifact.created_by<>auth.uid()) THEN RAISE EXCEPTION 'Artifact unavailable' USING ERRCODE='42501'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-bytes:'||p_workspace::text||':'||artifact.expected_sha256,0));
 SELECT * INTO signer FROM private.acquisition_evidence_verification_keys WHERE id=p_key AND workspace_id=p_workspace FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Verification signer unavailable' USING ERRCODE='42501'; END IF;
 SELECT * INTO scope FROM private.acquisition_contract_verification_key_scopes WHERE workspace_id=p_workspace AND key_id=p_key AND purpose=p_purpose FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Reviewed contract signing scope required' USING ERRCODE='42501'; END IF;
 SELECT * INTO policy FROM private.acquisition_evidence_policies WHERE id=artifact.retention_policy_id AND workspace_id=p_workspace AND purpose=p_purpose FOR SHARE;
 stamped:=clock_timestamp();
 IF session_expires IS NOT NULL AND session_expires<=stamped THEN RAISE EXCEPTION 'Verification session expired' USING ERRCODE='42501'; END IF;
 IF scope.revoked_at IS NOT NULL OR NOT(scope.valid_from<=checked AND scope.valid_from<=stamped AND stamped<scope.valid_until)
  OR signer.revoked_at IS NOT NULL OR NOT(signer.valid_from<=checked AND signer.valid_from<=stamped AND stamped<signer.valid_until)
  OR signer.scanner_version IS DISTINCT FROM payload->>'scanner_version'
  OR signer.scan_policy_version IS DISTINCT FROM payload->>'scan_policy_version' THEN
  RAISE EXCEPTION 'Current reviewed scanner required' USING ERRCODE='42501'; END IF;
 expected:=extensions.hmac(convert_to(message,'UTF8'),signer.secret,'sha256'); supplied:=decode(p_signature,'hex');
 FOR n IN 0..31 LOOP difference:=difference | (get_byte(expected,n) # get_byte(supplied,n)); END LOOP;
 IF difference<>0 THEN RAISE EXCEPTION 'Invalid verification signature' USING ERRCODE='42501'; END IF;
 IF NOT isfinite(checked) OR NOT isfinite(scanned) OR NOT isfinite(registry_checked) OR NOT isfinite(retained)
  OR checked<artifact.created_at-interval '5 seconds' OR checked<stamped-interval '120 seconds' OR checked>scanned OR scanned>stamped+interval '5 seconds'
  OR registry_checked<scanned-interval '5 seconds' OR registry_checked>stamped+interval '5 seconds'
  OR retained<=greatest(checked,scanned,registry_checked)
  OR artifact.retain_until<=stamped OR retained IS DISTINCT FROM artifact.retain_until
  OR (payload->>'retention_policy_id')::uuid IS DISTINCT FROM artifact.retention_policy_id
  OR payload->>'sha256' IS DISTINCT FROM artifact.expected_sha256 OR (payload->>'byte_size')::integer<>artifact.expected_byte_size
  OR payload->>'media_type' IS DISTINCT FROM artifact.media_type OR policy.id IS NULL OR policy.revoked_at IS NOT NULL
  OR NOT(policy.valid_from<=stamped AND stamped<policy.valid_until)
  OR EXISTS(SELECT 1 FROM public.acquisition_evidence_revocations WHERE artifact_id=p_artifact) THEN
  RAISE EXCEPTION 'Evidence changed or observation expired' USING ERRCODE='55000'; END IF;
 INSERT INTO public.acquisition_evidence_verifications(id,workspace_id,contract_id,contract_version,contract_purpose,artifact_id,actor_id,session_id,
  actor_membership_updated_at,key_id,scan_status,observation,request_hash,created_at)
 VALUES(p_id,p_workspace,p_contract,p_version,p_purpose,p_artifact,p_actor,p_session,actor_updated,p_key,payload->>'scan_status',payload,fingerprint,stamped)
 RETURNING * INTO saved;
 INSERT INTO public.audit_logs(entity_type,entity_id,action,actor,workspace_id,new_value)
 VALUES('acquisition_evidence_verification',p_id::text,'recorded',auth.uid()::text,p_workspace,
  jsonb_build_object('artifact_id',p_artifact,'contract_id',p_contract,'contract_version',p_version,'purpose',p_purpose,'scan_status',saved.scan_status,'key_id',p_key,
                    'preview_authorized',false,'legal_review_approved',false,'execution_authorized',false));
 RETURN jsonb_build_object('verification_id',saved.id,'artifact_id',saved.artifact_id,'workspace_id',saved.workspace_id,'contract_id',saved.contract_id,'contract_version',saved.contract_version,'purpose',saved.contract_purpose,
  'scan_status',saved.scan_status,'duplicate',false,'observation_persisted',true,'preview_authorized',false,'legal_review_approved',false,'execution_authorized',false);
END $function$

CREATE OR REPLACE FUNCTION private.record_contract_review(p_id uuid, p_workspace uuid, p_contract uuid, p_version integer, p_kind text, p_expected_sequence integer, p_status text, p_artifact uuid, p_verification uuid, p_policy uuid, p_expires timestamp with time zone, p_personally_reviewed boolean, p_note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE saved public.acquisition_contract_reviews%ROWTYPE; prior public.acquisition_contract_reviews%ROWTYPE;
 artifact public.acquisition_evidence_artifacts%ROWTYPE; verification public.acquisition_evidence_verifications%ROWTYPE;
 policy private.acquisition_contract_review_policies%ROWTYPE; authority record; source_ref record;
 fingerprint text; stamped timestamptz; deadline timestamptz; active boolean; seq integer;
BEGIN
 IF p_id IS NULL OR p_workspace IS NULL OR p_kind IS NULL OR p_kind NOT IN ('contract_review','title_review','assignment_basis')
  OR p_expected_sequence IS NULL OR p_expected_sequence<0 OR p_expected_sequence>=2147483647
  OR p_status IS NULL OR p_status NOT IN ('approved','withdrawn') OR p_artifact IS NULL OR p_verification IS NULL OR p_policy IS NULL
  OR p_note IS NULL OR length(trim(p_note)) NOT BETWEEN 20 AND 4000 OR p_personally_reviewed IS NULL
  OR (p_status='approved' AND (NOT p_personally_reviewed OR p_expires IS NULL OR NOT isfinite(p_expires)))
  OR (p_status='withdrawn' AND (p_personally_reviewed OR p_expires IS NOT NULL)) THEN
  RAISE EXCEPTION 'Exact human review request required' USING ERRCODE='22023'; END IF;
 SELECT * INTO authority FROM private.lock_contract_document_context(p_workspace,p_contract,p_version,ARRAY['owner','admin']);
 PERFORM pg_advisory_xact_lock(hashtextextended('contract-review:'||p_id::text,0));
 fingerprint:=encode(sha256(convert_to(jsonb_build_object('workspace',p_workspace,'contract',p_contract,'version',p_version,'kind',p_kind,
  'expected_sequence',p_expected_sequence,'status',p_status,'artifact',p_artifact,'verification',p_verification,'policy',p_policy,
  'expires',p_expires,'personally_reviewed',p_personally_reviewed,'note',p_note,'actor',auth.uid(),'session',auth.jwt()->>'session_id')::text,'UTF8')),'hex');
 IF authority.session_expires IS NOT NULL AND authority.session_expires<=clock_timestamp() THEN
  RAISE EXCEPTION 'Review session expired' USING ERRCODE='42501'; END IF;
 SELECT * INTO saved FROM public.acquisition_contract_reviews WHERE id=p_id;
 IF FOUND THEN
  IF saved.request_hash IS DISTINCT FROM fingerprint THEN RAISE EXCEPTION 'Review request conflict' USING ERRCODE='23505'; END IF;
  RETURN jsonb_build_object('review_id',saved.id,'workspace_id',saved.workspace_id,'contract_id',saved.contract_id,'contract_version',saved.contract_version,
   'kind',saved.kind,'sequence',saved.sequence,'status',saved.status,'duplicate',true,'review_recorded',true,'approval_current',false,'execution_authorized',false);
 END IF;
 SELECT * INTO prior FROM public.acquisition_contract_reviews WHERE workspace_id=p_workspace AND contract_id=p_contract AND contract_version=p_version AND kind=p_kind ORDER BY sequence DESC LIMIT 1;
 seq:=coalesce(prior.sequence,0);
 IF seq<>p_expected_sequence THEN RAISE EXCEPTION 'Review sequence changed' USING ERRCODE='40001'; END IF;
 IF p_status='withdrawn' THEN
  IF prior.id IS NULL OR prior.status<>'approved' OR prior.actor_id<>auth.uid() OR prior.policy_id<>p_policy
   OR prior.artifact_id<>p_artifact OR prior.verification_id<>p_verification THEN
   RAISE EXCEPTION 'Original approved review required for withdrawal' USING ERRCODE='55000'; END IF;
  -- Withdrawal can reduce authority even after policy/activation/evidence expiry.
  artifact.purpose:=prior.purpose; artifact.expected_sha256:=prior.sha256; artifact.contract_version:=prior.source_version;
 ELSE
  SELECT enabled INTO active FROM private.acquisition_activation WHERE singleton FOR SHARE;
  IF active IS DISTINCT FROM true THEN RAISE EXCEPTION 'Acquisition paused' USING ERRCODE='55000'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.deals WHERE id=p_contract AND workspace_id=p_workspace AND acquisition_version=p_version
    AND acquisition_status NOT IN ('closed','cancelled','expired')) THEN
   RAISE EXCEPTION 'Current contract version required' USING ERRCODE='55000'; END IF;
  SELECT * INTO source_ref FROM private.contract_document_reference(p_workspace,p_contract,p_version,p_artifact);
  IF NOT FOUND OR source_ref.link_revoked THEN RAISE EXCEPTION 'Current original document reference required' USING ERRCODE='55000'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('evidence-artifact:'||p_artifact::text,0));
  SELECT * INTO artifact FROM public.acquisition_evidence_artifacts WHERE workspace_id=p_workspace AND contract_id=p_contract AND contract_version=source_ref.source_version AND id=p_artifact;
  IF NOT FOUND THEN RAISE EXCEPTION 'Contract review artifact unavailable' USING ERRCODE='55000'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('evidence-bytes:'||p_workspace::text||':'||artifact.expected_sha256,0));
  SELECT * INTO verification FROM public.acquisition_evidence_verifications WHERE workspace_id=p_workspace AND artifact_id=p_artifact AND id=p_verification;
  IF NOT FOUND THEN RAISE EXCEPTION 'Contract review scan unavailable' USING ERRCODE='55000'; END IF;
  SELECT * INTO policy FROM private.acquisition_contract_review_policies WHERE id=p_policy AND workspace_id=p_workspace
   AND kind=p_kind AND purpose=artifact.purpose AND reviewer_id=auth.uid() FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Reviewed human authority required' USING ERRCODE='42501'; END IF;
  SELECT least(artifact.retain_until,rp.valid_until,k.valid_until,ks.valid_until,s.not_after,policy.valid_until,authority.session_expires)
   INTO deadline FROM private.acquisition_evidence_verification_keys k
   JOIN private.acquisition_contract_verification_key_scopes ks ON ks.workspace_id=k.workspace_id AND ks.key_id=k.id AND ks.purpose=artifact.purpose
   JOIN private.acquisition_evidence_policies rp ON rp.workspace_id=k.workspace_id AND rp.id=artifact.retention_policy_id
   JOIN public.workspace_memberships m ON m.workspace_id=k.workspace_id AND m.user_id=verification.actor_id
   JOIN public.profiles profile ON profile.id=m.user_id JOIN auth.sessions s ON s.id=verification.session_id AND s.user_id=m.user_id
   WHERE k.id=verification.key_id AND k.workspace_id=p_workspace FOR SHARE OF k,ks,rp,m,profile,s;
  stamped:=clock_timestamp();
  IF policy.revoked_at IS NOT NULL OR NOT(policy.valid_from<=stamped AND stamped<policy.valid_until)
   OR deadline IS NULL OR p_expires<=stamped OR p_expires>deadline OR p_expires>stamped+make_interval(secs=>policy.max_review_seconds)
   OR NOT private.contract_review_evidence_current(p_workspace,p_contract,artifact.contract_version,p_artifact,p_verification,artifact.expected_sha256,artifact.purpose,stamped) THEN
   RAISE EXCEPTION 'Current reviewed evidence and deadline required' USING ERRCODE='55000'; END IF;
 END IF;
 stamped:=clock_timestamp();
 IF authority.session_expires IS NOT NULL AND authority.session_expires<=stamped THEN RAISE EXCEPTION 'Review session expired' USING ERRCODE='42501'; END IF;
 INSERT INTO public.acquisition_contract_reviews(id,workspace_id,contract_id,contract_version,kind,sequence,status,artifact_id,verification_id,purpose,sha256,policy_id,
  actor_id,session_id,actor_membership_updated_at,personally_reviewed,note,expires_at,request_hash,created_at,evidence_version)
 VALUES(p_id,p_workspace,p_contract,p_version,p_kind,seq+1,p_status,p_artifact,p_verification,artifact.purpose,artifact.expected_sha256,p_policy,
  auth.uid(),(auth.jwt()->>'session_id')::uuid,authority.actor_updated,p_personally_reviewed,p_note,p_expires,fingerprint,stamped,artifact.contract_version);
 INSERT INTO public.audit_logs(entity_type,entity_id,action,actor,workspace_id,new_value)
 VALUES('acquisition_contract_review',p_id::text,p_status,auth.uid()::text,p_workspace,
  jsonb_build_object('contract_id',p_contract,'contract_version',p_version,'kind',p_kind,'sequence',seq+1,'artifact_id',p_artifact,'verification_id',p_verification,
   'policy_id',p_policy,'source_version',artifact.contract_version,'expires_at',p_expires,'execution_authorized',false));
 RETURN jsonb_build_object('review_id',p_id,'workspace_id',p_workspace,'contract_id',p_contract,'contract_version',p_version,'kind',p_kind,'sequence',seq+1,
  'status',p_status,'duplicate',false,'review_recorded',true,'approval_current',false,'execution_authorized',false);
END $function$

CREATE OR REPLACE FUNCTION private.record_contract_transition(p_id uuid, p_workspace uuid, p_contract uuid, p_expected_version integer, p_expected_sequence integer, p_expected_status text, p_target_status text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE authority record; saved public.acquisition_contract_transitions%ROWTYPE;
 release public.acquisition_signature_reviews%ROWTYPE; basis public.acquisition_contract_reviews%ROWTYPE;
 disposition public.acquisition_contract_reviews%ROWTYPE; executed public.acquisition_contract_reviews%ROWTYPE; bound jsonb; checked timestamptz;
 fingerprint text; authority_reviews jsonb:='[]'; execution_root uuid; disposition_root uuid; seq integer; active boolean; current_review jsonb; duplicate boolean:=false;
BEGIN
 IF p_id IS NULL OR p_expected_sequence IS NULL OR p_expected_sequence NOT BETWEEN 0 AND 2147483646
  OR NOT ((p_expected_status IS NOT DISTINCT FROM 'draft' AND p_target_status IS NOT DISTINCT FROM 'pending_signature')
   OR (p_expected_status IS NOT DISTINCT FROM 'pending_signature' AND p_target_status IS NOT DISTINCT FROM 'executed')
   OR (p_expected_status IS NOT DISTINCT FROM 'executed' AND p_target_status IS NOT DISTINCT FROM 'title_review')
   OR (p_expected_status IS NOT DISTINCT FROM 'title_review' AND p_target_status IS NOT DISTINCT FROM 'disposition_review'))
  OR p_reason IS NULL OR length(trim(p_reason)) NOT BETWEEN 20 AND 4000 THEN
  RAISE EXCEPTION 'Supported exact lifecycle request required' USING ERRCODE='22023'; END IF;
 SELECT * INTO authority FROM private.lock_contract_document_context(p_workspace,p_contract,p_expected_version,ARRAY['owner','admin']);
 PERFORM pg_advisory_xact_lock(hashtextextended('contract-transition:'||p_id::text,0));
 fingerprint:=encode(sha256(convert_to(jsonb_build_array(p_workspace,p_contract,p_expected_version,p_expected_sequence,
  p_expected_status,p_target_status,p_reason,auth.uid(),auth.jwt()->>'session_id')::text,'UTF8')),'hex');
 IF authority.session_expires IS NOT NULL AND authority.session_expires<=clock_timestamp() THEN
  RAISE EXCEPTION 'Transition session expired' USING ERRCODE='42501'; END IF;
 SELECT * INTO saved FROM public.acquisition_contract_transitions WHERE id=p_id;
 IF FOUND THEN
  IF saved.request_hash IS DISTINCT FROM fingerprint THEN RAISE EXCEPTION 'Lifecycle request conflict' USING ERRCODE='23505'; END IF;
  duplicate:=true;
 ELSE
  SELECT enabled INTO active FROM private.acquisition_activation WHERE singleton FOR SHARE;
  IF active IS DISTINCT FROM true THEN RAISE EXCEPTION 'Acquisition paused' USING ERRCODE='55000'; END IF;
  SELECT coalesce(max(sequence),0) INTO seq FROM public.acquisition_contract_transitions WHERE workspace_id=p_workspace AND contract_id=p_contract;
  IF seq<>p_expected_sequence OR NOT EXISTS(SELECT 1 FROM public.deals WHERE workspace_id=p_workspace AND id=p_contract
   AND acquisition_version=p_expected_version AND acquisition_status=p_expected_status) THEN
   RAISE EXCEPTION 'Lifecycle context changed' USING ERRCODE='40001'; END IF;
  IF p_target_status='pending_signature' THEN
  SELECT * INTO release FROM public.acquisition_signature_reviews WHERE workspace_id=p_workspace AND contract_id=p_contract
   AND contract_version=p_expected_version ORDER BY sequence DESC LIMIT 1;
  IF release.id IS NULL OR release.status<>'approved' THEN RAISE EXCEPTION 'Current signature review required' USING ERRCODE='55000'; END IF;
  SELECT * INTO basis FROM public.acquisition_contract_reviews WHERE id=release.basis_review_id AND workspace_id=p_workspace
   AND contract_id=p_contract AND contract_version=p_expected_version;
  PERFORM pg_advisory_xact_lock(hashtextextended('evidence-artifact:'||basis.artifact_id::text,0));
  PERFORM pg_advisory_xact_lock(hashtextextended('evidence-bytes:'||p_workspace::text||':'||basis.sha256,0));
  PERFORM 1 FROM private.acquisition_signature_policies WHERE id=release.policy_id FOR SHARE;
   PERFORM 1 FROM private.acquisition_contract_review_policies WHERE id=basis.policy_id FOR SHARE;
   PERFORM 1 FROM public.acquisition_evidence_artifacts a
    JOIN public.acquisition_evidence_verifications v ON v.workspace_id=a.workspace_id AND v.artifact_id=a.id AND v.id=basis.verification_id
    JOIN private.acquisition_evidence_policies rp ON rp.workspace_id=a.workspace_id AND rp.id=a.retention_policy_id
    JOIN private.acquisition_evidence_verification_keys k ON k.workspace_id=v.workspace_id AND k.id=v.key_id
    JOIN private.acquisition_contract_verification_key_scopes ks ON ks.workspace_id=k.workspace_id AND ks.key_id=k.id AND ks.purpose=a.purpose
    WHERE a.workspace_id=p_workspace AND a.id=basis.artifact_id FOR SHARE OF rp,k,ks;
   PERFORM 1 FROM public.workspace_memberships m JOIN public.profiles profile ON profile.id=m.user_id
    JOIN auth.sessions sess ON sess.user_id=m.user_id
    WHERE m.workspace_id=p_workspace AND (sess.id=release.session_id OR sess.id=basis.session_id OR sess.id=(SELECT session_id FROM public.acquisition_evidence_verifications WHERE id=basis.verification_id))
    ORDER BY m.user_id,sess.id FOR SHARE OF m,profile,sess;

  -- VOLATILE state read occurs after all source/policy/reviewer locks and uses
  -- clock_timestamp. A prior ready response or client-supplied evidence is ignored.
  current_review:=private.signature_review_state(p_workspace,p_contract,p_expected_version);
  IF current_review->>'review_id' IS DISTINCT FROM release.id::text OR current_review->>'approval_current' IS DISTINCT FROM 'true'
   OR (authority.session_expires IS NOT NULL AND authority.session_expires<=clock_timestamp()) THEN
   RAISE EXCEPTION 'Signature release authority changed' USING ERRCODE='55000'; END IF;
  ELSIF p_target_status='disposition_review' THEN
   IF seq<>3 THEN RAISE EXCEPTION 'Original title entry required' USING ERRCODE='55000'; END IF;
   disposition.id:=private.lock_disposition_handoff_authority(p_workspace,p_contract,p_expected_version);
   SELECT * INTO disposition FROM public.acquisition_contract_reviews r WHERE r.id=disposition.id;
   SELECT * INTO executed FROM public.acquisition_contract_reviews WHERE id=(
    SELECT execution_review_id FROM public.acquisition_contract_transitions WHERE id=disposition.disposition_execution_id);
   checked:=clock_timestamp();
   IF (authority.session_expires IS NOT NULL AND authority.session_expires<=checked)
    OR NOT private.disposition_review_current(disposition.id,checked) THEN
    RAISE EXCEPTION 'Disposition transition authority expired' USING ERRCODE='55000'; END IF;
  ELSE
   -- Exact current head and complete transitive authority are locked together.
   SELECT * INTO executed FROM public.acquisition_contract_reviews WHERE workspace_id=p_workspace AND contract_id=p_contract
    AND contract_version=p_expected_version AND kind='executed_contract' ORDER BY sequence DESC LIMIT 1;
   IF executed.id IS NULL OR executed.status<>'approved' OR seq<>(CASE WHEN p_target_status='title_review' THEN 2 ELSE 1 END) THEN
    RAISE EXCEPTION 'Current executed agreement review required' USING ERRCODE='55000'; END IF;
   execution_root:=coalesce(executed.renewal_root_id,executed.id);
   IF p_target_status='title_review' AND NOT EXISTS(SELECT 1 FROM public.acquisition_contract_transitions t
    WHERE t.workspace_id=p_workspace AND t.contract_id=p_contract AND t.contract_version=p_expected_version
     AND t.sequence=2 AND t.recorded_status='executed' AND t.execution_review_id=execution_root) THEN
    RAISE EXCEPTION 'Original recorded execution review required' USING ERRCODE='55000'; END IF;
   PERFORM private.lock_acquisition_renewal_authority(p_workspace,p_contract,p_expected_version,execution_root,executed.policy_id);
   checked:=clock_timestamp();
   -- This separate statement sees changes committed while locks were awaited.
   -- The predicate checks the latest exact review, every saved scan/reference,
   -- source retention, reviewer/scanner authority and current matching terms.
   IF NOT private.execution_review_current(executed.id,checked)
    OR (authority.session_expires IS NOT NULL AND authority.session_expires<=checked) THEN
    RAISE EXCEPTION 'Execution review authority changed' USING ERRCODE='55000'; END IF;
  END IF;
  execution_root:=coalesce(executed.renewal_root_id,executed.id);
  disposition_root:=coalesce(disposition.renewal_root_id,disposition.id);
  IF execution_root IS NOT NULL THEN
   authority_reviews:=private.acquisition_renewal_review_set(p_workspace,p_contract,p_expected_version,
    coalesce(disposition_root,execution_root),checked);
   IF authority_reviews IS NULL THEN RAISE EXCEPTION 'Exact effective review snapshot required' USING ERRCODE='55000'; END IF;
  END IF;
  INSERT INTO public.acquisition_contract_transitions(id,workspace_id,contract_id,contract_version,sequence,previous_status,recorded_status,
   signature_review_id,execution_review_id,execution_review_kind,actor_id,session_id,actor_membership_updated_at,reason,request_hash,
   disposition_review_id,disposition_plan_id,disposition_exit_type,disposition_execution_id,disposition_title_entry_id,disposition_title_review_id)
  VALUES(p_id,p_workspace,p_contract,p_expected_version,seq+1,p_expected_status,p_target_status,release.id,execution_root,CASE WHEN execution_root IS NOT NULL THEN 'executed_contract' END,auth.uid(),
   (auth.jwt()->>'session_id')::uuid,authority.actor_updated,p_reason,fingerprint,
   disposition_root,disposition.disposition_plan_id,disposition.disposition_exit_type,disposition.disposition_execution_id,disposition.disposition_title_entry_id,disposition.disposition_title_review_id) RETURNING * INTO saved;
  UPDATE public.deals SET acquisition_status=p_target_status WHERE id=p_contract AND workspace_id=p_workspace;
  INSERT INTO public.audit_logs(entity_type,entity_id,action,actor,workspace_id,new_value)
  VALUES('acquisition_contract_transition',p_id::text,p_target_status,auth.uid()::text,p_workspace,
   jsonb_build_object('contract_id',p_contract,'contract_version',p_expected_version,'sequence',saved.sequence,
    'previous_status',p_expected_status,'recorded_status',p_target_status,'signature_review_id',release.id,'execution_review_id',execution_root,'disposition_review_id',disposition_root,'disposition_plan_id',disposition.disposition_plan_id,
    'disposition_exit_type',disposition.disposition_exit_type,'title_review_id',disposition.disposition_title_review_id,'review_authority',authority_reviews,'authority_checked_at',coalesce(checked,clock_timestamp()),'execution_authorized',false));
 END IF;
 RETURN jsonb_build_object('workspace_id',saved.workspace_id,'contract_id',saved.contract_id,'request_id',saved.id,
  'contract_version',saved.contract_version,'sequence',saved.sequence,'previous_status',saved.previous_status,'recorded_status',saved.recorded_status,
  'duplicate',duplicate,'transition_recorded',true,'execution_authorized',false);
END $function$

CREATE OR REPLACE FUNCTION private.record_deadline_resolution_review(p_id uuid, p_workspace uuid, p_contract uuid, p_version integer, p_expected_sequence integer, p_status text, p_artifact uuid, p_verification uuid, p_policy uuid, p_expires timestamp with time zone, p_personally_reviewed boolean, p_note text, p_term text, p_resolution jsonb, p_original uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE saved public.acquisition_contract_reviews%ROWTYPE; prior public.acquisition_contract_reviews%ROWTYPE;
 artifact public.acquisition_evidence_artifacts%ROWTYPE; verification public.acquisition_evidence_verifications%ROWTYPE;
 policy private.acquisition_contract_review_policies%ROWTYPE; authority record; source_ref record;
 p_kind constant text:='deadline_resolution'; prepared jsonb; original_source public.acquisition_contract_term_sources%ROWTYPE; bound jsonb; sources jsonb:='[]'::jsonb; source_deadline timestamptz; source_id uuid;
 fingerprint text; stamped timestamptz; active boolean; seq integer;
BEGIN
 IF p_id IS NULL OR p_workspace IS NULL OR p_term IS NULL OR p_term NOT IN ('effective','inspection_deadline','closing_deadline')
  OR (p_status='approved' AND (NOT private.valid_deadline_resolution(p_resolution,p_version) OR p_original IS NOT NULL
   OR p_resolution->>'term' IS DISTINCT FROM p_term OR (p_resolution->'source'->>'artifact_id')::uuid IS DISTINCT FROM p_artifact))
  OR (p_status='withdrawn' AND (p_resolution IS NOT NULL OR p_original IS NULL OR p_original=p_id))
  OR p_expected_sequence IS NULL OR p_expected_sequence<0 OR p_expected_sequence>=2147483647
  OR p_status IS NULL OR p_status NOT IN ('approved','withdrawn') OR p_artifact IS NULL OR p_verification IS NULL OR p_policy IS NULL
  OR p_note IS NULL OR length(trim(p_note)) NOT BETWEEN 20 AND 4000 OR p_personally_reviewed IS NULL
  OR (p_status='approved' AND (NOT p_personally_reviewed OR p_expires IS NULL OR NOT isfinite(p_expires)))
  OR (p_status='withdrawn' AND (p_personally_reviewed OR p_expires IS NOT NULL)) THEN
  RAISE EXCEPTION 'Exact human review request required' USING ERRCODE='22023'; END IF;
 SELECT * INTO authority FROM private.lock_contract_document_context(p_workspace,p_contract,p_version,ARRAY['owner','admin']);
 PERFORM pg_advisory_xact_lock(hashtextextended('contract-review:'||p_id::text,0));
 fingerprint:=encode(sha256(convert_to(jsonb_build_object('workspace',p_workspace,'contract',p_contract,'version',p_version,'kind',p_kind,
  'expected_sequence',p_expected_sequence,'status',p_status,'artifact',p_artifact,'verification',p_verification,'policy',p_policy,
  'deadline_term',p_term,'deadline_resolution',p_resolution,'original_review_id',p_original,'expires',p_expires,'personally_reviewed',p_personally_reviewed,'note',p_note,'actor',auth.uid(),'session',auth.jwt()->>'session_id')::text,'UTF8')),'hex');
 IF authority.session_expires IS NOT NULL AND authority.session_expires<=clock_timestamp() THEN
  RAISE EXCEPTION 'Review session expired' USING ERRCODE='42501'; END IF;
 SELECT * INTO saved FROM public.acquisition_contract_reviews WHERE id=p_id;
 IF FOUND THEN
  IF saved.request_hash IS DISTINCT FROM fingerprint THEN RAISE EXCEPTION 'Review request conflict' USING ERRCODE='23505'; END IF;
  RETURN jsonb_build_object('review_id',saved.id,'workspace_id',saved.workspace_id,'contract_id',saved.contract_id,'contract_version',saved.contract_version,
   'kind',saved.kind,'sequence',saved.sequence,'status',saved.status,'term',saved.deadline_term,'interpretation_review_id',coalesce(saved.deadline_original_review_id,saved.id),'duplicate',true,'review_recorded',true,'approval_current',false,'execution_authorized',false);
 END IF;
 SELECT coalesce(max(sequence),0) INTO seq FROM public.acquisition_contract_reviews
  WHERE workspace_id=p_workspace AND contract_id=p_contract AND contract_version=p_version AND kind=p_kind;
 IF seq<>p_expected_sequence THEN RAISE EXCEPTION 'Review sequence changed' USING ERRCODE='40001'; END IF;
 IF p_status='withdrawn' THEN
  SELECT * INTO prior FROM public.acquisition_contract_reviews
   WHERE workspace_id=p_workspace AND contract_id=p_contract AND contract_version=p_version AND kind=p_kind
    AND deadline_term=p_term ORDER BY sequence DESC LIMIT 1;
  IF prior.id IS NULL OR prior.id<>p_original OR prior.status<>'approved' OR prior.actor_id<>auth.uid() OR prior.policy_id<>p_policy
   OR prior.artifact_id<>p_artifact OR prior.verification_id<>p_verification THEN
   RAISE EXCEPTION 'Original approved interpretation required for withdrawal' USING ERRCODE='55000'; END IF;
  -- Withdrawal can reduce authority even after policy/activation/evidence expiry.
  artifact.purpose:=prior.purpose; artifact.expected_sha256:=prior.sha256; artifact.contract_version:=prior.source_version;
 ELSE
  SELECT enabled INTO active FROM private.acquisition_activation WHERE singleton FOR SHARE;
  IF active IS DISTINCT FROM true THEN RAISE EXCEPTION 'Acquisition paused' USING ERRCODE='55000'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.deals WHERE id=p_contract AND workspace_id=p_workspace AND acquisition_version=p_version
    AND acquisition_status='pending_signature') THEN
   RAISE EXCEPTION 'Current contract version required' USING ERRCODE='55000'; END IF;
  SELECT terms INTO prepared FROM public.acquisition_contract_versions
   WHERE workspace_id=p_workspace AND deal_id=p_contract AND version=p_version;
  IF prepared->p_term->>'precision' IS DISTINCT FROM 'date'
   OR prepared->p_term->>'calendar_date' IS DISTINCT FROM p_resolution->>'calendar_date' THEN
   RAISE EXCEPTION 'Preserve the exact original calendar date; changed dates require amendment' USING ERRCODE='55000'; END IF;
  SELECT * INTO original_source FROM public.acquisition_contract_term_sources
   WHERE workspace_id=p_workspace AND contract_id=p_contract AND contract_version=p_version AND term=p_term;
  IF NOT FOUND THEN RAISE EXCEPTION 'Original calendar term source required' USING ERRCODE='55000'; END IF;
  -- Bind both the original calendar clause and the proposed interpretation. Their
  -- original scans remain exact; a later scan cannot silently replace either.
  FOR source_id IN SELECT id FROM (SELECT p_artifact AS id UNION SELECT original_source.artifact_id) originals ORDER BY id LOOP
   SELECT * INTO source_ref FROM private.contract_document_reference(p_workspace,p_contract,p_version,source_id);
   IF NOT FOUND OR source_ref.link_revoked THEN RAISE EXCEPTION 'Current original source reference required' USING ERRCODE='55000'; END IF;
   PERFORM pg_advisory_xact_lock(hashtextextended('evidence-artifact:'||source_id::text,0));
   SELECT * INTO artifact FROM public.acquisition_evidence_artifacts WHERE workspace_id=p_workspace AND contract_id=p_contract
    AND contract_version=source_ref.source_version AND id=source_id AND campaign_id IS NULL;
   IF NOT FOUND OR (source_id=p_artifact AND artifact.purpose<>'purchase_contract') THEN
    RAISE EXCEPTION 'Exact deadline source unavailable' USING ERRCODE='55000'; END IF;
   IF (source_id=p_artifact AND ((p_resolution->'source'->>'artifact_version')::integer<>artifact.contract_version
      OR p_resolution->'source'->>'sha256'<>artifact.expected_sha256))
    OR (source_id=original_source.artifact_id AND (original_source.artifact_version<>artifact.contract_version
      OR original_source.sha256<>artifact.expected_sha256)) THEN
    RAISE EXCEPTION 'Original deadline source identity changed' USING ERRCODE='55000'; END IF;
   PERFORM pg_advisory_xact_lock(hashtextextended('evidence-bytes:'||p_workspace::text||':'||artifact.expected_sha256,0));
   SELECT * INTO verification FROM public.acquisition_evidence_verifications WHERE workspace_id=p_workspace AND artifact_id=source_id
    ORDER BY created_at DESC,id DESC LIMIT 1;
   IF NOT FOUND OR (source_id=p_artifact AND verification.id<>p_verification)
    OR (source_id=original_source.artifact_id AND verification.id<>original_source.verification_id) THEN
    RAISE EXCEPTION 'Exact current deadline source scan required' USING ERRCODE='55000'; END IF;
   SELECT least(artifact.retain_until,rp.valid_until,k.valid_until,ks.valid_until,s.not_after)
    INTO source_deadline FROM private.acquisition_evidence_verification_keys k
    JOIN private.acquisition_contract_verification_key_scopes ks ON ks.workspace_id=k.workspace_id AND ks.key_id=k.id AND ks.purpose=artifact.purpose
    JOIN private.acquisition_evidence_policies rp ON rp.workspace_id=k.workspace_id AND rp.id=artifact.retention_policy_id
    JOIN public.workspace_memberships m ON m.workspace_id=k.workspace_id AND m.user_id=verification.actor_id
    JOIN public.profiles profile ON profile.id=m.user_id JOIN auth.sessions s ON s.id=verification.session_id AND s.user_id=m.user_id
    WHERE k.id=verification.key_id AND k.workspace_id=p_workspace FOR SHARE OF k,ks,rp,m,profile,s;
   IF source_deadline IS NULL THEN RAISE EXCEPTION 'Deadline source authority missing' USING ERRCODE='55000'; END IF;
   sources:=sources||jsonb_build_array(jsonb_build_object('artifact_id',source_id,'source_version',artifact.contract_version,
    'verification_id',verification.id,'sha256',artifact.expected_sha256,'purpose',artifact.purpose,'expires_at',source_deadline));
  END LOOP;
  SELECT * INTO policy FROM private.acquisition_contract_review_policies WHERE id=p_policy AND workspace_id=p_workspace
   AND kind=p_kind AND purpose='purchase_contract' AND reviewer_id=auth.uid() FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Reviewed human deadline interpretation authority required' USING ERRCODE='42501'; END IF;
  stamped:=clock_timestamp();
  IF policy.revoked_at IS NOT NULL OR NOT(policy.valid_from<=stamped AND stamped<policy.valid_until)
   OR p_expires<=stamped OR p_expires>policy.valid_until OR p_expires>stamped+make_interval(secs=>policy.max_review_seconds)
   OR prepared->p_term->>'calendar_date' IS DISTINCT FROM p_resolution->>'calendar_date' THEN
   RAISE EXCEPTION 'Current bounded deadline interpretation review required' USING ERRCODE='55000'; END IF;
  FOR bound IN SELECT value FROM jsonb_array_elements(sources) LOOP
   IF p_expires>(bound->>'expires_at')::timestamptz OR NOT private.contract_review_evidence_current(p_workspace,p_contract,
    (bound->>'source_version')::integer,(bound->>'artifact_id')::uuid,(bound->>'verification_id')::uuid,
    bound->>'sha256',bound->>'purpose',stamped) THEN
    RAISE EXCEPTION 'Deadline source authority changed while waiting' USING ERRCODE='55000'; END IF;
  END LOOP;
  SELECT * INTO artifact FROM public.acquisition_evidence_artifacts WHERE id=p_artifact;
 END IF;
 stamped:=clock_timestamp();
 IF authority.session_expires IS NOT NULL AND (authority.session_expires<=stamped OR (p_status='approved' AND p_expires>authority.session_expires)) THEN RAISE EXCEPTION 'Review session expired' USING ERRCODE='42501'; END IF;
 INSERT INTO public.acquisition_contract_reviews(id,workspace_id,contract_id,contract_version,kind,sequence,status,artifact_id,verification_id,purpose,sha256,policy_id,
  actor_id,session_id,actor_membership_updated_at,personally_reviewed,note,expires_at,request_hash,created_at,evidence_version,deadline_term,deadline_resolution,deadline_original_review_id,deadline_sources)
 VALUES(p_id,p_workspace,p_contract,p_version,p_kind,seq+1,p_status,p_artifact,p_verification,artifact.purpose,artifact.expected_sha256,p_policy,
  auth.uid(),(auth.jwt()->>'session_id')::uuid,authority.actor_updated,p_personally_reviewed,p_note,p_expires,fingerprint,stamped,artifact.contract_version,p_term,p_resolution,p_original,CASE WHEN p_status='approved' THEN sources ELSE NULL END);
 INSERT INTO public.audit_logs(entity_type,entity_id,action,actor,workspace_id,new_value)
 VALUES('acquisition_contract_review',p_id::text,p_status,auth.uid()::text,p_workspace,
  jsonb_build_object('contract_id',p_contract,'contract_version',p_version,'kind',p_kind,'sequence',seq+1,'artifact_id',p_artifact,'verification_id',p_verification,
   'policy_id',p_policy,'source_version',artifact.contract_version,'expires_at',p_expires,'deadline_term',p_term,'original_review_id',p_original,'deadline_sources',CASE WHEN p_status='approved' THEN sources ELSE NULL END,'execution_authorized',false));
 RETURN jsonb_build_object('review_id',p_id,'workspace_id',p_workspace,'contract_id',p_contract,'contract_version',p_version,'kind',p_kind,'sequence',seq+1,
  'status',p_status,'term',p_term,'interpretation_review_id',coalesce(p_original,p_id),'duplicate',false,'review_recorded',true,'approval_current',false,'execution_authorized',false);
END $function$

CREATE OR REPLACE FUNCTION private.record_disposition_review(p_id uuid, p_workspace uuid, p_contract uuid, p_version integer, p_expected_sequence integer, p_status text, p_plan uuid, p_original_review uuid, p_policy uuid, p_expires timestamp with time zone, p_personally_reviewed boolean, p_note text, p_findings jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE authority record; saved public.acquisition_contract_reviews%ROWTYPE; prior public.acquisition_contract_reviews%ROWTYPE;
 title public.acquisition_contract_reviews%ROWTYPE; executed public.acquisition_contract_reviews%ROWTYPE;
 execution public.acquisition_contract_transitions%ROWTYPE; plan public.acquisition_disposition_plans%ROWTYPE;
 policy private.acquisition_contract_review_policies%ROWTYPE; scope private.acquisition_disposition_policy_scopes%ROWTYPE;
 resolved jsonb; sources jsonb; bound jsonb; originals jsonb; snapshot jsonb; fingerprint text; seq integer; stamped timestamptz;
BEGIN
 IF p_id IS NULL OR p_workspace IS NULL OR p_contract IS NULL OR p_version IS NULL OR p_version<1
  OR p_expected_sequence IS NULL OR p_expected_sequence NOT BETWEEN 0 AND 2147483646
  OR p_status IS NULL OR p_status NOT IN ('approved','requires_resolution','withdrawn') OR p_plan IS NULL OR p_policy IS NULL
  OR p_personally_reviewed IS NULL OR p_note IS NULL OR length(btrim(p_note,E' \t\n\r\f\v'))<20 OR length(p_note)>4000
  OR (p_status<>'withdrawn' AND (NOT p_personally_reviewed OR p_original_review IS NOT NULL
   OR private.valid_disposition_findings(p_findings,p_version,p_status='approved',p_findings->>'exit_type') IS DISTINCT FROM true))
  OR (p_status='approved' AND (p_expires IS NULL OR NOT isfinite(p_expires)))
  OR (p_status='requires_resolution' AND p_expires IS NOT NULL)
  OR (p_status='withdrawn' AND (p_personally_reviewed OR p_expires IS NOT NULL OR p_findings IS NOT NULL
   OR p_original_review IS NULL OR p_original_review=p_id OR p_expected_sequence<1)) THEN
  RAISE EXCEPTION 'Exact human disposition review required' USING ERRCODE='22023'; END IF;
 SELECT * INTO authority FROM private.lock_contract_document_context(p_workspace,p_contract,p_version,ARRAY['owner','admin']);
 PERFORM pg_advisory_xact_lock(hashtextextended('contract-review:'||p_id::text,0));
 fingerprint:=encode(sha256(convert_to(jsonb_build_array(p_workspace,p_contract,p_version,'disposition_findings',p_expected_sequence,
  p_status,p_plan,p_original_review,p_policy,p_expires,p_personally_reviewed,p_note,p_findings,auth.uid(),auth.jwt()->>'session_id')::text,'UTF8')),'hex');
 IF authority.session_expires IS NOT NULL AND authority.session_expires<=clock_timestamp() THEN RAISE EXCEPTION 'Review session expired' USING ERRCODE='42501'; END IF;
 SELECT * INTO saved FROM public.acquisition_contract_reviews WHERE id=p_id;
 IF FOUND THEN
  IF saved.request_hash IS DISTINCT FROM fingerprint THEN RAISE EXCEPTION 'Disposition request conflict' USING ERRCODE='23505'; END IF;
 ELSE
  SELECT * INTO prior FROM public.acquisition_contract_reviews WHERE workspace_id=p_workspace AND contract_id=p_contract
   AND contract_version=p_version AND kind='disposition_findings' ORDER BY sequence DESC LIMIT 1;
  seq:=coalesce(prior.sequence,0);
  IF seq<>p_expected_sequence THEN RAISE EXCEPTION 'Disposition sequence changed' USING ERRCODE='40001'; END IF;
  IF p_status='withdrawn' THEN
   IF prior.id IS DISTINCT FROM p_original_review OR prior.status NOT IN ('approved','requires_resolution')
    OR prior.actor_id<>auth.uid() OR prior.policy_id<>p_policy OR prior.disposition_plan_id<>p_plan THEN
    RAISE EXCEPTION 'Original personal disposition decision required' USING ERRCODE='55000'; END IF;
   plan.id:=prior.disposition_plan_id;plan.exit_type:=prior.disposition_exit_type;
   plan.execution_transition_id:=prior.disposition_execution_id;plan.title_entry_id:=prior.disposition_title_entry_id;
   title.id:=prior.disposition_title_review_id;title.status:=prior.disposition_title_status;
   resolved:=jsonb_build_object('artifact_id',prior.artifact_id,'verification_id',prior.verification_id,'source_version',prior.source_version,'sha256',prior.sha256);
  ELSE
   SELECT * INTO plan FROM public.acquisition_disposition_plans WHERE workspace_id=p_workspace AND contract_id=p_contract
    AND contract_version=p_version AND id=p_plan AND status='proposed';
   IF NOT FOUND THEN RAISE EXCEPTION 'Original disposition proposal required' USING ERRCODE='55000'; END IF;
   SELECT * INTO execution FROM public.acquisition_contract_transitions WHERE id=plan.execution_transition_id;
   SELECT * INTO executed FROM public.acquisition_contract_reviews WHERE id=private.acquisition_review_anchor_head(p_workspace,p_contract,p_version,execution.execution_review_id,clock_timestamp());
   SELECT * INTO title FROM public.acquisition_contract_reviews WHERE workspace_id=p_workspace AND contract_id=p_contract
    AND contract_version=p_version AND kind='title_findings' ORDER BY sequence DESC LIMIT 1;
   IF NOT FOUND OR title.status NOT IN ('approved','requires_resolution') OR title.title_execution_transition_id<>plan.execution_transition_id THEN
    RAISE EXCEPTION 'Record original title findings before disposition review' USING ERRCODE='55000'; END IF;
   originals:=private.disposition_citations(p_findings)||coalesce(executed.execution_sources,'[]')||coalesce(title.title_sources,'[]');
   FOR bound IN SELECT jsonb_build_object('artifact_id',id,'sha256',expected_sha256) FROM public.acquisition_evidence_artifacts
    WHERE workspace_id=p_workspace AND contract_id=p_contract AND id IN (
     SELECT executed.artifact_id UNION SELECT (value->>'artifact_id')::uuid FROM jsonb_array_elements(originals)) ORDER BY id LOOP
    PERFORM pg_advisory_xact_lock(hashtextextended('evidence-artifact:'||(bound->>'artifact_id'),0));
    PERFORM pg_advisory_xact_lock(hashtextextended('evidence-bytes:'||p_workspace::text||':'||(bound->>'sha256'),0));
   END LOOP;
   resolved:=private.resolve_disposition_review_sources(p_workspace,p_contract,p_version,p_plan,p_findings);sources:=resolved->'sources';
   IF p_status='approved' THEN
    PERFORM private.lock_acquisition_renewal_authority(p_workspace,p_contract,p_version,
     coalesce(title.renewal_root_id,title.id),p_policy);
   END IF;
   SELECT * INTO policy FROM private.acquisition_contract_review_policies WHERE workspace_id=p_workspace AND id=p_policy
    AND kind='disposition_findings' AND purpose='purchase_contract' AND reviewer_id=auth.uid() FOR SHARE;
   IF NOT FOUND THEN RAISE EXCEPTION 'Reviewed disposition policy required' USING ERRCODE='42501'; END IF;
   SELECT * INTO scope FROM private.acquisition_disposition_policy_scopes WHERE workspace_id=p_workspace AND policy_id=p_policy
    AND reviewer_id=auth.uid() AND exit_type=plan.exit_type FOR SHARE;
   IF NOT FOUND THEN RAISE EXCEPTION 'Reviewed exit-specific policy required' USING ERRCODE='42501'; END IF;
   snapshot:=jsonb_build_object('reviewer',to_jsonb(policy),'scope',to_jsonb(scope));stamped:=clock_timestamp();
   IF NOT private.disposition_policy_current(p_workspace,p_policy,auth.uid(),plan.exit_type,stamped,snapshot) THEN
    RAISE EXCEPTION 'Disposition policy unavailable' USING ERRCODE='55000'; END IF;
   IF plan.exit_type='wholesale_assignment' AND (p_status='approved' OR p_findings->'assignment'->'legal_basis'->>'finding'='satisfactory') AND (NOT EXISTS(
    SELECT 1 FROM jsonb_array_elements(p_findings->'assignment'->'legal_basis'->'sources') c WHERE c->>'artifact_id'=scope.legal_source_id::text)
    OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(sources) c WHERE c->>'artifact_id'=scope.legal_source_id::text)) THEN
    RAISE EXCEPTION 'Policy-bound original legal evidence required' USING ERRCODE='55000'; END IF;
   IF p_status='approved' AND (p_expires<=stamped OR p_expires>least(policy.valid_until,scope.valid_until,
    stamped+make_interval(secs=>policy.max_review_seconds),(resolved->>'expires_at')::timestamptz,executed.expires_at,title.expires_at)
    OR NOT private.title_review_current(title.id,stamped) OR NOT private.execution_review_current(executed.id,stamped)) THEN
    RAISE EXCEPTION 'Current bounded title, execution and disposition authority required' USING ERRCODE='55000'; END IF;
   FOR bound IN SELECT value FROM jsonb_array_elements(sources) LOOP
    IF (bound->>'expires_at')::timestamptz<=stamped OR NOT private.contract_review_evidence_current(p_workspace,p_contract,
     (bound->>'source_version')::integer,(bound->>'artifact_id')::uuid,(bound->>'verification_id')::uuid,bound->>'sha256',bound->>'purpose',stamped) THEN
     RAISE EXCEPTION 'Disposition source changed while waiting' USING ERRCODE='55000'; END IF;
   END LOOP;
  END IF;
  stamped:=clock_timestamp();
  IF authority.session_expires IS NOT NULL AND (authority.session_expires<=stamped OR (p_status='approved' AND p_expires>authority.session_expires)) THEN
   RAISE EXCEPTION 'Review session expired' USING ERRCODE='42501'; END IF;
  INSERT INTO public.acquisition_contract_reviews(id,workspace_id,contract_id,contract_version,kind,sequence,status,artifact_id,verification_id,
   purpose,sha256,policy_id,actor_id,session_id,actor_membership_updated_at,personally_reviewed,note,expires_at,request_hash,created_at,evidence_version,
   disposition_findings,disposition_sources,disposition_plan_id,disposition_exit_type,disposition_execution_id,disposition_title_entry_id,
   disposition_title_review_id,disposition_title_status,disposition_original_review_id,disposition_original_status,disposition_policy_snapshot)
  VALUES(p_id,p_workspace,p_contract,p_version,'disposition_findings',seq+1,p_status,(resolved->>'artifact_id')::uuid,(resolved->>'verification_id')::uuid,
   'purchase_contract',resolved->>'sha256',p_policy,auth.uid(),(auth.jwt()->>'session_id')::uuid,authority.actor_updated,p_personally_reviewed,p_note,
   p_expires,fingerprint,stamped,(resolved->>'source_version')::integer,p_findings,sources,plan.id,plan.exit_type,plan.execution_transition_id,plan.title_entry_id,
   title.id,title.status,CASE WHEN p_status='withdrawn' THEN prior.id END,CASE WHEN p_status='withdrawn' THEN prior.status END,snapshot) RETURNING * INTO saved;
  IF p_status='approved' AND NOT private.disposition_review_current(saved.id,clock_timestamp()) THEN
   RAISE EXCEPTION 'Disposition authority changed before save' USING ERRCODE='55000'; END IF;
  INSERT INTO public.audit_logs(entity_type,entity_id,action,actor,workspace_id,new_value)
  VALUES('acquisition_contract_review',p_id::text,p_status,auth.uid()::text,p_workspace,jsonb_build_object('contract_id',p_contract,
   'contract_version',p_version,'kind','disposition_findings','sequence',saved.sequence,'plan_id',plan.id,'exit_type',plan.exit_type,
   'title_review_id',title.id,'original_review_id',saved.disposition_original_review_id,'sources',sources,'policy_id',p_policy,
   'expires_at',p_expires,'execution_authorized',false));
  RETURN jsonb_build_object('review_id',saved.id,'workspace_id',saved.workspace_id,'contract_id',saved.contract_id,'contract_version',saved.contract_version,
   'kind',saved.kind,'sequence',saved.sequence,'status',saved.status,'duplicate',false,'review_recorded',true,'approval_current',false,'execution_authorized',false);
 END IF;
 RETURN jsonb_build_object('review_id',saved.id,'workspace_id',saved.workspace_id,'contract_id',saved.contract_id,'contract_version',saved.contract_version,
  'kind',saved.kind,'sequence',saved.sequence,'status',saved.status,'duplicate',true,'review_recorded',true,'approval_current',false,'execution_authorized',false);
END $function$

CREATE OR REPLACE FUNCTION private.record_execution_review(p_id uuid, p_workspace uuid, p_contract uuid, p_version integer, p_expected_sequence integer, p_status text, p_artifact uuid, p_verification uuid, p_policy uuid, p_expires timestamp with time zone, p_personally_reviewed boolean, p_note text, p_findings jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE saved public.acquisition_contract_reviews%ROWTYPE; prior public.acquisition_contract_reviews%ROWTYPE;
 artifact public.acquisition_evidence_artifacts%ROWTYPE; verification public.acquisition_evidence_verifications%ROWTYPE;
 policy private.acquisition_contract_review_policies%ROWTYPE; authority record; source_ref record;
 p_kind constant text:='executed_contract'; prepared jsonb; source jsonb; bound jsonb; sources jsonb:='[]'::jsonb; source_deadline timestamptz; source_id uuid;
 fingerprint text; stamped timestamptz; deadline timestamptz; active boolean; seq integer;
BEGIN
 IF p_id IS NULL OR p_workspace IS NULL OR (p_status='approved' AND NOT private.valid_execution_findings(p_findings,p_version)) OR (p_status='withdrawn' AND p_findings IS NOT NULL)
  OR p_expected_sequence IS NULL OR p_expected_sequence<0 OR p_expected_sequence>=2147483647
  OR p_status IS NULL OR p_status NOT IN ('approved','withdrawn') OR p_artifact IS NULL OR p_verification IS NULL OR p_policy IS NULL
  OR p_note IS NULL OR length(trim(p_note)) NOT BETWEEN 20 AND 4000 OR p_personally_reviewed IS NULL
  OR (p_status='approved' AND (NOT p_personally_reviewed OR p_expires IS NULL OR NOT isfinite(p_expires)))
  OR (p_status='withdrawn' AND (p_personally_reviewed OR p_expires IS NOT NULL)) THEN
  RAISE EXCEPTION 'Exact human review request required' USING ERRCODE='22023'; END IF;
 SELECT * INTO authority FROM private.lock_contract_document_context(p_workspace,p_contract,p_version,ARRAY['owner','admin']);
 PERFORM pg_advisory_xact_lock(hashtextextended('contract-review:'||p_id::text,0));
 fingerprint:=encode(sha256(convert_to(jsonb_build_object('workspace',p_workspace,'contract',p_contract,'version',p_version,'kind',p_kind,
  'expected_sequence',p_expected_sequence,'status',p_status,'artifact',p_artifact,'verification',p_verification,'policy',p_policy,
  'execution_findings',p_findings,'expires',p_expires,'personally_reviewed',p_personally_reviewed,'note',p_note,'actor',auth.uid(),'session',auth.jwt()->>'session_id')::text,'UTF8')),'hex');
 IF authority.session_expires IS NOT NULL AND authority.session_expires<=clock_timestamp() THEN
  RAISE EXCEPTION 'Review session expired' USING ERRCODE='42501'; END IF;
 SELECT * INTO saved FROM public.acquisition_contract_reviews WHERE id=p_id;
 IF FOUND THEN
  IF saved.request_hash IS DISTINCT FROM fingerprint THEN RAISE EXCEPTION 'Review request conflict' USING ERRCODE='23505'; END IF;
  RETURN jsonb_build_object('review_id',saved.id,'workspace_id',saved.workspace_id,'contract_id',saved.contract_id,'contract_version',saved.contract_version,
   'kind',saved.kind,'sequence',saved.sequence,'status',saved.status,'duplicate',true,'review_recorded',true,'approval_current',false,'execution_authorized',false);
 END IF;
 SELECT * INTO prior FROM public.acquisition_contract_reviews WHERE workspace_id=p_workspace AND contract_id=p_contract AND contract_version=p_version AND kind=p_kind ORDER BY sequence DESC LIMIT 1;
 seq:=coalesce(prior.sequence,0);
 IF seq<>p_expected_sequence THEN RAISE EXCEPTION 'Review sequence changed' USING ERRCODE='40001'; END IF;
 IF p_status='withdrawn' THEN
  IF prior.id IS NULL OR prior.status<>'approved' OR prior.actor_id<>auth.uid() OR prior.policy_id<>p_policy
   OR prior.artifact_id<>p_artifact OR prior.verification_id<>p_verification THEN
   RAISE EXCEPTION 'Original approved review required for withdrawal' USING ERRCODE='55000'; END IF;
  -- Withdrawal can reduce authority even after policy/activation/evidence expiry.
  artifact.purpose:=prior.purpose; artifact.expected_sha256:=prior.sha256; artifact.contract_version:=prior.source_version;
 ELSE
  SELECT enabled INTO active FROM private.acquisition_activation WHERE singleton FOR SHARE;
  IF active IS DISTINCT FROM true THEN RAISE EXCEPTION 'Acquisition paused' USING ERRCODE='55000'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.deals WHERE id=p_contract AND workspace_id=p_workspace AND acquisition_version=p_version
    AND acquisition_status='pending_signature') THEN
   RAISE EXCEPTION 'Current contract version required' USING ERRCODE='55000'; END IF;
  SELECT terms INTO prepared FROM public.acquisition_contract_versions
   WHERE workspace_id=p_workspace AND deal_id=p_contract AND version=p_version;
  IF NOT private.execution_findings_match(p_workspace,p_contract,p_version,p_findings,prepared,clock_timestamp()) THEN
   RAISE EXCEPTION 'Current matching complete execution terms required' USING ERRCODE='55000'; END IF;
  -- Lock every original in deterministic identity order before rechecking all of
  -- them at one final time. The main returned agreement is included independently
  -- of which documents supplied monetary/deadline clauses.
  FOR source_id IN SELECT id FROM (
   SELECT p_artifact AS id UNION SELECT (value->>'artifact_id')::uuid FROM jsonb_array_elements(p_findings->'terms'->'sources')
   UNION SELECT (item->>'artifact_id')::uuid FROM jsonb_array_elements(coalesce(p_findings->'deadline_reviews','[]'::jsonb)) b
    JOIN public.acquisition_contract_reviews r ON r.id=(b->>'review_id')::uuid
     AND r.workspace_id=p_workspace AND r.contract_id=p_contract AND r.contract_version=p_version
     AND r.kind='deadline_resolution' AND r.deadline_term=b->>'term'
    CROSS JOIN LATERAL jsonb_array_elements(r.deadline_sources) item) originals ORDER BY id LOOP
   SELECT * INTO source_ref FROM private.contract_document_reference(p_workspace,p_contract,p_version,source_id);
   IF NOT FOUND OR source_ref.link_revoked THEN RAISE EXCEPTION 'Current original source reference required' USING ERRCODE='55000'; END IF;
   PERFORM pg_advisory_xact_lock(hashtextextended('evidence-artifact:'||source_id::text,0));
   SELECT * INTO artifact FROM public.acquisition_evidence_artifacts WHERE workspace_id=p_workspace AND contract_id=p_contract
    AND contract_version=source_ref.source_version AND id=source_id AND campaign_id IS NULL;
   IF NOT FOUND OR (source_id=p_artifact AND artifact.purpose<>'purchase_contract') THEN
    RAISE EXCEPTION 'Exact execution source unavailable' USING ERRCODE='55000'; END IF;
   FOR source IN SELECT value FROM jsonb_array_elements(p_findings->'terms'->'sources') WHERE (value->>'artifact_id')::uuid=source_id LOOP
    IF (source->>'artifact_version')::integer<>artifact.contract_version OR source->>'sha256'<>artifact.expected_sha256 THEN
     RAISE EXCEPTION 'Original execution source identity changed' USING ERRCODE='55000'; END IF;
   END LOOP;
   PERFORM pg_advisory_xact_lock(hashtextextended('evidence-bytes:'||p_workspace::text||':'||artifact.expected_sha256,0));
   SELECT * INTO verification FROM public.acquisition_evidence_verifications WHERE workspace_id=p_workspace AND artifact_id=source_id
    ORDER BY created_at DESC,id DESC LIMIT 1;
   IF NOT FOUND OR (source_id=p_artifact AND verification.id<>p_verification) THEN
    RAISE EXCEPTION 'Exact current execution source scan required' USING ERRCODE='55000'; END IF;
   SELECT least(artifact.retain_until,rp.valid_until,k.valid_until,ks.valid_until,s.not_after)
    INTO source_deadline FROM private.acquisition_evidence_verification_keys k
    JOIN private.acquisition_contract_verification_key_scopes ks ON ks.workspace_id=k.workspace_id AND ks.key_id=k.id AND ks.purpose=artifact.purpose
    JOIN private.acquisition_evidence_policies rp ON rp.workspace_id=k.workspace_id AND rp.id=artifact.retention_policy_id
    JOIN public.workspace_memberships m ON m.workspace_id=k.workspace_id AND m.user_id=verification.actor_id
    JOIN public.profiles profile ON profile.id=m.user_id JOIN auth.sessions s ON s.id=verification.session_id AND s.user_id=m.user_id
    WHERE k.id=verification.key_id AND k.workspace_id=p_workspace FOR SHARE OF k,ks,rp,m,profile,s;
   IF source_deadline IS NULL THEN RAISE EXCEPTION 'Execution source authority missing' USING ERRCODE='55000'; END IF;
   sources:=sources||jsonb_build_array(jsonb_build_object('artifact_id',source_id,'source_version',artifact.contract_version,
    'verification_id',verification.id,'sha256',artifact.expected_sha256,'purpose',artifact.purpose,'expires_at',source_deadline));
  END LOOP;
  SELECT * INTO policy FROM private.acquisition_contract_review_policies WHERE id=p_policy AND workspace_id=p_workspace
   AND kind=p_kind AND purpose='purchase_contract' AND reviewer_id=auth.uid() FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Reviewed human execution authority required' USING ERRCODE='42501'; END IF;
  deadline:=private.lock_execution_deadline_authority(p_workspace,p_contract,p_version,p_findings);
  stamped:=clock_timestamp();
  IF p_expires>deadline OR policy.revoked_at IS NOT NULL OR NOT(policy.valid_from<=stamped AND stamped<policy.valid_until)
   OR p_expires<=stamped OR p_expires>policy.valid_until OR p_expires>stamped+make_interval(secs=>policy.max_review_seconds)
   OR NOT private.execution_findings_match(p_workspace,p_contract,p_version,p_findings,prepared,stamped) THEN
   RAISE EXCEPTION 'Current bounded execution review required' USING ERRCODE='55000'; END IF;
  FOR bound IN SELECT value FROM jsonb_array_elements(sources) LOOP
   IF p_expires>(bound->>'expires_at')::timestamptz OR NOT private.contract_review_evidence_current(p_workspace,p_contract,
    (bound->>'source_version')::integer,(bound->>'artifact_id')::uuid,(bound->>'verification_id')::uuid,
    bound->>'sha256',bound->>'purpose',stamped) THEN
    RAISE EXCEPTION 'Execution source authority changed while waiting' USING ERRCODE='55000'; END IF;
  END LOOP;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(p_findings->'deadline_reviews','[]'::jsonb)) b
   JOIN public.acquisition_contract_reviews r ON r.id=(b->>'review_id')::uuid
   CROSS JOIN LATERAL jsonb_array_elements(r.deadline_sources) item
   WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(sources) retained WHERE
    retained->>'artifact_id'=item->>'artifact_id' AND retained->>'source_version'=item->>'source_version'
    AND retained->>'verification_id'=item->>'verification_id' AND retained->>'sha256'=item->>'sha256'
    AND retained->>'purpose'=item->>'purpose')) THEN
   RAISE EXCEPTION 'Deadline source identity changed' USING ERRCODE='55000'; END IF;
  SELECT * INTO artifact FROM public.acquisition_evidence_artifacts WHERE id=p_artifact;
 END IF;
 stamped:=clock_timestamp();
 IF authority.session_expires IS NOT NULL AND (authority.session_expires<=stamped OR (p_status='approved' AND p_expires>authority.session_expires)) THEN RAISE EXCEPTION 'Review session expired' USING ERRCODE='42501'; END IF;
 INSERT INTO public.acquisition_contract_reviews(id,workspace_id,contract_id,contract_version,kind,sequence,status,artifact_id,verification_id,purpose,sha256,policy_id,
  actor_id,session_id,actor_membership_updated_at,personally_reviewed,note,expires_at,request_hash,created_at,evidence_version,execution_findings,execution_sources)
 VALUES(p_id,p_workspace,p_contract,p_version,p_kind,seq+1,p_status,p_artifact,p_verification,artifact.purpose,artifact.expected_sha256,p_policy,
  auth.uid(),(auth.jwt()->>'session_id')::uuid,authority.actor_updated,p_personally_reviewed,p_note,p_expires,fingerprint,stamped,artifact.contract_version,p_findings,CASE WHEN p_status='approved' THEN sources ELSE NULL END);
 INSERT INTO public.audit_logs(entity_type,entity_id,action,actor,workspace_id,new_value)
 VALUES('acquisition_contract_review',p_id::text,p_status,auth.uid()::text,p_workspace,
  jsonb_build_object('contract_id',p_contract,'contract_version',p_version,'kind',p_kind,'sequence',seq+1,'artifact_id',p_artifact,'verification_id',p_verification,
   'policy_id',p_policy,'source_version',artifact.contract_version,'expires_at',p_expires,'execution_sources',CASE WHEN p_status='approved' THEN sources ELSE NULL END,'execution_authorized',false));
 RETURN jsonb_build_object('review_id',p_id,'workspace_id',p_workspace,'contract_id',p_contract,'contract_version',p_version,'kind',p_kind,'sequence',seq+1,
  'status',p_status,'duplicate',false,'review_recorded',true,'approval_current',false,'execution_authorized',false);
END $function$

CREATE OR REPLACE FUNCTION private.record_signature_review(p_id uuid, p_workspace uuid, p_contract uuid, p_version integer, p_expected_sequence integer, p_status text, p_basis uuid, p_policy uuid, p_expires timestamp with time zone, p_personally_reviewed boolean, p_note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE authority record; prior public.acquisition_signature_reviews%ROWTYPE; saved public.acquisition_signature_reviews%ROWTYPE;
 basis public.acquisition_contract_reviews%ROWTYPE; policy private.acquisition_signature_policies%ROWTYPE;
 fingerprint text; stamped timestamptz; seq integer; active boolean;
BEGIN
 IF p_id IS NULL OR p_basis IS NULL OR p_policy IS NULL OR p_expected_sequence IS NULL OR p_expected_sequence NOT BETWEEN 0 AND 2147483646
  OR p_status IS NULL OR p_status NOT IN ('approved','withdrawn') OR p_personally_reviewed IS NULL
  OR p_note IS NULL OR length(trim(p_note)) NOT BETWEEN 20 AND 4000
  OR (p_status='approved' AND (NOT p_personally_reviewed OR p_expires IS NULL OR NOT isfinite(p_expires)))
  OR (p_status='withdrawn' AND (p_personally_reviewed OR p_expires IS NOT NULL)) THEN
  RAISE EXCEPTION 'Exact signature review request required' USING ERRCODE='22023'; END IF;
 SELECT * INTO authority FROM private.lock_contract_document_context(p_workspace,p_contract,p_version,ARRAY['owner','admin']);
 PERFORM pg_advisory_xact_lock(hashtextextended('signature-review:'||p_id::text,0));
 fingerprint:=encode(sha256(convert_to(jsonb_build_array(p_workspace,p_contract,p_version,p_expected_sequence,p_status,p_basis,p_policy,
  p_expires,p_personally_reviewed,p_note,auth.uid(),auth.jwt()->>'session_id')::text,'UTF8')),'hex');
 IF authority.session_expires IS NOT NULL AND authority.session_expires<=clock_timestamp() THEN
  RAISE EXCEPTION 'Signature review session expired' USING ERRCODE='42501'; END IF;
 SELECT * INTO saved FROM public.acquisition_signature_reviews WHERE id=p_id;
 IF FOUND THEN
  IF saved.request_hash IS DISTINCT FROM fingerprint THEN RAISE EXCEPTION 'Signature review request conflict' USING ERRCODE='23505'; END IF;
 ELSE
  SELECT * INTO prior FROM public.acquisition_signature_reviews WHERE workspace_id=p_workspace AND contract_id=p_contract AND contract_version=p_version ORDER BY sequence DESC LIMIT 1;
  seq:=coalesce(prior.sequence,0);
  IF seq<>p_expected_sequence THEN RAISE EXCEPTION 'Signature review sequence changed' USING ERRCODE='40001'; END IF;
  IF p_status='withdrawn' THEN
   IF prior.id IS NULL OR prior.status<>'approved' OR prior.actor_id<>auth.uid() OR prior.basis_review_id<>p_basis OR prior.policy_id<>p_policy THEN
    RAISE EXCEPTION 'Original signature review required for withdrawal' USING ERRCODE='55000'; END IF;
  ELSE
   SELECT enabled INTO active FROM private.acquisition_activation WHERE singleton FOR SHARE;
   IF active IS DISTINCT FROM true THEN RAISE EXCEPTION 'Acquisition paused' USING ERRCODE='55000'; END IF;
   SELECT * INTO basis FROM public.acquisition_contract_reviews WHERE workspace_id=p_workspace AND contract_id=p_contract AND contract_version=p_version AND id=p_basis AND kind='contract_review';
   IF NOT FOUND THEN RAISE EXCEPTION 'Exact contract review required' USING ERRCODE='42501'; END IF;
   PERFORM pg_advisory_xact_lock(hashtextextended('evidence-artifact:'||basis.artifact_id::text,0));
   PERFORM pg_advisory_xact_lock(hashtextextended('evidence-bytes:'||p_workspace::text||':'||basis.sha256,0));
   SELECT * INTO policy FROM private.acquisition_signature_policies WHERE id=p_policy AND workspace_id=p_workspace
    AND contract_id=p_contract AND contract_version=p_version AND reviewer_id=auth.uid()
    AND basis_policy_id=basis.policy_id AND artifact_id=basis.artifact_id AND source_version=basis.source_version AND sha256=basis.sha256 FOR SHARE;
   IF NOT FOUND THEN RAISE EXCEPTION 'Exact signature reviewer policy required' USING ERRCODE='42501'; END IF;
   -- Pin underlying review and scanner authority through commit. All review writes
   -- for this contract share deal-ref; shared identity locks do not mutate authority.
   PERFORM 1 FROM private.acquisition_contract_review_policies WHERE id=basis.policy_id FOR SHARE;
   PERFORM 1 FROM public.acquisition_evidence_artifacts a
    JOIN public.acquisition_evidence_verifications v ON v.workspace_id=a.workspace_id AND v.artifact_id=a.id AND v.id=basis.verification_id
    JOIN private.acquisition_evidence_policies rp ON rp.workspace_id=a.workspace_id AND rp.id=a.retention_policy_id
    JOIN private.acquisition_evidence_verification_keys k ON k.workspace_id=v.workspace_id AND k.id=v.key_id
    JOIN private.acquisition_contract_verification_key_scopes ks ON ks.workspace_id=k.workspace_id AND ks.key_id=k.id AND ks.purpose=a.purpose
    WHERE a.workspace_id=p_workspace AND a.id=basis.artifact_id FOR SHARE OF rp,k,ks;
   PERFORM 1 FROM public.workspace_memberships m JOIN public.profiles profile ON profile.id=m.user_id
    JOIN auth.sessions sess ON sess.user_id=m.user_id
    WHERE m.workspace_id=p_workspace AND (sess.id=basis.session_id OR sess.id=(SELECT session_id FROM public.acquisition_evidence_verifications WHERE id=basis.verification_id))
    ORDER BY m.user_id,sess.id FOR SHARE OF m,profile,sess;
   stamped:=clock_timestamp();
   IF policy.revoked_at IS NOT NULL OR NOT(policy.valid_from<=stamped AND stamped<policy.valid_until)
    OR p_expires<=stamped OR p_expires>policy.valid_until OR p_expires>basis.expires_at
    OR p_expires>stamped+make_interval(secs=>policy.max_review_seconds)
    OR (authority.session_expires IS NOT NULL AND p_expires>authority.session_expires)
    OR NOT private.signature_basis_current(p_workspace,p_contract,p_version,p_basis,stamped) THEN
    RAISE EXCEPTION 'Current contract review and bounded signature approval required' USING ERRCODE='55000'; END IF;
  END IF;
  stamped:=clock_timestamp();
  IF authority.session_expires IS NOT NULL AND authority.session_expires<=stamped THEN RAISE EXCEPTION 'Signature review session expired' USING ERRCODE='42501'; END IF;
  INSERT INTO public.acquisition_signature_reviews(id,workspace_id,contract_id,contract_version,sequence,status,basis_review_id,policy_id,
   actor_id,session_id,actor_membership_updated_at,personally_reviewed,note,expires_at,request_hash,created_at)
  VALUES(p_id,p_workspace,p_contract,p_version,seq+1,p_status,p_basis,p_policy,auth.uid(),(auth.jwt()->>'session_id')::uuid,
   authority.actor_updated,p_personally_reviewed,p_note,p_expires,fingerprint,stamped) RETURNING * INTO saved;
  INSERT INTO public.audit_logs(entity_type,entity_id,action,actor,workspace_id,new_value)
  VALUES('acquisition_signature_review',p_id::text,p_status,auth.uid()::text,p_workspace,
   jsonb_build_object('contract_id',p_contract,'contract_version',p_version,'sequence',saved.sequence,'basis_review_id',p_basis,'policy_id',p_policy,'execution_authorized',false));
  RETURN jsonb_build_object('review_id',saved.id,'workspace_id',p_workspace,'contract_id',p_contract,'contract_version',p_version,
   'sequence',saved.sequence,'status',saved.status,'duplicate',false,'review_recorded',true,'approval_current',false,'execution_authorized',false);
 END IF;
 RETURN jsonb_build_object('review_id',saved.id,'workspace_id',saved.workspace_id,'contract_id',saved.contract_id,'contract_version',saved.contract_version,
  'sequence',saved.sequence,'status',saved.status,'duplicate',true,'review_recorded',true,'approval_current',false,'execution_authorized',false);
END $function$

CREATE OR REPLACE FUNCTION private.record_title_review(p_id uuid, p_workspace uuid, p_contract uuid, p_version integer, p_expected_sequence integer, p_status text, p_artifact uuid, p_verification uuid, p_policy uuid, p_expires timestamp with time zone, p_personally_reviewed boolean, p_note text, p_findings jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE authority record; saved public.acquisition_contract_reviews%ROWTYPE; prior public.acquisition_contract_reviews%ROWTYPE;
 execution public.acquisition_contract_transitions%ROWTYPE; executed public.acquisition_contract_reviews%ROWTYPE;
 policy private.acquisition_contract_review_policies%ROWTYPE; artifact public.acquisition_evidence_artifacts%ROWTYPE;
 sources jsonb; resolved jsonb; bound jsonb; originals jsonb:='[]'; name text; fingerprint text;
 seq integer; stamped timestamptz; fresh_until timestamptz;
BEGIN
 IF p_id IS NULL OR p_workspace IS NULL OR p_contract IS NULL OR p_version IS NULL OR p_version<1
  OR p_expected_sequence IS NULL OR p_expected_sequence NOT BETWEEN 0 AND 2147483646
  OR p_status IS NULL OR p_status NOT IN ('approved','requires_resolution','withdrawn')
  OR p_artifact IS NULL OR p_verification IS NULL OR p_policy IS NULL OR p_personally_reviewed IS NULL
  OR p_note IS NULL OR length(btrim(p_note,E' \t\n\r\f\v'))<20 OR length(p_note)>4000
  OR (p_status<>'withdrawn' AND (NOT p_personally_reviewed OR private.valid_title_findings(p_findings,p_version,p_status='approved') IS DISTINCT FROM true))
  OR (p_status='approved' AND (p_expires IS NULL OR NOT isfinite(p_expires)))
  OR (p_status='requires_resolution' AND p_expires IS NOT NULL)
  OR (p_status='withdrawn' AND (p_personally_reviewed OR p_expires IS NOT NULL OR p_findings IS NOT NULL)) THEN
  RAISE EXCEPTION 'Exact human title review required' USING ERRCODE='22023'; END IF;
 SELECT * INTO authority FROM private.lock_contract_document_context(p_workspace,p_contract,p_version,ARRAY['owner','admin']);
 PERFORM pg_advisory_xact_lock(hashtextextended('contract-review:'||p_id::text,0));
 fingerprint:=encode(sha256(convert_to(jsonb_build_array(p_workspace,p_contract,p_version,'title_findings',p_expected_sequence,
  p_status,p_artifact,p_verification,p_policy,p_expires,p_personally_reviewed,p_note,p_findings,auth.uid(),auth.jwt()->>'session_id')::text,'UTF8')),'hex');
 IF authority.session_expires IS NOT NULL AND authority.session_expires<=clock_timestamp() THEN RAISE EXCEPTION 'Review session expired' USING ERRCODE='42501'; END IF;
 SELECT * INTO saved FROM public.acquisition_contract_reviews WHERE id=p_id;
 IF FOUND THEN
  IF saved.request_hash IS DISTINCT FROM fingerprint THEN RAISE EXCEPTION 'Title request conflict' USING ERRCODE='23505'; END IF;
 ELSE
  SELECT * INTO prior FROM public.acquisition_contract_reviews WHERE workspace_id=p_workspace AND contract_id=p_contract
   AND contract_version=p_version AND kind='title_findings' ORDER BY sequence DESC LIMIT 1;
  seq:=coalesce(prior.sequence,0);
  IF seq<>p_expected_sequence THEN RAISE EXCEPTION 'Title review sequence changed' USING ERRCODE='40001'; END IF;
  IF p_status='withdrawn' THEN
   IF prior.id IS NULL OR prior.status NOT IN ('approved','requires_resolution') OR prior.actor_id<>auth.uid()
    OR prior.policy_id<>p_policy OR prior.artifact_id<>p_artifact OR prior.verification_id<>p_verification THEN
    RAISE EXCEPTION 'Original title decision required for withdrawal' USING ERRCODE='55000'; END IF;
   artifact.purpose:=prior.purpose;artifact.expected_sha256:=prior.sha256;artifact.contract_version:=prior.source_version;
   execution.id:=prior.title_execution_transition_id;
  ELSE
   SELECT * INTO execution FROM public.acquisition_contract_transitions WHERE workspace_id=p_workspace AND contract_id=p_contract
    AND contract_version=p_version AND sequence=2 AND recorded_status='executed';
   IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.acquisition_contract_transitions WHERE workspace_id=p_workspace AND contract_id=p_contract
    AND contract_version=p_version AND sequence=3 AND recorded_status='title_review' AND execution_review_id=execution.execution_review_id) THEN
    RAISE EXCEPTION 'Exact recorded execution and title entry required' USING ERRCODE='55000'; END IF;
   SELECT * INTO executed FROM public.acquisition_contract_reviews WHERE id=private.acquisition_review_anchor_head(p_workspace,p_contract,p_version,execution.execution_review_id,clock_timestamp());
   -- Lock the combined original set before acquiring scanner/policy locks. The
   -- contract context serializes reference edits, review withdrawals and stages.
   IF p_findings->'report_as_of_source'<>'null'::jsonb THEN originals:=jsonb_build_array(p_findings->'report_as_of_source'); END IF;
   FOREACH name IN ARRAY ARRAY['ownership','legal_description','liens_and_payoffs','exceptions_and_encumbrances','occupancy_and_possession'] LOOP originals:=originals||(p_findings->name->'sources'); END LOOP;
   FOR bound IN SELECT jsonb_build_object('artifact_id',id,'sha256',expected_sha256) FROM public.acquisition_evidence_artifacts
    WHERE workspace_id=p_workspace AND contract_id=p_contract AND id IN (
     SELECT p_artifact UNION SELECT (value->>'artifact_id')::uuid FROM jsonb_array_elements(originals)
     UNION SELECT (value->>'artifact_id')::uuid FROM jsonb_array_elements(executed.execution_sources)) ORDER BY id LOOP
    PERFORM pg_advisory_xact_lock(hashtextextended('evidence-artifact:'||(bound->>'artifact_id'),0));
    PERFORM pg_advisory_xact_lock(hashtextextended('evidence-bytes:'||p_workspace::text||':'||(bound->>'sha256'),0));
   END LOOP;
   resolved:=private.resolve_title_review_sources(p_workspace,p_contract,p_version,p_artifact,p_verification,p_findings);
   sources:=resolved->'sources';
   IF p_status='approved' THEN
    PERFORM private.lock_acquisition_renewal_authority(p_workspace,p_contract,p_version,
     coalesce(executed.renewal_root_id,executed.id),p_policy);
   END IF;
   SELECT * INTO policy FROM private.acquisition_contract_review_policies WHERE workspace_id=p_workspace AND id=p_policy
    AND kind='title_findings' AND purpose='title_report' AND reviewer_id=auth.uid() FOR SHARE;
   IF NOT FOUND THEN RAISE EXCEPTION 'Reviewed title authority required' USING ERRCODE='42501'; END IF;
   stamped:=clock_timestamp();
   IF policy.revoked_at IS NOT NULL OR policy.valid_from>stamped OR policy.valid_until<=stamped THEN RAISE EXCEPTION 'Title policy unavailable' USING ERRCODE='55000'; END IF;
   IF p_status='approved' THEN
    fresh_until:=private.title_report_fresh_until(p_findings->'report_as_of',policy,stamped);
    IF fresh_until IS NULL OR p_expires<=stamped OR p_expires>least(fresh_until,policy.valid_until,
      stamped+make_interval(secs=>policy.max_review_seconds),(resolved->>'expires_at')::timestamptz,executed.expires_at)
     OR NOT private.execution_review_current(executed.id,stamped) THEN
     RAISE EXCEPTION 'Current bounded title and execution review required' USING ERRCODE='55000'; END IF;
   END IF;
   FOR bound IN SELECT value FROM jsonb_array_elements(sources) LOOP
    IF (bound->>'expires_at')::timestamptz<=stamped OR NOT private.contract_review_evidence_current(p_workspace,p_contract,
     (bound->>'source_version')::integer,(bound->>'artifact_id')::uuid,(bound->>'verification_id')::uuid,bound->>'sha256',bound->>'purpose',stamped) THEN
     RAISE EXCEPTION 'Title source changed while waiting' USING ERRCODE='55000'; END IF;
   END LOOP;
   SELECT * INTO artifact FROM public.acquisition_evidence_artifacts WHERE workspace_id=p_workspace AND id=p_artifact;
  END IF;
  stamped:=clock_timestamp();
  IF authority.session_expires IS NOT NULL AND (authority.session_expires<=stamped OR (p_status='approved' AND p_expires>authority.session_expires)) THEN
   RAISE EXCEPTION 'Review session expired' USING ERRCODE='42501'; END IF;
  INSERT INTO public.acquisition_contract_reviews(id,workspace_id,contract_id,contract_version,kind,sequence,status,artifact_id,verification_id,
   purpose,sha256,policy_id,actor_id,session_id,actor_membership_updated_at,personally_reviewed,note,expires_at,request_hash,created_at,evidence_version,
   title_findings,title_sources,title_execution_transition_id,title_original_review_id,title_original_status,title_policy_snapshot)
  VALUES(p_id,p_workspace,p_contract,p_version,'title_findings',seq+1,p_status,p_artifact,p_verification,artifact.purpose,artifact.expected_sha256,p_policy,
   auth.uid(),(auth.jwt()->>'session_id')::uuid,authority.actor_updated,p_personally_reviewed,p_note,p_expires,fingerprint,stamped,artifact.contract_version,
   p_findings,sources,execution.id,CASE WHEN p_status='withdrawn' THEN prior.id END,CASE WHEN p_status='withdrawn' THEN prior.status END,
   CASE WHEN p_status<>'withdrawn' THEN to_jsonb(policy) END) RETURNING * INTO saved;
  -- A separate statement checks the exact persisted snapshot at final write time.
  IF p_status='approved' AND NOT private.title_review_current(saved.id,clock_timestamp()) THEN
   RAISE EXCEPTION 'Title approval authority changed before save' USING ERRCODE='55000'; END IF;
  INSERT INTO public.audit_logs(entity_type,entity_id,action,actor,workspace_id,new_value)
  VALUES('acquisition_contract_review',p_id::text,p_status,auth.uid()::text,p_workspace,jsonb_build_object('contract_id',p_contract,
   'contract_version',p_version,'kind','title_findings','sequence',saved.sequence,'execution_transition_id',execution.id,
   'original_review_id',saved.title_original_review_id,'sources',sources,'policy_id',p_policy,'expires_at',p_expires,'execution_authorized',false));
  RETURN jsonb_build_object('review_id',saved.id,'workspace_id',saved.workspace_id,'contract_id',saved.contract_id,'contract_version',saved.contract_version,
   'kind',saved.kind,'sequence',saved.sequence,'status',saved.status,'duplicate',false,'review_recorded',true,'approval_current',false,'execution_authorized',false);
 END IF;
 RETURN jsonb_build_object('review_id',saved.id,'workspace_id',saved.workspace_id,'contract_id',saved.contract_id,'contract_version',saved.contract_version,
  'kind',saved.kind,'sequence',saved.sequence,'status',saved.status,'duplicate',true,'review_recorded',true,'approval_current',false,'execution_authorized',false);
END $function$

CREATE OR REPLACE FUNCTION private.register_acquisition_evidence(p_id uuid, p_workspace uuid, p_campaign uuid, p_purpose text, p_sha256 text, p_byte_size integer, p_media_type text, p_policy uuid, p_note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE saved public.acquisition_evidence_artifacts%ROWTYPE; policy private.acquisition_evidence_policies%ROWTYPE;
 actor_updated timestamptz; session_expires timestamptz; active boolean; fingerprint text; stamped timestamptz;
BEGIN
 IF auth.jwt()->>'aal' IS DISTINCT FROM 'aal2' OR coalesce(private.acquisition_role(p_workspace),'') NOT IN ('owner','admin','operator') THEN
  RAISE EXCEPTION 'Evidence registration authority required' USING ERRCODE='42501'; END IF;
 IF p_id IS NULL OR p_campaign IS NULL OR p_purpose IS NULL OR p_purpose NOT IN ('mail_content','mail_destination')
  OR p_sha256 IS NULL OR p_sha256 !~ '^[0-9a-f]{64}$' OR p_byte_size IS NULL OR p_byte_size NOT BETWEEN 1 AND 10485760
  OR p_media_type IS NULL OR p_media_type NOT IN ('application/pdf','image/png','image/jpeg','text/plain')
  OR p_policy IS NULL OR p_note IS NULL OR length(trim(p_note)) NOT BETWEEN 20 AND 2000 THEN
  RAISE EXCEPTION 'Bounded evidence expectations and provenance required' USING ERRCODE='22023'; END IF;
 SELECT enabled INTO active FROM private.acquisition_activation WHERE singleton FOR SHARE;
 IF active IS DISTINCT FROM true THEN RAISE EXCEPTION 'Acquisition activation required' USING ERRCODE='55000'; END IF;
 PERFORM 1 FROM public.workspaces WHERE id=p_workspace AND status='active' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Workspace unavailable' USING ERRCODE='42501'; END IF;
 SELECT m.updated_at,s.not_after INTO actor_updated,session_expires FROM public.workspace_memberships m JOIN public.profiles p ON p.id=m.user_id
 JOIN auth.sessions s ON s.user_id=p.id WHERE m.workspace_id=p_workspace AND m.user_id=auth.uid() AND m.status='active'
  AND m.role IN ('owner','admin','operator') AND p.status='approved' AND s.id::text=auth.jwt()->>'session_id'
  AND (s.not_after IS NULL OR s.not_after>clock_timestamp()) FOR SHARE OF m,p,s;
 IF NOT FOUND THEN RAISE EXCEPTION 'Evidence registration authority changed' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.ad_campaigns WHERE workspace_id=p_workspace AND id=p_campaign AND acquisition_channel='direct_mail' AND status='draft' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Mail campaign unavailable' USING ERRCODE='42501'; END IF;
 fingerprint:=encode(sha256(convert_to(jsonb_build_array(p_workspace,p_campaign,p_purpose,p_sha256,p_byte_size,p_media_type,p_policy,p_note,auth.uid())::text,'UTF8')),'hex');
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-artifact:'||p_id::text,0));
 IF session_expires IS NOT NULL AND session_expires<=clock_timestamp() THEN RAISE EXCEPTION 'Evidence session expired' USING ERRCODE='42501'; END IF;
 SELECT * INTO saved FROM public.acquisition_evidence_artifacts WHERE id=p_id;
 IF FOUND THEN
  IF saved.request_hash IS DISTINCT FROM fingerprint THEN RAISE EXCEPTION 'Evidence request conflict' USING ERRCODE='23505'; END IF;
  RETURN jsonb_build_object('artifact_id',saved.id,'workspace_id',saved.workspace_id,'retain_until',saved.retain_until,
   'duplicate',true,'bytes_verified',false,'execution_authorized',false);
 END IF;
 SELECT * INTO policy FROM private.acquisition_evidence_policies WHERE id=p_policy AND workspace_id=p_workspace AND purpose=p_purpose FOR SHARE;
 stamped:=clock_timestamp();
 IF session_expires IS NOT NULL AND session_expires<=stamped THEN RAISE EXCEPTION 'Evidence session expired' USING ERRCODE='42501'; END IF;
 IF NOT FOUND OR policy.revoked_at IS NOT NULL OR NOT(policy.valid_from<=stamped AND stamped<policy.valid_until) THEN
  RAISE EXCEPTION 'Reviewed current retention policy required' USING ERRCODE='55000'; END IF;
 INSERT INTO public.acquisition_evidence_artifacts(id,workspace_id,campaign_id,purpose,expected_sha256,expected_byte_size,
  media_type,retention_policy_id,retain_until,provenance_note,created_by,actor_membership_updated_at,created_at,request_hash)
 VALUES(p_id,p_workspace,p_campaign,p_purpose,p_sha256,p_byte_size,p_media_type,p_policy,
  stamped+make_interval(secs=>policy.retention_seconds),p_note,auth.uid(),actor_updated,stamped,fingerprint) RETURNING * INTO saved;
 INSERT INTO public.audit_logs(entity_type,entity_id,action,actor,workspace_id,new_value)
 VALUES('acquisition_evidence',p_id::text,'registered',auth.uid()::text,p_workspace,
  jsonb_build_object('campaign_id',p_campaign,'purpose',p_purpose,'policy_id',p_policy,'bytes_verified',false,'execution_authorized',false));
 RETURN jsonb_build_object('artifact_id',saved.id,'workspace_id',saved.workspace_id,'retain_until',saved.retain_until,
  'duplicate',false,'bytes_verified',false,'execution_authorized',false);
END $function$

CREATE OR REPLACE FUNCTION private.register_contract_document(p_id uuid, p_workspace uuid, p_contract uuid, p_version integer, p_purpose text, p_sha256 text, p_byte_size integer, p_media_type text, p_policy uuid, p_note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE saved public.acquisition_evidence_artifacts%ROWTYPE; policy private.acquisition_evidence_policies%ROWTYPE;
 authority record; fingerprint text; stamped timestamptz; active boolean;
BEGIN
 IF p_id IS NULL OR p_purpose IS NULL OR p_purpose NOT IN ('purchase_contract','title_report','assignment_agreement','seller_disclosure','assignee_disclosure','closing_statement','supporting_document')
  OR p_sha256 IS NULL OR p_sha256 !~ '^[0-9a-f]{64}$' OR p_byte_size IS NULL OR p_byte_size NOT BETWEEN 1 AND 10485760
  OR p_media_type IS NULL OR p_media_type NOT IN ('application/pdf','image/png','image/jpeg','text/plain')
  OR p_policy IS NULL OR p_note IS NULL OR length(trim(p_note)) NOT BETWEEN 20 AND 2000 THEN
  RAISE EXCEPTION 'Bounded document expectations required' USING ERRCODE='22023'; END IF;
 SELECT * INTO authority FROM private.lock_contract_document_context(p_workspace,p_contract,p_version,ARRAY['owner','admin','operator']);
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-artifact:'||p_id::text,0));
 IF authority.session_expires IS NOT NULL AND authority.session_expires<=clock_timestamp() THEN
  RAISE EXCEPTION 'Document session expired' USING ERRCODE='42501'; END IF;
 fingerprint:=encode(sha256(convert_to(jsonb_build_array('contract_document',p_workspace,p_contract,p_version,p_purpose,p_sha256,p_byte_size,p_media_type,p_policy,p_note,auth.uid())::text,'UTF8')),'hex');
 SELECT * INTO saved FROM public.acquisition_evidence_artifacts WHERE id=p_id;
 IF FOUND THEN
  IF saved.request_hash IS DISTINCT FROM fingerprint OR saved.contract_id IS DISTINCT FROM p_contract
   OR saved.contract_version IS DISTINCT FROM p_version OR saved.campaign_id IS NOT NULL THEN
   RAISE EXCEPTION 'Document request conflict' USING ERRCODE='23505'; END IF;
  RETURN jsonb_build_object('artifact_id',saved.id,'workspace_id',saved.workspace_id,'contract_id',saved.contract_id,
   'contract_version',saved.contract_version,'retain_until',saved.retain_until,'duplicate',true,'bytes_verified',false,'execution_authorized',false);
 END IF;
 SELECT enabled INTO active FROM private.acquisition_activation WHERE singleton FOR SHARE;
 IF active IS DISTINCT FROM true THEN RAISE EXCEPTION 'Acquisition activation required' USING ERRCODE='55000'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.deals WHERE id=p_contract AND workspace_id=p_workspace AND acquisition_version=p_version AND acquisition_status IN ('draft','pending_signature','title_review')) THEN
  RAISE EXCEPTION 'Current document-capture version required' USING ERRCODE='55000'; END IF;
 SELECT * INTO policy FROM private.acquisition_evidence_policies WHERE id=p_policy AND workspace_id=p_workspace AND purpose=p_purpose FOR SHARE;
 stamped:=clock_timestamp();
 IF policy.id IS NULL OR policy.revoked_at IS NOT NULL OR NOT(policy.valid_from<=stamped AND stamped<policy.valid_until) THEN
  RAISE EXCEPTION 'Reviewed retention policy required' USING ERRCODE='55000'; END IF;
 IF authority.session_expires IS NOT NULL AND authority.session_expires<=stamped THEN
  RAISE EXCEPTION 'Document session expired' USING ERRCODE='42501'; END IF;
 INSERT INTO public.acquisition_evidence_artifacts(id,workspace_id,contract_id,contract_version,purpose,expected_sha256,expected_byte_size,
  media_type,retention_policy_id,retain_until,provenance_note,created_by,actor_membership_updated_at,created_at,request_hash)
 VALUES(p_id,p_workspace,p_contract,p_version,p_purpose,p_sha256,p_byte_size,p_media_type,p_policy,
  stamped+make_interval(secs=>policy.retention_seconds),p_note,auth.uid(),authority.actor_updated,stamped,fingerprint) RETURNING * INTO saved;
 INSERT INTO public.audit_logs(entity_type,entity_id,action,actor,workspace_id,new_value)
 VALUES('acquisition_contract_document',p_id::text,'registered',auth.uid()::text,p_workspace,
  jsonb_build_object('contract_id',p_contract,'contract_version',p_version,'purpose',p_purpose,'policy_id',p_policy,'bytes_verified',false,'execution_authorized',false));
 RETURN jsonb_build_object('artifact_id',saved.id,'workspace_id',saved.workspace_id,'contract_id',saved.contract_id,
  'contract_version',saved.contract_version,'retain_until',saved.retain_until,'duplicate',false,'bytes_verified',false,'execution_authorized',false);
END $function$

CREATE OR REPLACE FUNCTION private.resolve_disposition_review_sources(p_workspace uuid, p_contract uuid, p_version integer, p_plan uuid, p_findings jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE authority record; ref record; artifact public.acquisition_evidence_artifacts%ROWTYPE;
 verification public.acquisition_evidence_verifications%ROWTYPE; citation jsonb; bound jsonb;
 citations jsonb:='[]'; sources jsonb:='[]'; name text; source_id uuid; source_deadline timestamptz;
 checked timestamptz; deadline timestamptz; active boolean;
 plan public.acquisition_disposition_plans%ROWTYPE; executed public.acquisition_contract_transitions%ROWTYPE;
 original public.acquisition_contract_reviews%ROWTYPE; p_artifact uuid; p_verification uuid;
BEGIN
 IF p_workspace IS NULL OR p_contract IS NULL OR p_plan IS NULL
  OR private.valid_disposition_findings(p_findings,p_version,false,p_findings->>'exit_type') IS DISTINCT FROM true THEN
  RAISE EXCEPTION 'Exact disposition findings and original proposal required' USING ERRCODE='22023'; END IF;
 SELECT * INTO authority FROM private.lock_contract_document_context(p_workspace,p_contract,p_version,ARRAY['owner','admin']);
 SELECT enabled INTO active FROM private.acquisition_activation WHERE singleton FOR SHARE;
 IF active IS DISTINCT FROM true OR NOT EXISTS(SELECT 1 FROM public.deals WHERE workspace_id=p_workspace AND id=p_contract
  AND acquisition_version=p_version AND acquisition_status='title_review') THEN
  RAISE EXCEPTION 'Current active disposition preparation context required' USING ERRCODE='55000'; END IF;
 SELECT * INTO plan FROM public.acquisition_disposition_plans WHERE workspace_id=p_workspace AND contract_id=p_contract
  AND contract_version=p_version AND id=p_plan AND status='proposed';
 IF NOT FOUND OR plan.exit_type IS DISTINCT FROM p_findings->>'exit_type'
  OR plan.id IS DISTINCT FROM (SELECT id FROM public.acquisition_disposition_plans WHERE workspace_id=p_workspace AND contract_id=p_contract
   AND contract_version=p_version ORDER BY sequence DESC LIMIT 1) THEN
  RAISE EXCEPTION 'Current exact purchase-path proposal required' USING ERRCODE='55000'; END IF;
 SELECT * INTO executed FROM public.acquisition_contract_transitions WHERE workspace_id=p_workspace AND contract_id=p_contract
  AND contract_version=p_version AND id=plan.execution_transition_id AND recorded_status='executed';
 IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.acquisition_contract_transitions WHERE workspace_id=p_workspace AND contract_id=p_contract
  AND contract_version=p_version AND id=plan.title_entry_id AND recorded_status='title_review' AND execution_review_id=executed.execution_review_id) THEN
  RAISE EXCEPTION 'Original recorded execution and title entry required' USING ERRCODE='55000'; END IF;
 SELECT * INTO original FROM public.acquisition_contract_reviews WHERE workspace_id=p_workspace AND contract_id=p_contract
  AND contract_version=p_version AND id=private.acquisition_review_anchor_head(p_workspace,p_contract,p_version,executed.execution_review_id,clock_timestamp()) AND kind='executed_contract' AND status='approved' AND purpose='purchase_contract';
 IF NOT FOUND THEN RAISE EXCEPTION 'Original execution review required' USING ERRCODE='55000'; END IF;
 p_artifact:=original.artifact_id; p_verification:=original.verification_id;
 citations:=private.disposition_citations(p_findings);
 IF (p_findings->'contractual_interest'->>'finding'='satisfactory' AND NOT EXISTS(
    SELECT 1 FROM jsonb_array_elements(p_findings->'contractual_interest'->'sources') item WHERE item->>'artifact_id'=p_artifact::text))
  OR (plan.exit_type='wholesale_assignment' AND p_findings->'assignment'->'assignment_provisions'->>'finding'='satisfactory' AND NOT EXISTS(
    SELECT 1 FROM jsonb_array_elements(p_findings->'assignment'->'assignment_provisions'->'sources') item WHERE item->>'artifact_id'=p_artifact::text)) THEN
  RAISE EXCEPTION 'Satisfactory contract findings must cite the recorded executed original' USING ERRCODE='55000'; END IF;
 FOR source_id IN SELECT id FROM (SELECT p_artifact AS id UNION SELECT (value->>'artifact_id')::uuid FROM jsonb_array_elements(citations)) originals ORDER BY id LOOP
  SELECT * INTO ref FROM private.contract_document_reference(p_workspace,p_contract,p_version,source_id);
  IF NOT FOUND OR ref.link_revoked THEN RAISE EXCEPTION 'Current original disposition source reference required' USING ERRCODE='55000'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('evidence-artifact:'||source_id::text,0));
  SELECT * INTO artifact FROM public.acquisition_evidence_artifacts WHERE workspace_id=p_workspace AND contract_id=p_contract
   AND contract_version=ref.source_version AND id=source_id AND campaign_id IS NULL;
  IF NOT FOUND OR (source_id=p_artifact AND (artifact.purpose<>'purchase_contract' OR artifact.contract_version<>original.source_version OR artifact.expected_sha256<>original.sha256)) THEN
   RAISE EXCEPTION 'Original disposition source unavailable' USING ERRCODE='55000'; END IF;
  FOR citation IN SELECT value FROM jsonb_array_elements(citations) WHERE value->>'artifact_id'=source_id::text LOOP
   IF (citation->>'artifact_version')::integer<>artifact.contract_version OR citation->>'sha256'<>artifact.expected_sha256 THEN
    RAISE EXCEPTION 'Original disposition citation changed' USING ERRCODE='55000'; END IF;
  END LOOP;
  PERFORM pg_advisory_xact_lock(hashtextextended('evidence-bytes:'||p_workspace::text||':'||artifact.expected_sha256,0));
  SELECT * INTO verification FROM public.acquisition_evidence_verifications WHERE workspace_id=p_workspace AND artifact_id=source_id
   ORDER BY created_at DESC,id DESC LIMIT 1;
  IF NOT FOUND OR (source_id=p_artifact AND verification.id<>p_verification) THEN
   RAISE EXCEPTION 'Exact current disposition scan required' USING ERRCODE='55000'; END IF;
  SELECT least(artifact.retain_until,rp.valid_until,k.valid_until,ks.valid_until,s.not_after) INTO source_deadline
   FROM private.acquisition_evidence_verification_keys k
   JOIN private.acquisition_contract_verification_key_scopes ks ON ks.workspace_id=k.workspace_id AND ks.key_id=k.id AND ks.purpose=artifact.purpose
   JOIN private.acquisition_evidence_policies rp ON rp.workspace_id=k.workspace_id AND rp.id=artifact.retention_policy_id
   JOIN public.workspace_memberships m ON m.workspace_id=k.workspace_id AND m.user_id=verification.actor_id
   JOIN public.profiles profile ON profile.id=m.user_id JOIN auth.sessions s ON s.id=verification.session_id AND s.user_id=m.user_id
   WHERE k.id=verification.key_id AND k.workspace_id=p_workspace FOR SHARE OF k,ks,rp,m,profile,s;
  IF source_deadline IS NULL THEN RAISE EXCEPTION 'Disposition source authority missing' USING ERRCODE='55000'; END IF;
  sources:=sources||jsonb_build_array(jsonb_build_object('artifact_id',source_id,'source_version',artifact.contract_version,
   'verification_id',verification.id,'sha256',artifact.expected_sha256,'purpose',artifact.purpose,'expires_at',source_deadline));
  deadline:=least(deadline,source_deadline);
 END LOOP;
 checked:=clock_timestamp();
 IF authority.session_expires IS NOT NULL AND authority.session_expires<=checked THEN RAISE EXCEPTION 'Disposition session expired' USING ERRCODE='42501'; END IF;
 FOR bound IN SELECT value FROM jsonb_array_elements(sources) LOOP
  IF (bound->>'expires_at')::timestamptz<=checked OR NOT private.contract_review_evidence_current(p_workspace,p_contract,
   (bound->>'source_version')::integer,(bound->>'artifact_id')::uuid,(bound->>'verification_id')::uuid,
   bound->>'sha256',bound->>'purpose',checked) THEN
   RAISE EXCEPTION 'Disposition source authority changed while waiting' USING ERRCODE='55000'; END IF;
 END LOOP;
 -- The caller must recheck these exact sources after any subsequent waits and
 -- independently bind current execution/deadline/title/reviewer/legal policy authority.
 RETURN jsonb_build_object('plan_id',plan.id,'exit_type',plan.exit_type,'execution_transition_id',executed.id,
  'execution_review_id',original.id,'title_entry_id',plan.title_entry_id,'artifact_id',p_artifact,'source_version',original.source_version,
  'verification_id',p_verification,'sha256',original.sha256,'sources',sources,'checked_at',checked,'expires_at',least(deadline,authority.session_expires),
  'legal_review_approved',false,'disposition_approved',false,'marketing_authorized',false,'execution_authorized',false);
END $function$

CREATE OR REPLACE FUNCTION private.resolve_title_review_sources(p_workspace uuid, p_contract uuid, p_version integer, p_artifact uuid, p_verification uuid, p_findings jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE authority record; ref record; artifact public.acquisition_evidence_artifacts%ROWTYPE;
 verification public.acquisition_evidence_verifications%ROWTYPE; citation jsonb; bound jsonb;
 citations jsonb:='[]'; sources jsonb:='[]'; name text; source_id uuid; source_deadline timestamptz;
 checked timestamptz; deadline timestamptz; active boolean;
BEGIN
 IF p_workspace IS NULL OR p_contract IS NULL OR p_artifact IS NULL OR p_verification IS NULL
  OR private.valid_title_findings(p_findings,p_version,false) IS DISTINCT FROM true THEN
  RAISE EXCEPTION 'Exact title findings and original report required' USING ERRCODE='22023'; END IF;
 SELECT * INTO authority FROM private.lock_contract_document_context(p_workspace,p_contract,p_version,ARRAY['owner','admin']);
 SELECT enabled INTO active FROM private.acquisition_activation WHERE singleton FOR SHARE;
 IF active IS DISTINCT FROM true OR NOT EXISTS(SELECT 1 FROM public.deals WHERE workspace_id=p_workspace AND id=p_contract
  AND acquisition_version=p_version AND acquisition_status='title_review') THEN
  RAISE EXCEPTION 'Current active title-review context required' USING ERRCODE='55000'; END IF;
 IF p_findings->'report_as_of_source'<>'null'::jsonb THEN citations:=jsonb_build_array(p_findings->'report_as_of_source'); END IF;
 FOREACH name IN ARRAY ARRAY['ownership','legal_description','liens_and_payoffs','exceptions_and_encumbrances','occupancy_and_possession'] LOOP
  citations:=citations||(p_findings->name->'sources');
 END LOOP;
 IF p_findings->'report_as_of_source'<>'null'::jsonb AND p_findings->'report_as_of_source'->>'artifact_id'<>p_artifact::text THEN
  RAISE EXCEPTION 'Cutoff must cite the selected original title report' USING ERRCODE='55000'; END IF;
 FOR source_id IN SELECT id FROM (SELECT p_artifact AS id UNION SELECT (value->>'artifact_id')::uuid FROM jsonb_array_elements(citations)) originals ORDER BY id LOOP
  SELECT * INTO ref FROM private.contract_document_reference(p_workspace,p_contract,p_version,source_id);
  IF NOT FOUND OR ref.link_revoked THEN RAISE EXCEPTION 'Current original title source reference required' USING ERRCODE='55000'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('evidence-artifact:'||source_id::text,0));
  SELECT * INTO artifact FROM public.acquisition_evidence_artifacts WHERE workspace_id=p_workspace AND contract_id=p_contract
   AND contract_version=ref.source_version AND id=source_id AND campaign_id IS NULL;
  IF NOT FOUND OR (source_id=p_artifact AND artifact.purpose<>'title_report') THEN
   RAISE EXCEPTION 'Original title source unavailable' USING ERRCODE='55000'; END IF;
  FOR citation IN SELECT value FROM jsonb_array_elements(citations) WHERE value->>'artifact_id'=source_id::text LOOP
   IF (citation->>'artifact_version')::integer<>artifact.contract_version OR citation->>'sha256'<>artifact.expected_sha256 THEN
    RAISE EXCEPTION 'Original title citation changed' USING ERRCODE='55000'; END IF;
  END LOOP;
  PERFORM pg_advisory_xact_lock(hashtextextended('evidence-bytes:'||p_workspace::text||':'||artifact.expected_sha256,0));
  SELECT * INTO verification FROM public.acquisition_evidence_verifications WHERE workspace_id=p_workspace AND artifact_id=source_id
   ORDER BY created_at DESC,id DESC LIMIT 1;
  IF NOT FOUND OR (source_id=p_artifact AND verification.id<>p_verification) THEN
   RAISE EXCEPTION 'Exact current title scan required' USING ERRCODE='55000'; END IF;
  SELECT least(artifact.retain_until,rp.valid_until,k.valid_until,ks.valid_until,s.not_after) INTO source_deadline
   FROM private.acquisition_evidence_verification_keys k
   JOIN private.acquisition_contract_verification_key_scopes ks ON ks.workspace_id=k.workspace_id AND ks.key_id=k.id AND ks.purpose=artifact.purpose
   JOIN private.acquisition_evidence_policies rp ON rp.workspace_id=k.workspace_id AND rp.id=artifact.retention_policy_id
   JOIN public.workspace_memberships m ON m.workspace_id=k.workspace_id AND m.user_id=verification.actor_id
   JOIN public.profiles profile ON profile.id=m.user_id JOIN auth.sessions s ON s.id=verification.session_id AND s.user_id=m.user_id
   WHERE k.id=verification.key_id AND k.workspace_id=p_workspace FOR SHARE OF k,ks,rp,m,profile,s;
  IF source_deadline IS NULL THEN RAISE EXCEPTION 'Title source authority missing' USING ERRCODE='55000'; END IF;
  sources:=sources||jsonb_build_array(jsonb_build_object('artifact_id',source_id,'source_version',artifact.contract_version,
   'verification_id',verification.id,'sha256',artifact.expected_sha256,'purpose',artifact.purpose,'expires_at',source_deadline));
  deadline:=least(deadline,source_deadline);
 END LOOP;
 checked:=clock_timestamp();
 IF authority.session_expires IS NOT NULL AND authority.session_expires<=checked THEN RAISE EXCEPTION 'Title session expired' USING ERRCODE='42501'; END IF;
 FOR bound IN SELECT value FROM jsonb_array_elements(sources) LOOP
  IF (bound->>'expires_at')::timestamptz<=checked OR NOT private.contract_review_evidence_current(p_workspace,p_contract,
   (bound->>'source_version')::integer,(bound->>'artifact_id')::uuid,(bound->>'verification_id')::uuid,
   bound->>'sha256',bound->>'purpose',checked) THEN
   RAISE EXCEPTION 'Title source authority changed while waiting' USING ERRCODE='55000'; END IF;
 END LOOP;
 -- The caller must recheck these exact sources after any subsequent waits and
 -- independently bind execution/deadline/reviewer/freshness policy authority.
 RETURN jsonb_build_object('sources',sources,'checked_at',checked,'expires_at',least(deadline,authority.session_expires),
  'legal_review_approved',false,'title_clearance_confirmed',false,'execution_authorized',false);
END $function$

CREATE OR REPLACE FUNCTION private.revoke_acquisition_evidence(p_id uuid, p_workspace uuid, p_campaign uuid, p_artifact uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE saved public.acquisition_evidence_revocations%ROWTYPE; actor_updated timestamptz; session_expires timestamptz; fingerprint text;
BEGIN
 IF auth.jwt()->>'aal' IS DISTINCT FROM 'aal2' OR coalesce(private.acquisition_role(p_workspace),'') NOT IN ('owner','admin') THEN
  RAISE EXCEPTION 'Evidence revocation authority required' USING ERRCODE='42501'; END IF;
 IF p_id IS NULL OR p_campaign IS NULL OR p_artifact IS NULL OR p_reason IS NULL OR length(trim(p_reason)) NOT BETWEEN 20 AND 2000 THEN
  RAISE EXCEPTION 'Documented revocation required' USING ERRCODE='22023'; END IF;
 PERFORM 1 FROM public.workspaces WHERE id=p_workspace AND status='active' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Workspace unavailable' USING ERRCODE='42501'; END IF;
 SELECT m.updated_at,s.not_after INTO actor_updated,session_expires FROM public.workspace_memberships m JOIN public.profiles p ON p.id=m.user_id
 JOIN auth.sessions s ON s.user_id=p.id WHERE m.workspace_id=p_workspace AND m.user_id=auth.uid() AND m.status='active'
  AND m.role IN ('owner','admin') AND p.status='approved' AND s.id::text=auth.jwt()->>'session_id'
  AND (s.not_after IS NULL OR s.not_after>clock_timestamp()) FOR SHARE OF m,p,s;
 IF NOT FOUND THEN RAISE EXCEPTION 'Evidence revocation authority changed' USING ERRCODE='42501'; END IF;
 fingerprint:=encode(sha256(convert_to(jsonb_build_array(p_workspace,p_campaign,p_artifact,p_reason,auth.uid())::text,'UTF8')),'hex');
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-revocation:'||p_id::text,0));
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-artifact:'||p_artifact::text,0));
 IF session_expires IS NOT NULL AND session_expires<=clock_timestamp() THEN RAISE EXCEPTION 'Evidence session expired' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.acquisition_evidence_artifacts WHERE workspace_id=p_workspace AND campaign_id=p_campaign AND id=p_artifact;
 IF NOT FOUND THEN RAISE EXCEPTION 'Evidence artifact unavailable' USING ERRCODE='42501'; END IF;
 SELECT * INTO saved FROM public.acquisition_evidence_revocations WHERE id=p_id;
 IF FOUND THEN
  IF saved.request_hash IS DISTINCT FROM fingerprint THEN RAISE EXCEPTION 'Revocation request conflict' USING ERRCODE='23505'; END IF;
  RETURN jsonb_build_object('revocation_id',saved.id,'artifact_id',saved.artifact_id,'workspace_id',saved.workspace_id,'duplicate',true,'execution_authorized',false);
 END IF;
 INSERT INTO public.acquisition_evidence_revocations(id,workspace_id,campaign_id,artifact_id,reason,actor_id,actor_membership_updated_at,request_hash)
 VALUES(p_id,p_workspace,p_campaign,p_artifact,p_reason,auth.uid(),actor_updated,fingerprint) RETURNING * INTO saved;
 INSERT INTO public.audit_logs(entity_type,entity_id,action,actor,workspace_id,new_value)
 VALUES('acquisition_evidence',p_artifact::text,'revoked',auth.uid()::text,p_workspace,jsonb_build_object('revocation_id',p_id,'campaign_id',p_campaign,'execution_authorized',false));
 RETURN jsonb_build_object('revocation_id',saved.id,'artifact_id',saved.artifact_id,'workspace_id',saved.workspace_id,'duplicate',false,'execution_authorized',false);
END $function$

CREATE OR REPLACE FUNCTION private.revoke_contract_document(p_id uuid, p_workspace uuid, p_contract uuid, p_version integer, p_artifact uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE saved public.acquisition_evidence_revocations%ROWTYPE; authority record; fingerprint text;
BEGIN
 IF p_id IS NULL OR p_artifact IS NULL OR p_reason IS NULL OR length(trim(p_reason)) NOT BETWEEN 20 AND 2000 THEN
  RAISE EXCEPTION 'Documented revocation required' USING ERRCODE='22023'; END IF;
 SELECT * INTO authority FROM private.lock_contract_document_context(p_workspace,p_contract,p_version,ARRAY['owner','admin']);
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-revocation:'||p_id::text,0));
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-artifact:'||p_artifact::text,0));
 IF authority.session_expires IS NOT NULL AND authority.session_expires<=clock_timestamp() THEN
  RAISE EXCEPTION 'Document session expired' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.acquisition_evidence_artifacts WHERE workspace_id=p_workspace AND contract_id=p_contract AND contract_version=p_version AND id=p_artifact AND campaign_id IS NULL;
 IF NOT FOUND THEN RAISE EXCEPTION 'Contract document unavailable' USING ERRCODE='42501'; END IF;
 fingerprint:=encode(sha256(convert_to(jsonb_build_array('contract_document',p_workspace,p_contract,p_version,p_artifact,p_reason,auth.uid())::text,'UTF8')),'hex');
 SELECT * INTO saved FROM public.acquisition_evidence_revocations WHERE id=p_id;
 IF FOUND THEN
  IF saved.request_hash IS DISTINCT FROM fingerprint THEN RAISE EXCEPTION 'Revocation request conflict' USING ERRCODE='23505'; END IF;
  RETURN jsonb_build_object('revocation_id',saved.id,'artifact_id',saved.artifact_id,'workspace_id',saved.workspace_id,'duplicate',true,'execution_authorized',false);
 END IF;
 INSERT INTO public.acquisition_evidence_revocations(id,workspace_id,contract_id,contract_version,artifact_id,reason,actor_id,actor_membership_updated_at,request_hash)
 VALUES(p_id,p_workspace,p_contract,p_version,p_artifact,p_reason,auth.uid(),authority.actor_updated,fingerprint) RETURNING * INTO saved;
 INSERT INTO public.audit_logs(entity_type,entity_id,action,actor,workspace_id,new_value)
 VALUES('acquisition_contract_document',p_artifact::text,'revoked',auth.uid()::text,p_workspace,
  jsonb_build_object('revocation_id',p_id,'contract_id',p_contract,'contract_version',p_version,'execution_authorized',false));
 RETURN jsonb_build_object('revocation_id',saved.id,'artifact_id',saved.artifact_id,'workspace_id',saved.workspace_id,'duplicate',false,'execution_authorized',false);
END $function$

CREATE OR REPLACE FUNCTION private.save_contract_terms(p_id uuid, p_workspace uuid, p_contract uuid, p_expected_version integer, p_terms jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE authority record; saved public.acquisition_contract_versions%ROWTYPE; source jsonb; artifact public.acquisition_evidence_artifacts%ROWTYPE;
 scan public.acquisition_evidence_verifications%ROWTYPE; manifest jsonb; active boolean; stamped timestamptz; new_version integer;
BEGIN
 IF p_id IS NULL OR p_expected_version IS NULL OR p_expected_version NOT BETWEEN 1 AND 2147483646 OR NOT private.valid_contract_terms(p_terms) THEN
  RAISE EXCEPTION 'Exact sourced draft terms required' USING ERRCODE='22023'; END IF;
 SELECT * INTO authority FROM private.lock_contract_document_context(p_workspace,p_contract,p_expected_version,ARRAY['owner','admin','operator']);
 PERFORM pg_advisory_xact_lock(hashtextextended('contract-terms-request:'||p_id::text,0));
 manifest:=jsonb_build_object('workspace_id',p_workspace,'contract_id',p_contract,'expected_version',p_expected_version,'terms',p_terms);
 IF authority.session_expires IS NOT NULL AND authority.session_expires<=clock_timestamp() THEN RAISE EXCEPTION 'Terms session expired' USING ERRCODE='42501'; END IF;
 SELECT * INTO saved FROM public.acquisition_contract_versions WHERE id=p_id;
 IF FOUND THEN
  IF saved.workspace_id IS DISTINCT FROM p_workspace OR saved.deal_id IS DISTINCT FROM p_contract OR saved.actor_id IS DISTINCT FROM auth.uid() OR saved.request IS DISTINCT FROM manifest THEN
   RAISE EXCEPTION 'Terms request conflict' USING ERRCODE='23505'; END IF;
  RETURN jsonb_build_object('request_id',p_id,'workspace_id',p_workspace,'contract_id',p_contract,'version',saved.version,'status','draft','duplicate',true,'execution_authorized',false);
 END IF;
 SELECT enabled INTO active FROM private.acquisition_activation WHERE singleton FOR SHARE;
 IF active IS DISTINCT FROM true OR NOT EXISTS(SELECT 1 FROM public.deals WHERE workspace_id=p_workspace AND id=p_contract AND acquisition_version=p_expected_version AND acquisition_status='draft') THEN
  RAISE EXCEPTION 'Current active draft required' USING ERRCODE='55000'; END IF;
 new_version:=p_expected_version+1;
 -- Artifact ordering matches shared scan/revocation locks and avoids cross-source inversions.
 FOR source IN SELECT value FROM jsonb_array_elements(p_terms->'sources') ORDER BY (value->>'artifact_id')::uuid,value->>'term' LOOP
  IF (source->>'artifact_version')::integer>p_expected_version THEN RAISE EXCEPTION 'Future term source denied' USING ERRCODE='22023'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('evidence-artifact:'||(source->>'artifact_id')::uuid::text,0));
  SELECT * INTO artifact FROM public.acquisition_evidence_artifacts WHERE workspace_id=p_workspace AND contract_id=p_contract AND contract_version=(source->>'artifact_version')::integer
   AND id=(source->>'artifact_id')::uuid AND expected_sha256=source->>'sha256' AND campaign_id IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'Exact same-contract source unavailable' USING ERRCODE='42501'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('evidence-bytes:'||p_workspace::text||':'||artifact.expected_sha256,0));
  SELECT * INTO scan FROM public.acquisition_evidence_verifications WHERE workspace_id=p_workspace AND artifact_id=artifact.id ORDER BY created_at DESC,id DESC LIMIT 1;
  IF NOT FOUND THEN RAISE EXCEPTION 'Verified source required' USING ERRCODE='55000'; END IF;
  PERFORM 1 FROM private.acquisition_evidence_verification_keys k
   JOIN private.acquisition_contract_verification_key_scopes ks ON ks.workspace_id=k.workspace_id AND ks.key_id=k.id AND ks.purpose=artifact.purpose
   JOIN private.acquisition_evidence_policies rp ON rp.workspace_id=k.workspace_id AND rp.id=artifact.retention_policy_id
   JOIN public.workspace_memberships m ON m.workspace_id=k.workspace_id AND m.user_id=scan.actor_id
   JOIN public.profiles profile ON profile.id=m.user_id JOIN auth.sessions sess ON sess.id=scan.session_id AND sess.user_id=m.user_id
   WHERE k.workspace_id=p_workspace AND k.id=scan.key_id FOR SHARE OF k,ks,rp,m,profile,sess;
  IF NOT private.contract_review_evidence_current(p_workspace,p_contract,artifact.contract_version,artifact.id,scan.id,artifact.expected_sha256,artifact.purpose,clock_timestamp()) THEN
   RAISE EXCEPTION 'Current verified source required' USING ERRCODE='55000'; END IF;
 END LOOP;
 stamped:=clock_timestamp();
 IF authority.session_expires IS NOT NULL AND authority.session_expires<=stamped THEN RAISE EXCEPTION 'Terms session expired' USING ERRCODE='42501'; END IF;
 -- Recheck every source after all lock waits, including expired earlier sources.
 FOR source IN SELECT * FROM jsonb_array_elements(p_terms->'sources') LOOP
  SELECT * INTO artifact FROM public.acquisition_evidence_artifacts WHERE id=(source->>'artifact_id')::uuid;
  SELECT * INTO scan FROM public.acquisition_evidence_verifications WHERE workspace_id=p_workspace AND artifact_id=artifact.id ORDER BY created_at DESC,id DESC LIMIT 1;
  IF NOT private.contract_review_evidence_current(p_workspace,p_contract,artifact.contract_version,artifact.id,scan.id,artifact.expected_sha256,artifact.purpose,stamped) THEN
   RAISE EXCEPTION 'Source authority expired while waiting' USING ERRCODE='55000'; END IF;
 END LOOP;
 INSERT INTO public.acquisition_contract_versions(id,workspace_id,deal_id,version,status,request,actor_id,created_at,terms,previous_version,session_id)
 VALUES(p_id,p_workspace,p_contract,new_version,'draft',manifest,auth.uid(),stamped,p_terms,p_expected_version,(auth.jwt()->>'session_id')::uuid);
 FOR source IN SELECT * FROM jsonb_array_elements(p_terms->'sources') LOOP
  SELECT * INTO scan FROM public.acquisition_evidence_verifications WHERE workspace_id=p_workspace AND artifact_id=(source->>'artifact_id')::uuid ORDER BY created_at DESC,id DESC LIMIT 1;
  INSERT INTO public.acquisition_contract_term_sources(workspace_id,contract_id,contract_version,term,artifact_version,artifact_id,verification_id,sha256,locator)
  VALUES(p_workspace,p_contract,new_version,source->>'term',(source->>'artifact_version')::integer,(source->>'artifact_id')::uuid,scan.id,source->>'sha256',source->>'locator');
 END LOOP;
 UPDATE public.deals SET acquisition_version=new_version WHERE workspace_id=p_workspace AND id=p_contract AND acquisition_version=p_expected_version;
 INSERT INTO public.audit_logs(entity_type,entity_id,action,actor,workspace_id,new_value)
 VALUES('acquisition_contract_terms',p_id::text,'prepared',auth.uid()::text,p_workspace,jsonb_build_object('contract_id',p_contract,'version',new_version,'previous_version',p_expected_version,'source_count',jsonb_array_length(p_terms->'sources'),'execution_authorized',false));
 RETURN jsonb_build_object('request_id',p_id,'workspace_id',p_workspace,'contract_id',p_contract,'version',new_version,'status','draft','duplicate',false,'execution_authorized',false);
END $function$

CREATE OR REPLACE FUNCTION private.signature_review_candidate(p_workspace uuid, p_contract uuid, p_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE state jsonb; checked timestamptz; status_name text; deadline timestamptz;
 basis public.acquisition_contract_reviews%ROWTYPE; prior public.acquisition_signature_reviews%ROWTYPE;
 policy private.acquisition_signature_policies%ROWTYPE; candidate jsonb:=NULL; withdrawal jsonb:=NULL;
BEGIN
 -- Reuse current owner/admin MFA, session, membership and retained-version access.
 state:=private.signature_review_state(p_workspace,p_contract,p_version);
 SELECT * INTO basis FROM public.acquisition_contract_reviews WHERE workspace_id=p_workspace AND contract_id=p_contract
  AND contract_version=p_version AND kind='contract_review' ORDER BY sequence DESC LIMIT 1;
 SELECT * INTO policy FROM private.acquisition_signature_policies WHERE workspace_id=p_workspace AND contract_id=p_contract
  AND contract_version=p_version AND reviewer_id=auth.uid() AND basis_policy_id=basis.policy_id
  AND artifact_id=basis.artifact_id AND source_version=basis.source_version AND sha256=basis.sha256
  AND revoked_at IS NULL AND valid_from<=clock_timestamp() AND clock_timestamp()<valid_until
  ORDER BY valid_from DESC,id DESC LIMIT 1;
 -- Refresh state after lookup; withdrawals always bind the actual latest decision.
 state:=private.signature_review_state(p_workspace,p_contract,p_version);
 checked:=(state->>'checked_at')::timestamptz;
 SELECT * INTO prior FROM public.acquisition_signature_reviews WHERE id=(state->>'review_id')::uuid
  AND workspace_id=p_workspace AND contract_id=p_contract AND contract_version=p_version;
 IF prior.status='approved' AND prior.actor_id=auth.uid() AND prior.sequence<2147483647 THEN
  withdrawal:=jsonb_build_object('review_id',prior.id,'basis_review_id',prior.basis_review_id,
   'policy_id',prior.policy_id,'expected_sequence',prior.sequence);
 END IF;
 IF NOT EXISTS(SELECT 1 FROM private.acquisition_activation WHERE singleton AND enabled) THEN status_name:='paused';
 ELSIF NOT EXISTS(SELECT 1 FROM public.deals WHERE workspace_id=p_workspace AND id=p_contract AND acquisition_version=p_version AND acquisition_status='draft') THEN status_name:='contract_unavailable';
 ELSIF (state->>'sequence')::integer>=2147483647 THEN status_name:='history_limit_reached';
 ELSIF basis.id IS NULL OR NOT private.signature_basis_current(p_workspace,p_contract,p_version,basis.id,checked) THEN status_name:='contract_review_required';
 ELSIF policy.id IS NULL OR policy.revoked_at IS NOT NULL OR NOT(policy.valid_from<=checked AND checked<policy.valid_until) THEN status_name:='reviewer_policy_required';
 ELSE
  SELECT least(checked+make_interval(secs=>policy.max_review_seconds),policy.valid_until,basis.expires_at,
   release_session.not_after,review_session.not_after,basis_policy.valid_until,a.retain_until,retention.valid_until,
   k.valid_until,ks.valid_until,scan_session.not_after) INTO deadline
   FROM public.acquisition_evidence_artifacts a
   JOIN public.acquisition_evidence_verifications scan ON scan.workspace_id=a.workspace_id AND scan.artifact_id=a.id AND scan.id=basis.verification_id
   JOIN private.acquisition_evidence_policies retention ON retention.workspace_id=a.workspace_id AND retention.id=a.retention_policy_id
   JOIN private.acquisition_evidence_verification_keys k ON k.workspace_id=scan.workspace_id AND k.id=scan.key_id
   JOIN private.acquisition_contract_verification_key_scopes ks ON ks.workspace_id=k.workspace_id AND ks.key_id=k.id AND ks.purpose=a.purpose
   JOIN private.acquisition_contract_review_policies basis_policy ON basis_policy.workspace_id=a.workspace_id AND basis_policy.id=basis.policy_id
   JOIN auth.sessions scan_session ON scan_session.id=scan.session_id AND scan_session.user_id=scan.actor_id
   JOIN auth.sessions review_session ON review_session.id=basis.session_id AND review_session.user_id=basis.actor_id
   JOIN auth.sessions release_session ON release_session.id::text=auth.jwt()->>'session_id' AND release_session.user_id=auth.uid()
   WHERE a.workspace_id=p_workspace AND a.contract_id=p_contract AND a.contract_version=basis.source_version AND a.id=basis.artifact_id;
  IF deadline IS NULL OR deadline<=clock_timestamp() THEN status_name:='contract_review_required';
  ELSE
   status_name:='ready_for_human_review';
   candidate:=jsonb_build_object('basis_review_id',basis.id,'artifact_id',basis.artifact_id,'source_version',basis.source_version,
    'sha256',basis.sha256,'reviewed_at',basis.created_at,'policy_id',policy.id,
    'expected_sequence',(state->>'sequence')::integer,'max_expires_at',deadline);
  END IF;
 END IF;
 RETURN jsonb_build_object('workspace_id',p_workspace,'contract_id',p_contract,'contract_version',p_version,
  'status',status_name,'candidate',candidate,'withdrawal',withdrawal,'current_review',state,'checked_at',checked,'execution_authorized',false);
END $function$

CREATE OR REPLACE FUNCTION private.title_review_candidate(p_workspace uuid, p_contract uuid, p_version integer, p_artifact uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE checked timestamptz:=statement_timestamp(); state jsonb; status_name text; source_ref record;
 artifact public.acquisition_evidence_artifacts%ROWTYPE; scan public.acquisition_evidence_verifications%ROWTYPE;
 policy private.acquisition_contract_review_policies%ROWTYPE; prior public.acquisition_contract_reviews%ROWTYPE;
 execution public.acquisition_contract_transitions%ROWTYPE; executed public.acquisition_contract_reviews%ROWTYPE;
 deadline timestamptz; approval_deadline timestamptz; calendar_supported boolean:=false;
 candidate jsonb:=NULL; resolution jsonb:=NULL; withdrawal jsonb:=NULL;
BEGIN
 state:=private.title_review_state(p_workspace,p_contract,p_version);
 SELECT * INTO prior FROM public.acquisition_contract_reviews WHERE workspace_id=p_workspace AND contract_id=p_contract
  AND contract_version=p_version AND kind='title_findings' ORDER BY sequence DESC LIMIT 1;
 IF prior.status IN ('approved','requires_resolution') AND prior.actor_id=auth.uid() AND prior.sequence<2147483647 THEN
  withdrawal:=jsonb_build_object('review_id',prior.id,'artifact_id',prior.artifact_id,'source_version',prior.source_version,
   'verification_id',prior.verification_id,'policy_id',prior.policy_id,'expected_sequence',prior.sequence,'original_status',prior.status);
 END IF;
 -- A null selection can still recover/withdraw the latest original decision.
 IF p_artifact IS NOT NULL THEN
  SELECT * INTO source_ref FROM private.contract_document_reference(p_workspace,p_contract,p_version,p_artifact);
  IF NOT FOUND THEN RAISE EXCEPTION 'Title report reference unavailable' USING ERRCODE='42501'; END IF;
  SELECT * INTO artifact FROM public.acquisition_evidence_artifacts WHERE workspace_id=p_workspace AND contract_id=p_contract
   AND contract_version=source_ref.source_version AND id=p_artifact AND purpose='title_report' AND campaign_id IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'Original title report unavailable' USING ERRCODE='42501'; END IF;
  SELECT * INTO scan FROM public.acquisition_evidence_verifications WHERE workspace_id=p_workspace AND artifact_id=p_artifact ORDER BY created_at DESC,id DESC LIMIT 1;
 END IF;
 SELECT * INTO policy FROM private.acquisition_contract_review_policies WHERE workspace_id=p_workspace AND kind='title_findings'
  AND purpose='title_report' AND reviewer_id=auth.uid() AND revoked_at IS NULL AND valid_from<=checked AND checked<valid_until
  ORDER BY valid_from DESC,id DESC LIMIT 1;
 SELECT * INTO execution FROM public.acquisition_contract_transitions WHERE workspace_id=p_workspace AND contract_id=p_contract
  AND contract_version=p_version AND sequence=2 AND recorded_status='executed';
 IF NOT EXISTS(SELECT 1 FROM private.acquisition_activation WHERE singleton AND enabled) THEN status_name:='paused';
 ELSIF NOT EXISTS(SELECT 1 FROM public.deals WHERE workspace_id=p_workspace AND id=p_contract AND acquisition_version=p_version AND acquisition_status='title_review')
  OR execution.id IS NULL OR NOT EXISTS(SELECT 1 FROM public.acquisition_contract_transitions WHERE workspace_id=p_workspace AND contract_id=p_contract
   AND contract_version=p_version AND sequence=3 AND recorded_status='title_review' AND execution_review_id=execution.execution_review_id) THEN status_name:='contract_unavailable';
 ELSIF coalesce(prior.sequence,0)>=2147483647 THEN status_name:='history_limit_reached';
 ELSIF p_artifact IS NULL THEN status_name:='document_required';
 ELSIF policy.id IS NULL THEN status_name:='reviewer_policy_required';
 ELSIF source_ref.link_revoked OR scan.id IS NULL OR NOT private.contract_review_evidence_current(p_workspace,p_contract,source_ref.source_version,p_artifact,scan.id,artifact.expected_sha256,'title_report',checked) THEN status_name:='evidence_review_required';
 ELSE
  SELECT least(artifact.retain_until,rp.valid_until,k.valid_until,ks.valid_until,scanner_session.not_after,
   reviewer_session.not_after,policy.valid_until,checked+make_interval(secs=>policy.max_review_seconds)) INTO deadline
  FROM private.acquisition_evidence_verification_keys k
  JOIN private.acquisition_contract_verification_key_scopes ks ON ks.workspace_id=k.workspace_id AND ks.key_id=k.id AND ks.purpose='title_report'
  JOIN private.acquisition_evidence_policies rp ON rp.workspace_id=k.workspace_id AND rp.id=artifact.retention_policy_id
  JOIN auth.sessions scanner_session ON scanner_session.id=scan.session_id AND scanner_session.user_id=scan.actor_id
  JOIN auth.sessions reviewer_session ON reviewer_session.id=(auth.jwt()->>'session_id')::uuid AND reviewer_session.user_id=auth.uid()
  WHERE k.workspace_id=p_workspace AND k.id=scan.key_id;
  IF deadline IS NULL OR deadline<=checked THEN status_name:='evidence_review_required';
  ELSE
   resolution:=jsonb_build_object('artifact_id',p_artifact,'source_version',source_ref.source_version,'verification_id',scan.id,
    'sha256',artifact.expected_sha256,'policy_id',policy.id,'available_until',deadline,'expected_sequence',(state->>'sequence')::integer);
   SELECT * INTO executed FROM public.acquisition_contract_reviews WHERE id=private.acquisition_review_anchor_head(p_workspace,p_contract,p_version,execution.execution_review_id,checked);
   calendar_supported:=policy.title_report_max_age_days IS NOT NULL AND EXISTS(SELECT 1 FROM pg_timezone_names WHERE name=policy.title_report_timezone);
   IF NOT private.execution_review_current(executed.id,checked) THEN status_name:='execution_review_required';
   ELSIF policy.title_report_max_age_seconds IS NULL AND NOT calendar_supported THEN status_name:='report_freshness_policy_required';
   ELSE
    approval_deadline:=least(deadline,executed.expires_at);
    IF approval_deadline<=checked THEN status_name:='execution_review_required';
    ELSE
     status_name:='ready_for_human_review';
     candidate:=resolution||jsonb_build_object('max_expires_at',approval_deadline,'report_policy',jsonb_build_object(
      'max_age_seconds',policy.title_report_max_age_seconds,
      'max_age_days',CASE WHEN calendar_supported THEN policy.title_report_max_age_days END,
      'timezone',CASE WHEN calendar_supported THEN policy.title_report_timezone END));
    END IF;
   END IF;
  END IF;
 END IF;
 RETURN jsonb_build_object('workspace_id',p_workspace,'contract_id',p_contract,'contract_version',p_version,'artifact_id',p_artifact,
  'status',status_name,'candidate',candidate,'resolution',resolution,'withdrawal',withdrawal,
  'current_review',state,'checked_at',checked,'execution_authorized',false);
END $function$
